se\n            return None\n\n    def _build_all(entries: list | tuple) -> tuple[ExitCondition, ...]:\n        return tuple(built for built in (_build(entry) for entry in entries) if built)\n\n    if isinstance(raw_value, list | tuple):\n        return _build_all(raw_value)\n    if not isinstance(raw_value, str):\n        return ()\n    text = raw_value.strip()\n    if not text:\n        if strict:\n            raise ValueError(f\"{field_label} must be an explicit JSON array; got a blank value.\")\n        return ()\n    decoded = _decode_object_array(text, field_label=field_label, strict=strict)\n    if decoded is not None:\n        return _build_all(decoded)\n\n    conditions: list[ExitCondition] = []\n    for condition_str in text.split(\"|\"):\n        condition_str = condition_str.strip()\n        if not condition_str:\n            continue\n        parts = condition_str.split(\":\")\n        if len(parts) < 3:\n            continue\n        name = parts[0].strip()\n        description = parts[1].strip()\n        criteria = \":\".join(parts[2:]).strip()\n        if not name or not description or not criteria:\n            continue\n        conditions.append(\n            ExitCondition(\n                name=name,\n                description=description,\n                evaluation_criteria=criteria,\n            )\n        )\n    return tuple(conditions)\n\n\ndef _parse_ontology_fields(raw_value: object, *, strict: bool = False) -> tuple[OntologyField, ...]:\n    \"\"\"Parse ONTOLOGY_FIELDS from JSON object arrays or the legacy pipe list.\n\n    Mirrors the evaluation-principle and exit-condition parsers (#1729): the\n    extraction format requests a single-line JSON array of ``{\"name\", \"type\",\n    \"description\"}`` objects (the model field spelling ``field_type`` is\n    accepted too, and an optional boolean ``required`` is honored) so colons\n    and pipes inside the data survive. Strict mode raises on anything else so\n    the retry path reformats; lenient mode keeps the historical\n    ``name:type:description`` split where the description absorbs any further\n    colons, skips malformed entries, and never raises.\n    \"\"\"\n    field_label = \"ONTOLOGY_FIELDS\"\n\n    def _build(entry: object) -> OntologyField | None:\n        if isinstance(entry, OntologyField):\n            return entry\n        if not isinstance(entry, dict):\n            if strict:\n                raise ValueError(\n                    f\"{field_label} entries must be JSON objects; got \"\n                    f\"{type(entry).__name__}: {entry!r}\"\n                )\n            return None\n        try:\n            required = entry.get(\"required\", True)\n            if not isinstance(required, bool):\n                raise ValueError(\n                    f\"{field_label} entry field 'required' must be a boolean; got {required!r}.\"\n                )\n            return OntologyField(\n                name=_require_object_string(entry, \"name\", field_label=field_label),\n                field_type=_require_object_string(\n                    entry, \"type\", field_label=field_label, aliases=(\"field_type\",)\n                ),\n                description=_require_object_string(entry, \"description\", field_label=field_label),\n                required=required,\n            )\n        except (ValueError, TypeError, PydanticValidationError):\n            if strict:\n                raise\n            return None\n\n    def _build_all(entries: list | tuple) -> tuple[OntologyField, ...]:\n        return tuple(built for built in (_build(entry) for entry in entries) if built)\n\n    if isinstance(raw_value, list | tuple):\n        return _build_all(raw_value)\n    if not isinstance(raw_value, str):\n        return ()\n    text = raw_value.strip()\n    if not text:\n        if strict:\n            raise ValueError(\n                f\"{field_label} must be a single-line JSON array of objects; \"\n                \"use [] for an intentionally empty list.\"\n            )\n        return ()\n    decoded = _decode_object_array(text, field_label=field_label, strict=strict)\n    if decoded is not None:\n        return _build_all(decoded)\n\n    fields: list[OntologyField] = []\n    for field_str in text.split(\"|\"):\n        field_str = field_str.strip()\n        if not field_str:\n            continue\n        parts = field_str.split(\":\")\n        if len(parts) < 3:\n            continue\n        name = parts[0].strip()\n        field_type = parts[1].strip()\n        description = \":\".join(parts[2:]).strip()\n        if not name or not field_type or not description:\n            # Stored legacy data has no retry path; skip malformed entries\n            # instead of raising at model construction.\n            continue\n        fields.append(OntologyField(name=name, field_type=field_type, description=description))\n    return tuple(fields)\n\n\ndef _parse_context_references(\n    raw_value: object, *, strict: bool = False\n) -> tuple[ContextReference, ...]:\n    \"\"\"Parse CONTEXT_REFERENCES from JSON object arrays or the legacy pipe list.\n\n    Mirrors the other #1729 object-array parsers: the extraction format\n    requests a single-line JSON array of ``{\"path\", \"role\", \"summary\"}``\n    objects — ``summary`` is optional and defaults to empty — so colons in\n    paths (e.g. Windows drives) and colons/pipes in summaries survive as\n    data. Strict mode raises on anything else so the retry path reformats;\n    lenient mode keeps the historical ``path:role:summary`` split where the\n    summary absorbs further colons, skips malformed entries, and never\n    raises.\n    \"\"\"\n    field_label = \"CONTEXT_REFERENCES\"\n\n    def _build(entry: object) -> ContextReference | None:\n        if isinstance(entry, ContextReference):\n            return entry\n        if not isinstance(entry, dict):\n            if strict:\n                raise ValueError(\n                    f\"{field_label} entries must be JSON objects; got \"\n                    f\"{type(entry).__name__}: {entry!r}\"\n                )\n            return None\n        try:\n            summary = entry.get(\"summary\", \"\")\n            if not isinstance(summary, str):\n                raise ValueError(\n                    f\"{field_label} entry field 'summary' must be a string; got {summary!r}.\"\n                )\n            return ContextReference(\n                path=_require_object_string(entry, \"path\", field_label=field_label),\n                role=_require_object_string(entry, \"role\", field_label=field_label),\n                summary=summary.strip(),\n            )\n        except (ValueError, TypeError, PydanticValidationError):\n            if strict:\n                raise\n            return None\n\n    def _build_all(entries: list | tuple) -> tuple[ContextReference, ...]:\n        return tuple(built for built in (_build(entry) for entry in entries) if built)\n\n    if isinstance(raw_value, list | tuple):\n        return _build_all(raw_value)\n    if not isinstance(raw_value, str):\n        return ()\n    text = raw_value.strip()\n    if not text:\n        if strict:\n            raise ValueError(\n                f\"{field_label} must be a single-line JSON array of objects; \"\n                \"use [] for an intentionally empty list.\"\n            )\n        return ()\n    decoded = _decode_object_array(text, field_label=field_label, strict=strict)\n    if decoded is not None:\n        return _build_all(decoded)\n\n    references: list[ContextReference] = []\n    for ref_str in text.split(\"|\"):\n        ref_str = ref_str.strip()\n        if not ref_str:\n            continue\n        parts = ref_str.split(\":\")\n        if len(parts) < 2:\n            continue\n        path = parts[0].strip()\n        role = parts[1].strip()\n        if not path or not role:\n            # Stored legacy data has no retry path; skip malformed entries\n            # instead of raising at model construction.\n            continue\n        references.append(\n            ContextReference(\n                path=path,\n                role=role,\n                summary=\":\".join(parts[2:]).strip() if len(parts) > 2 else \"\",\n            )\n        )\n    return tuple(references)\n\n\ndef _parse_acceptance_criteria_contracts(\n    raw_value: object,\n) -> tuple[AcceptanceCriterionSpec | str, ...]:\n    \"\"\"Parse legacy AC prose or structured AC success-contract lines.\"\"\"\n    if isinstance(raw_value, list | tuple):\n        parsed_entries: list[AcceptanceCriterionSpec | str] = []\n        for item in raw_value:\n            if isinstance(item, AcceptanceCriterionSpec):\n                parsed_entries.append(item)\n                continue\n            text = str(item).strip()\n            if text:\n                parsed_entries.append(text)\n        entries = tuple(parsed_entries)\n    elif isinstance(raw_value, str):\n        text = raw_value.strip()\n        if not text:\n            return ()\n        if \"\\nAC:\" in text or text.startswith(\"AC:\"):\n            entries = tuple(line.strip() for line in text.splitlines() if line.strip())\n        else:\n            entries = tuple(item.strip() for item in text.split(\"|\") if item.strip())\n    else:\n        return ()\n\n    parsed: list[AcceptanceCriterionSpec | str] = []\n    for entry in entries:\n        if isinstance(entry, AcceptanceCriterionSpec):\n            parsed.append(entry)\n            continue\n        if not entry.startswith(\"AC:\"):\n            parsed.append(entry)\n            continue\n        spec = _parse_acceptance_criterion_contract(entry)\n        parsed.append(spec if spec is not None else entry.removeprefix(\"AC:\").strip())\n    return tuple(parsed)\n\n\ndef _parse_acceptance_criterion_contract(line: str) -> AcceptanceCriterionSpec | None:\n    \"\"\"Parse one structured AC line, falling back to description-only on gaps.\"\"\"\n    if not line.startswith(\"AC:\"):\n        return None\n    body = line.removeprefix(\"AC:\").strip()\n    matches = _iter_outer_ac_field_markers(body)\n    description_end = matches[0].start if matches else len(body)\n    description = body[:description_end].strip()\n    if not description:\n        return None\n    fields: dict[str, object] = {\"description\": description}\n    seen_fields: set[str] = set()\n    for index, match in enumerate(matches):\n        normalized_key = match.name\n        if normalized_key in seen_fields:\n            raise ValueError(f\"Duplicate {normalized_key} field in acceptance criterion\")\n        seen_fields.add(normalized_key)\n        value_start = match.end\n        value_end = matches[index + 1].start if index + 1 < len(matches) else len(body)\n        normalized_value = body[value_start:value_end].strip(\" \")\n        if normalized_key == \"artifacts\" and not normalized_value:\n            raise ValueError(\"Empty artifacts field; use artifacts: NONE\")\n        if not normalized_value or normalized_value.upper() == \"NONE\":\n            continue\n        if normalized_key == \"verify\":\n            fields[\"verify_command\"] = normalized_value\n        elif normalized_key == \"artifacts\":\n            fields[\"expected_artifacts\"] = parse_expected_artifact_list(normalized_value)\n        elif normalized_key == \"expect\":\n            fields[\"output_assertion\"] = normalized_value\n    return AcceptanceCriterionSpec.model_validate(fields)\n\n\ndef _unsupported_verify_command_reason(command: str) -> str | None:\n    if \"\\n\" in command or \"\\r\" in command:\n        return \"verify_command must be a single-line command\"\n    if _contains_posix_heredoc_operator(command):\n        return \"verify_command uses heredoc/multiline shell syntax; use python -c or pytest instead\"\n    return None\n\n\ndef _contains_posix_heredoc_operator(command: str) -> bool:\n    \"\"\"Return whether shell code contains an active ``<<``/``<<-`` operator.\n\n    The delimiter is a POSIX shell word, so quoting may be backslash-based or\n    fragmented (``<<\\\\EOF``, ``<<E\"OF\"``). Looking for a delimiter spelling\n    with one regex is therefore bypassable. Instead, recognize the operator\n    in shell lexical context: quoted strings, comments, parameter expansion,\n    and arithmetic expansion cannot introduce a heredoc operator themselves.\n    Ordinary comparison text embedded in those contexts remains valid.\n    \"\"\"\n    quote: str | None = None\n    escaped = False\n    word_started = False\n    index = 0\n    while index < len(command):\n        char = command[index]\n        if quote == \"'\":\n            if char == \"'\":\n                quote = None\n            index += 1\n            continue\n        if escaped:\n            escaped = False\n            word_started = True\n            index += 1\n            continue\n        if char == \"\\\\\":\n            escaped = True\n            index += 1\n            continue\n        if quote == '\"':\n            if char == '\"':\n                quote = None\n                index += 1\n                continue\n            if char == \"$\" and index + 1 < len(command):\n                is_parameter = command[index + 1] == \"{\"\n                is_arithmetic = command.startswith(\"$((\", index)\n                if is_parameter or is_arithmetic:\n                    expansion_end = _posix_expansion_end(command, index)\n                    if expansion_end is not None:\n                        inner_start = index + (3 if is_arithmetic else 2)\n                        inner_end = expansion_end - (2 if is_arithmetic else 1)\n                        if _contains_nested_shell_substitution_heredoc(\n                            command[inner_start:inner_end]\n                        ):\n                            return True\n                        index = expansion_end\n                        continue\n            if (\n                char == \"$\"\n                and command.startswith(\"$(\", index)\n                and not command.startswith(\"$((\", index)\n            ):\n                expansion_end = _posix_expansion_end(command, index)\n                if expansion_end is not None:\n                    if _contains_posix_heredoc_operator(command[index + 2 : expansion_end - 1]):\n                        return True\n                    index = expansion_end\n                    continue\n            if char == \"`\":\n                substitution_end = _posix_backtick_substitution_end(command, index)\n                if substitution_end is None:\n                    return True\n                if _contains_posix_heredoc_operator(command[index + 1 : substitution_end - 1]):\n                    return True\n                index = substitution_end\n                continue\n            index += 1\n            continue\n        if char in {\"'\", '\"'}:\n            quote = char\n            word_started = True\n            index += 1\n            continue\n        if char == \"`\":\n            substitution_end = _posix_backtick_substitution_end(command, index)\n            if substitution_end is None:\n                return True\n            if _contains_posix_heredoc_operator(command[index + 1 : substitution_end - 1]):\n                return True\n            word_started = True\n            index = substitution_end\n            continue\n        if char == \"#\" and not word_started:\n            return False\n        if char == \"$\" and index + 1 < len(command):\n            is_parameter = command[index + 1] == \"{\"\n            is_arithmetic = command.startswith(\"$((\", index)\n            if is_parameter or is_arithmetic:\n                expansion_end = _posix_expansion_end(command, index)\n                if expansion_end is not None:\n                    inner_start = index + (3 if is_arithmetic else 2)\n                    inner_end = expansion_end - (2 if is_arithmetic else 1)\n                    if _contains_nested_shell_substitution_heredoc(command[inner_start:inner_end]):\n                        return True\n                    word_started = True\n                    index = expansion_end\n                    continue\n            if command[index + 1] == \"(\":\n                expansion_end = _posix_expansion_end(command, index)\n                if expansion_end is not None:\n                    if _contains_posix_heredoc_operator(command[index + 2 : expansion_end - 1]):\n                        return True\n                    word_started = True\n                    index = expansion_end\n                    continue\n        if char == \"<\" and index + 1 < len(command) and command[index + 1] == \"<\":\n            return True\n        if char.isspace() or char in \";|&()<>\":\n            word_started = False\n        else:\n            word_started = True\n        index += 1\n    return False\n\n\ndef _posix_backtick_substitution_end(value: str, index: int) -> int | None:\n    \"\"\"Return just past the next unescaped legacy command-substitution backtick.\"\"\"\n    if index >= len(value) or value[index] != \"`\":\n        return None\n    escaped = False\n    cursor = index + 1\n    while cursor < len(value):\n        char = value[cursor]\n        if escaped:\n            escaped = False\n        elif char == \"\\\\\":\n            escaped = True\n        elif char == \"`\":\n            return cursor + 1\n        cursor += 1\n    return None\n\n\ndef _contains_nested_shell_substitution_heredoc(value: str) -> bool:\n    \"\"\"Inspect only executable substitutions inside parameter/arithmetic text.\n\n    Raw ``<<`` in these frames is data or an arithmetic shift, not shell\n    redirection. Nested ``$()`` and legacy backticks execute shell code and\n    must therefore be scanned with the full heredoc detector.\n    \"\"\"\n    quote: str | None = None\n    escaped = False\n    index = 0\n    while index < len(value):\n        char = value[index]\n        if quote == \"'\":\n            if char == \"'\":\n                quote = None\n            index += 1\n            continue\n        if escaped:\n            escaped = False\n            index += 1\n            continue\n        if char == \"\\\\\":\n            escaped = True\n            index += 1\n            continue\n        if char == '\"':\n            quote = None if quote == '\"' else '\"'\n            index += 1\n            continue\n        if char == \"'\" and quote is None:\n            quote = \"'\"\n            index += 1\n            continue\n        if char == \"$\" and index + 1 < len(value) and value[index + 1] in \"({\":\n            expansion_end = _posix_expansion_end(value, index)\n            if expansion_end is not None:\n                is_arithmetic = value.startswith(\"$((\", index)\n                is_parameter = value[index + 1] == \"{\"\n                if is_arithmetic or is_parameter:\n                    inner_start = index + (3 if is_arithmetic else 2)\n                    inner_end = expansion_end - (2 if is_arithmetic else 1)\n                    if _contains_nested_shell_substitution_heredoc(value[inner_start:inner_end]):\n                        return True\n                elif _contains_posix_heredoc_operator(value[index + 2 : expansion_end - 1]):\n                    return True\n                index = expansion_end\n                continue\n        if char == \"`\":\n            substitution_end = _posix_backtick_substitution_end(value, index)\n            if substitution_end is None:\n                return True\n            if _contains_posix_heredoc_operator(value[index + 1 : substitution_end - 1]):\n                return True\n            index = substitution_end\n            continue\n        index += 1\n    return False\n\n\n@dataclass\nclass SeedGenerator:\n    \"\"\"Generator for creating immutable Seeds from interview state.\n\n    Transforms completed interviews with low ambiguity scores into\n    structured, immutable Seed specifications.\n\n    Example:\n        generator = SeedGenerator(llm_adapter=LiteLLMAdapter())\n\n        # Generate seed from interview\n        result = await generator.generate(\n            state=interview_state,\n            ambiguity_score=ambiguity_result,\n        )\n\n        if result.is_ok:\n            seed = result.value\n            # Save to file\n            save_result = await generator.save_seed(seed, Path(\"seed.yaml\"))\n\n    Note:\n        The model can be configured via OuroborosConfig.clarification.default_model\n        or passed directly to the constructor.\n    \"\"\"\n\n    llm_adapter: LLMAdapter\n    model: str | None = None\n    model_is_explicit: bool = field(default=False, init=False)\n    temperature: float = EXTRACTION_TEMPERATURE\n    max_tokens: int = 4096\n    output_dir: Path = field(default_factory=lambda: Path.home() / \".ouroboros\" / \"seeds\")\n\n    def __post_init__(self) -> None:\n        \"\"\"Ensure output directory exists.\"\"\"\n        self.model_is_explicit = self.model is not None\n        if self.model is None:\n            self.model = get_llm_model_for_role(\"seed_generation\")\n        self.output_dir.mkdir(parents=True, exist_ok=True)\n\n    async def generate(\n        self,\n        state: InterviewState,\n        ambiguity_score: AmbiguityScore,\n        parent_seed: Seed | None = None,\n        reflect_output: Any | None = None,\n        *,\n        force: bool = False,\n    ) -> Result[Seed, ValidationError | ProviderError]:\n        \"\"\"Generate an immutable Seed from interview state or reflect output.\n\n        Two modes:\n        - Gen 1 (reflect_output=None): Extract from interview, gate on ambiguity.\n        - Gen 2+ (reflect_output provided): Use refined ACs and ontology mutations\n          from ReflectEngine. Skip ambiguity gating.\n\n        When ``force=True``, the ambiguity threshold gate is bypassed but every\n        other validation (initial-context summary, extraction, build) still runs.\n        The real ``ambiguity_score.overall_score`` is recorded in metadata so\n        forced seeds carry truthful provenance.\n\n        Args:\n            state: Completed interview state.\n            ambiguity_score: The ambiguity score for the interview.\n            parent_seed: Optional parent seed for evolutionary lineage.\n            reflect_output: Optional ReflectOutput for Gen 2+ evolution.\n            force: When True, bypass the ambiguity threshold gate. The real\n                score is still stamped into ``SeedMetadata.ambiguity_score``.\n                Defaults to False (gate enforced).\n\n        Returns:\n            Result containing the generated Seed or error.\n        \"\"\"\n        # Gen 2+ path: use reflect output directly\n        if reflect_output is not None and parent_seed is not None:\n            return self.generate_from_reflect(parent_seed, reflect_output)\n\n        log.info(\n            \"seed.generation.started\",\n            interview_id=state.interview_id,\n            ambiguity_score=ambiguity_score.overall_score,\n        )\n\n        # Gate on ambiguity score (skipped when force=True)\n        if force:\n            log.warning(\n                \"seed.generation.ambiguity_gate_bypassed\",\n                interview_id=state.interview_id,\n                ambiguity_score=ambiguity_score.overall_score,\n                threshold=AMBIGUITY_THRESHOLD,\n            )\n        elif not ambiguity_score.is_ready_for_seed:\n            log.warning(\n                \"seed.generation.ambiguity_too_high\",\n                interview_id=state.interview_id,\n                ambiguity_score=ambiguity_score.overall_score,\n                threshold=AMBIGUITY_THRESHOLD,\n            )\n            return Result.err(\n                ValidationError(\n                    f\"Ambiguity score {ambiguity_score.overall_score:.2f} exceeds \"\n                    f\"threshold {AMBIGUITY_THRESHOLD}. Cannot generate Seed.\",\n                    field=\"ambiguity_score\",\n                    value=ambiguity_score.overall_score,\n                    details={\n                        \"threshold\": AMBIGUITY_THRESHOLD,\n                        \"interview_id\": state.interview_id,\n                    },\n                )\n            )\n\n        if initial_context_summary_missing(state):\n            return Result.err(\n                ValidationError(\n                    \"Initial context summary required before seed generation\",\n                    field=\"initial_context\",\n                    details={\"interview_id\": state.interview_id},\n                )\n            )\n\n        distillation = build_requirement_distillation(state)\n        preflight = apply_requirement_distillation({}, distillation)\n        reference_aware = is_reference_aware_distillation(distillation)\n        readiness = seed_readiness_details(\n            preflight.promotion,\n            require_promoted_acceptance_criteria=reference_aware,\n        )\n        if readiness[\"blockers\"]:\n            return Result.err(\n                ValidationError(\n                    \"Interview must be reopened before Seed generation\",\n                    field=\"requirement_distillation\",\n                    details=readiness,\n                )\n            )\n        state.requirement_distillation = distillation\n        if reference_aware:\n            return Result.ok(\n                build_promoted_reference_seed(\n                    state,\n                    distillation,\n                    ambiguity_score=ambiguity_score.overall_score,\n                    gate_forced=force,\n                )\n            )\n\n        # Extract structured requirements from interview\n        extraction_result = await self._extract_requirements(state)\n\n        if extraction_result.is_err:\n            return Result.err(extraction_result.error)\n\n        applied = apply_requirement_distillation(extraction_result.value, distillation)\n        if applied.promotion.blockers:\n            return Result.err(\n                ValidationError(\n                    \"Interview must be reopened before Seed generation\",\n                    field=\"requirement_distillation\",\n                    details=seed_readiness_details(applied.promotion),\n                )\n            )\n        requirements = applied.requirements\n        # Verbatim-anchor backstop (grounded-lateral RFC D6): re-append any\n        # user-committed promoted requirement the LLM extraction dropped or\n        # re-worded. This is the one chokepoint every entry path shares —\n        # interview, auto, and host-context all converge here or on the fully\n        # deterministic builders.\n        requirements, anchored_count = anchor_promoted_requirements(requirements, applied.promotion)\n        if anchored_count:\n            log.info(\n                \"seed.generation.anchor_backstop\",\n                interview_id=state.interview_id,\n                appended=anchored_count,\n            )\n\n        # Create metadata\n        metadata = SeedMetadata(\n            ambiguity_score=ambiguity_score.overall_score,\n            gate_forced=force,\n            interview_id=state.interview_id,\n            parent_seed_id=parent_seed.metadata.seed_id if parent_seed else None,\n        )\n\n        # Build the seed\n        try:\n            seed = self._build_seed(requirements, metadata)\n\n            log.info(\n                \"seed.generation.completed\",\n                interview_id=state.interview_id,\n                seed_id=seed.metadata.seed_id,\n                goal_length=len(seed.goal),\n                constraint_count=len(seed.constraints),\n                criteria_count=len(seed.acceptance_criteria),\n            )\n\n            return Result.ok(seed)\n\n        except Exception as e:\n            log.exception(\n                \"seed.generation.build_failed\",\n                interview_id=state.interview_id,\n                error=str(e),\n            )\n            return Result.err(\n                ValidationError(\n                    f\"Failed to build seed: {e}\",\n                    details={\"interview_id\": state.interview_id},\n                )\n            )\n\n    def generate_from_reflect(\n        self,\n        parent_seed: Seed,\n        reflect_output: Any,\n    ) -> Result[Seed, ValidationError | ProviderError]:\n        \"\"\"Generate a successor Seed while preserving structured AC authority.\n\n        Reflect applies ontology and identity-bearing prose deltas without\n        Gen-1 ambiguity gating. Mechanical AC contracts cross only explicit\n        keeps; description changes require a future replacement-contract patch.\n        \"\"\"\n        log.info(\n            \"seed.generation.from_reflect\",\n            parent_seed_id=parent_seed.metadata.seed_id,\n            mutation_count=len(reflect_output.ontology_mutations),\n        )\n\n        try:\n            # Apply ontology mutations to parent's schema\n            new_ontology = self._apply_mutations(\n                parent_seed.ontology_schema,\n                reflect_output.ontology_mutations,\n            )\n\n            metadata = SeedMetadata(\n                ambiguity_score=parent_seed.metadata.ambiguity_score,\n                interview_id=parent_seed.metadata.interview_id,\n                parent_seed_id=parent_seed.metadata.seed_id,\n            )\n\n            refined_patches = (\n                reflect_output.ac_patches if reflect_output.ac_patch_identity_explicit else None\n            )\n            seed = Seed(\n                goal=reflect_output.refined_goal,\n                task_type=parent_seed.task_type,\n                brownfield_context=parent_seed.brownfield_context,\n                constraints=reflect_output.refined_constraints,\n                ontology_schema=new_ontology,\n                evaluation_principles=parent_seed.evaluation_principles,\n                exit_conditions=parent_seed.exit_conditions,\n                metadata=metadata,\n                **evolve_seed_contract_fields(\n                    parent_seed, reflect_output.refined_acs, refined_patches\n                ),\n            )\n\n            log.info(\n                \"seed.generation.from_reflect.completed\",\n                seed_id=seed.metadata.seed_id,\n                parent_seed_id=parent_seed.metadata.seed_id,\n                field_count=len(new_ontology.fields),\n            )\n\n            return Result.ok(seed)\n\n        except Exception as e:\n            log.exception(\n                \"seed.generation.from_reflect.failed\",\n                parent_seed_id=parent_seed.metadata.seed_id,\n                error=str(e),\n            )\n            return Result.err(\n                ValidationError(\n                    f\"Failed to generate seed from reflect: {e}\",\n                    details={\"parent_seed_id\": parent_seed.metadata.seed_id},\n                )\n            )\n\n    def _apply_mutations(\n        self,\n        schema: OntologySchema,\n        mutations: tuple,\n    ) -> OntologySchema:\n        \"\"\"Apply ontology mutations to produce a new schema.\n\n        Args:\n            schema: The parent ontology schema.\n            mutations: Tuple of OntologyMutation instances.\n\n        Returns:\n            New OntologySchema with mutations applied.\n        \"\"\"\n        fields_by_name = {f.name: f for f in schema.fields}\n\n        for mutation in mutations:\n            action = str(mutation.action)\n            if action == \"add\" and mutation.field_name not in fields_by_name:\n                fields_by_name[mutation.field_name] = OntologyField(\n                    name=mutation.field_name,\n                    field_type=mutation.field_type or \"string\",\n                    description=mutation.description or mutation.reason,\n                )\n            elif action == \"modify\" and mutation.field_name in fields_by_name:\n                old = fields_by_name[mutation.field_name]\n                fields_by_name[mutation.field_name] = OntologyField(\n                    name=mutation.field_name,\n                    field_type=mutation.field_type or old.field_type,\n                    description=mutation.description or old.description,\n                    required=old.required,\n                )\n            elif action == \"remove\" and mutation.field_name in fields_by_name:\n                del fields_by_name[mutation.field_name]\n\n        return OntologySchema(\n            name=schema.name,\n            description=schema.description,\n            fields=tuple(fields_by_name.values()),\n        )\n\n    async def _extract_requirements(\n        self, state: InterviewState\n    ) -> Result[dict[str, Any], ProviderError]:\n        \"\"\"Extract structured requirements from interview using LLM.\n\n        Retries once with a clarified prompt on parse failure.\n\n        Args:\n            state: The interview state.\n\n        Returns:\n            Result containing extracted requirements dict or error.\n        \"\"\"\n        context = self._build_interview_context(state)\n        is_brownfield = (\n            state.is_brownfield\n            or bool(state.codebase_context.strip())\n            or bool(state.codebase_paths)\n        )\n        system_prompt = self._build_extraction_system_prompt()\n        user_prompt = self._build_extraction_user_prompt(context, is_brownfield=is_brownfield)\n\n        messages = [\n            Message(role=MessageRole.SYSTEM, content=system_prompt),\n            Message(role=MessageRole.USER, content=user_prompt),\n        ]\n\n        assert self.model is not None\n        config = CompletionConfig(\n            model=self.model,\n            role=\"seed_generation\",\n            model_is_explicit=self.model_is_explicit,\n            temperature=self.temperature,\n            max_tokens=self.max_tokens,\n        )\n\n        last_error = \"\"\n        last_response = \"\"\n\n        for attempt in range(_MAX_EXTRACTION_RETRIES + 1):\n            result = await self.llm_adapter.complete(messages, config)\n\n            if result.is_err:\n                log.warning(\n                    \"seed.extraction.failed\",\n                    interview_id=state.interview_id,\n                    error=str(result.error),\n                    attempt=attempt + 1,\n                )\n                return Result.err(result.error)\n\n            last_response = result.value.content\n\n            try:\n                requirements = self._parse_extraction_response(last_response)\n                if attempt > 0:\n                    log.info(\n                        \"seed.extraction.retry_succeeded\",\n                        interview_id=state.interview_id,\n                        attempt=attempt + 1,\n                    )\n                return Result.ok(requirements)\n            except (ValueError, KeyError) as e:\n                last_error = str(e)\n                log.warning(\n                    \"seed.extraction.parse_failed\",\n                    interview_id=state.interview_id,\n                    error=last_error,\n                    response=last_response[:500],\n                    attempt=attempt + 1,\n                )\n\n                if attempt < _MAX_EXTRACTION_RETRIES:\n                    # Retry with clarified prompt\n                    messages = [\n                        Message(role=MessageRole.SYSTEM, content=system_prompt),\n                        Message(\n                            role=MessageRole.USER,\n                            content=self._build_retry_prompt(\n                                context,\n                                last_response,\n                                last_error,\n                                is_brownfield=is_brownfield,\n                            ),\n                        ),\n                    ]\n\n        return Result.err(\n            ProviderError(\n                f\"Failed to parse extraction response after \"\n                f\"{_MAX_EXTRACTION_RETRIES + 1} attempts: {last_error}\",\n                details={\"response_preview\": last_response[:200]},\n            )\n        )\n\n    def _build_retry_prompt(\n        self,\n        context: str,\n        failed_response: str,\n        error: str,\n        *,\n        is_brownfield: bool = False,\n    ) -> str:\n        \"\"\"Build a retry prompt after extraction parse failure.\n\n        Args:\n            context: Original interview context.\n            failed_response: The response that failed to parse.\n            error: The parse error message.\n            is_brownfield: Whether the interview targets an existing codebase.\n\n        Returns:\n            Retry prompt string.\n        \"\"\"\n        return f\"\"\"Your previous response could not be parsed. Error: {error}\n\nYour response was:\n---\n{failed_response[:1000]}\n---\n\nPlease try again. Extract requirements from this interview:\n---\n{context}\n---\n\nYou MUST respond with ONLY the following format, one field per line, no other text:\n\nACCEPTANCE_CRITERIA rule: an acceptance criterion names a state of the finished work that a user can see is true; an implementation step names a means of reaching that state. Only the first belongs here — deciding means is the execution engine's work at runtime. A criterion intelligible only as a move toward a sibling is that sibling's means and belongs merged into the outcome it serves. How many criteria a goal has is discovered by that judgment.\nACCEPTANCE_CRITERIA JSON rule: emit exactly one `ACCEPTANCE_CRITERIA:` field containing a non-empty single-line JSON array. Every object must contain `description`, `verify`, `cwd`, `artifacts`, and `expect`, plus `exempt` only when `verify` is NONE (see the exempt rule); no other keys, no aliases.\nACCEPTANCE_CRITERIA verify rule: `verify` must be one complete single-line shell command. Never use heredoc or multiline syntax (`<<`, `<<'PY'`, `cat <<EOF`, line-continuation scripts); use `python -c \"...\"`, `python3 -c \"...\"`, or a test command naming the exact test files or test ids that decide this criterion. Never use a bare whole-suite command such as `python -m pytest -q`: unrelated failing tests make it fail on any work, so it cannot decide the criterion.\nACCEPTANCE_CRITERIA cwd rule: `cwd` is a portable workspace-relative directory for `verify`, or `NONE` for default resolution (the sole nested Node project for npm/npx/yarn/pnpm, otherwise the workspace root). Artifacts remain relative to the workspace root.\nACCEPTANCE_CRITERIA artifacts rule: `artifacts` must be a JSON array of exact portable file or directory paths relative to the run workspace, or the string `NONE`. The runner resolves every path literally and requires it to exist. Prefix a top-level path containing spaces with `./`. Never use a descriptive label.\nACCEPTANCE_CRITERIA expect rule: `expect` is ONLY a literal string printed verbatim in the combined stdout and stderr of `verify`, such as `OK` or `5 passed`. Use `expect: NONE` for exit-code/status conditions like `exit code 0`, `success`, `passed`, or `no errors`; exit-code 0 is already verified separately.\nACCEPTANCE_CRITERIA exempt rule: prefer a real `verify` command for every criterion — a criterion without one can only be judged from the worker's own account of its work. Use `verify: NONE` only when no command could decide the outcome, and then add `\"exempt\": \"<why no command can decide this>\"`. Omit `exempt` (or set it to NONE) whenever `verify` is a command.\n\nCONSTRAINTS rule: respond with one single-line JSON array of strings, e.g. [\"<constraint 1>\", \"<constraint 2>\"]. Constraint values may contain any characters, including literal | pipes; never use a bare pipe as the list separator.\nACCEPTANCE_CRITERIA example rule: an output, value, or call quoted in the initial context as an example illustrates the behavior; it is not an exact-output contract. A criterion may require it only in the form the context states as required. Never invent exact strings, separators, argument orders, or byte-for-byte freezes of behavior the context does not ask to keep; put any such form in ASSUMPTIONS.\nASSUMPTIONS rule: CONSTRAINTS and ACCEPTANCE_CRITERIA hold only what the initial context or a recorded answer states. Anything you would have to guess (a scope limit, a default, an exact value or output nobody required) goes in ASSUMPTIONS, a single-line JSON array of strings, or `[]` when there is none. A withheld answer stays withheld: do not reconstruct it in any field.\n\nGOAL: <clear goal statement>\nCONSTRAINTS: [\"<constraint 1>\", \"<constraint 2>\", ...]\nASSUMPTIONS: [\"<assumption 1>\", ...]\nACCEPTANCE_CRITERIA: [{{\"description\": \"<observable outcome>\", \"verify\": \"<single-line command or NONE>\", \"cwd\": \"NONE\", \"artifacts\": [\"<path>\"], \"expect\": \"<literal output or NONE>\", \"exempt\": \"<why no command can decide this, only when verify is NONE>\"}}]\nONTOLOGY_NAME: <name>\nONTOLOGY_DESCRIPTION: <description>\nONTOLOGY_FIELDS: [{{\"name\": \"<name>\", \"type\": \"<string|number|boolean|array|object>\", \"description\": \"<description>\"}}, ...]\nEVALUATION_PRINCIPLES: [{{\"name\": \"<name>\", \"description\": \"<description>\", \"weight\": <0.0-1.0>}}, ...]\nEXIT_CONDITIONS: [{{\"name\": \"<name>\", \"description\": \"<description>\", \"criteria\": \"<criteria>\"}}, ...]\n{self._project_type_template(is_brownfield=is_brownfield)}\"\"\"\n\n    @staticmethod\n    def _project_type_template(*, is_brownfield: bool) -> str:\n        \"\"\"Return the PROJECT_TYPE trailer for the extraction format.\n\n        Greenfield interviews keep today's single ``PROJECT_TYPE: greenfield``\n        line. Brownfield interviews declare the type and request the three\n        brownfield keys the parser already recognizes so the resulting Seed\n        carries a populated ``brownfield_context``.\n        \"\"\"\n        if not is_brownfield:\n            return \"PROJECT_TYPE: greenfield\"\n        return (\n            \"PROJECT_TYPE: brownfield\\n\"\n            'CONTEXT_REFERENCES: [{{\"path\": \"<path>\", \"role\": \"<primary|reference>\", \"summary\": \"<summary>\"}}, ...]\\n'\n            'EXISTING_PATTERNS: [\"<pattern 1>\", \"<pattern 2>\", ...]\\n'\n            'EXISTING_DEPENDENCIES: [\"<dependency 1>\", \"<dependency 2>\", ...]\\n'\n            \"CONTEXT_REFERENCES rule: respond with one single-line JSON array of objects. \"\n            \"Path, role, and summary values may contain any characters, including literal \"\n            \": colons and | pipes; never use a bare pipe as the list separator.\\n\"\n            \"EXISTING_PATTERNS rule: respond with one single-line JSON array of strings. \"\n            \"Pattern values may contain any characters, including literal | pipes; \"\n            \"never use a bare pipe as the list separator.\\n\"\n            \"EXISTING_DEPENDENCIES rule: respond with one single-line JSON array of strings. \"\n            \"Dependency values may contain any characters, including literal | pipes; \"\n            \"never use a bare pipe as the list separator.\"\n        )\n\n    def _build_interview_context(self, state: InterviewState) -> str:\n        \"\"\"Build context string from interview state.\n\n        Args:\n            state: The interview state.\n\n        Returns:\n            Formatted context string.\n        \"\"\"\n        parts = [f\"Initial Context: {prompt_safe_initial_context(state)}\"]\n\n        # Brownfield priming: carry the auto-explore codebase summary and the\n        # referenced paths into the extraction context so the seed architect\n        # can populate CONTEXT_REFERENCES / EXISTING_PATTERNS / EXISTING_DEPENDENCIES\n        # instead of defaulting the seed to greenfield.\n        if state.codebase_context.strip():\n            parts.append(f\"\\nCodebase Context:\\n{state.codebase_context.strip()}\")\n        if state.codebase_paths:\n            rendered_paths = \"; \".join(\n                f\"{entry.get('path', '')} ({entry.get('role', 'reference')})\"\n                for entry in state.codebase_paths\n                if entry.get(\"path\")\n            )\n            if rendered_paths:\n                parts.append(f\"\\nCodebase Paths: {rendered_paths}\")\n\n        # Observation answers render as a fixed note instead of their content\n        # (#1755). Question lines are unchanged: an observation reaching a later\n        # question is where it was collected to arrive.\n        for round_data in extraction_rounds(state):\n            if round_data.question == INITIAL_CONTEXT_SUMMARY_QUESTION:\n                continue\n            parts.append(f\"\\nQ: {round_data.question}\")\n            if round_data.answer:\n                parts.append(f\"A: {round_data.answer}\")\n\n        return \"\\n\".join(parts)\n\n    def _build_extraction_system_prompt(self) -> str:\n        \"\"\"Build system prompt for requirement extraction.\n\n        Returns:\n            System prompt string.\n        \"\"\"\n        from ouroboros.agents.loader import load_agent_prompt\n\n        return load_agent_prompt(\"seed-architect\")\n\n    def _build_extraction_user_prompt(self, context: str, *, is_brownfield: bool = False) -> str:\n        \"\"\"Build user prompt with interview context.\n\n        Args:\n            context: Formatted interview context.\n            is_brownfield: Whether the interview targets an existing codebase.\n                When True, the format requests brownfield keys the parser\n                already understands; greenfield keeps today's template output.\n\n        Returns:\n            User prompt string.\n        \"\"\"\n        return f\"\"\"Extract structured requirements from the following interview conversation.\n\n---\n{context}\n---\n\nRespond ONLY with the structured format below. Do NOT add explanations, questions, commentary, or prose. Do NOT wrap in markdown code blocks.\n\nACCEPTANCE_CRITERIA rule: an acceptance criterion names a state of the finished work that a user can see is true; an implementation step names a means of reaching that state. Only the first belongs here — deciding means is the execution engine's work at runtime. Read each criterion beside its siblings and ask which kind it is: one that stands on its own as something a user would value is an outcome, while one intelligible only as a move toward a sibling is that sibling's means and belongs merged into the outcome it serves. Leaving a means in the list is a defect as severe as a missing requirement, because it commits the seed to a path no one has verified. How many criteria a goal has is discovered by making this judgment.\nACCEPTANCE_CRITERIA JSON rule: emit exactly one `ACCEPTANCE_CRITERIA:` field containing a non-empty single-line JSON array. Every object must contain `description`, `verify`, `cwd`, `artifacts`, and `expect`, plus `exempt` only when `verify` is NONE (see the exempt rule); no other keys, no aliases.\nACCEPTANCE_CRITERIA verify rule: `verify` must be one complete single-line shell command. Never use heredoc or multiline syntax (`<<`, `<<'PY'`, `cat <<EOF`, line-continuation scripts); use `python -c \"...\"`, `python3 -c \"...\"`, or a test command naming the exact test files or test ids that decide this criterion. Never use a bare whole-suite command such as `python -m pytest -q`: unrelated failing tests make it fail on any work, so it cannot decide the criterion.\nACCEPTANCE_CRITERIA cwd rule: `cwd` is a portable workspace-relative directory for `verify`, or `NONE` for default resolution (the sole nested Node project for npm/npx/yarn/pnpm, otherwise the workspace root). Artifacts remain relative to the workspace root.\nACCEPTANCE_CRITERIA artifacts rule: `artifacts` must be a JSON array of exact portable file or directory paths relative to the run workspace, or the string `NONE`. The runner resolves every path literally and requires it to exist. Prefix a top-level path containing spaces with `./`. Never use a descriptive label.\nACCEPTANCE_CRITERIA expect rule: `expect` is ONLY a literal string printed verbatim in the combined stdout and stderr of `verify`, such as `OK` or `5 passed`. Use `expect: NONE` for exit-code/status conditions like `exit code 0`, `success`, `passed`, or `no errors`; exit-code 0 is already verified separately.\nACCEPTANCE_CRITERIA exempt rule: prefer a real `verify` command for every criterion — a criterion without one can only be judged from the worker's own account of its work. Use `verify: NONE` only when no command could decide the outcome, and then add `\"exempt\": \"<why no command can decide this>\"`. Omit `exempt` (or set it to NONE) whenever `verify` is a command.\n\nCONSTRAINTS rule: respond with one single-line JSON array of strings, e.g. [\"<constraint 1>\", \"<constraint 2>\"]. Constraint values may contain any characters, including literal | pipes; never use a bare pipe as the list separator.\nACCEPTANCE_CRITERIA example rule: an output, value, or call quoted in the initial context as an example illustrates the behavior; it is not an exact-output contract. A criterion may require it only in the form the context states as required. Never invent exact strings, separators, argument orders, or byte-for-byte freezes of behavior the context does not ask to keep; put any such form in ASSUMPTIONS.\nASSUMPTIONS rule: CONSTRAINTS and ACCEPTANCE_CRITERIA hold only what the initial context or a recorded answer states. Anything you would have to guess (a scope limit, a default, an exact value or output nobody required) goes in ASSUMPTIONS, a single-line JSON array of strings, or `[]` when there is none. A withheld answer stays withheld: do not reconstruct it in any field.\n\nGOAL: <clear goal statement>\nCONSTRAINTS: [\"<constraint 1>\", \"<constraint 2>\", ...]\nASSUMPTIONS: [\"<assumption 1>\", ...]\nACCEPTANCE_CRITERIA: [{{\"description\": \"<observable outcome>\", \"verify\": \"<single-line command or NONE>\", \"cwd\": \"NONE\", \"artifacts\": [\"<path>\"], \"expect\": \"<literal output or NONE>\", \"exempt\": \"<why no command can decide this, only when verify is NONE>\"}}]\nONTOLOGY_NAME: <name>\nONTOLOGY_DESCRIPTION: <description>\nONTOLOGY_FIELDS: [{{\"name\": \"<name>\", \"type\": \"<string|number|boolean|array|object>\", \"description\": \"<description>\"}}, ...]\nEVALUATION_PRINCIPLES: [{{\"name\": \"<name>\", \"description\": \"<description>\", \"weight\": <0.0-1.0>}}, ...]\nEXIT_CONDITIONS: [{{\"name\": \"<name>\", \"description\": \"<description>\", \"criteria\": \"<criteria>\"}}, ...]\n{self._project_type_template(is_brownfield=is_brownfield)}\"\"\"\n\n    _KNOWN_PREFIXES = (\n        \"GOAL:\",\n        \"CONSTRAINTS:\",\n        \"ASSUMPTIONS:\",\n        \"ACCEPTANCE_CRITERIA:\",\n        \"ONTOLOGY_NAME:\",\n        \"ONTOLOGY_DESCRIPTION:\",\n        \"ONTOLOGY_FIELDS:\",\n        \"EVALUATION_PRINCIPLES:\",\n        \"EXIT_CONDITIONS:\",\n        \"PROJECT_TYPE:\",\n        \"CONTEXT_REFERENCES:\",\n        \"EXISTING_PATTERNS:\",\n        \"EXISTING_DEPENDENCIES:\",\n    )\n\n    def _preprocess_response(self, response: str) -> str:\n        \"\"\"Strip markdown code blocks and conversational preamble.\n\n        Args:\n            response: Raw LLM response text.\n\n        Returns:\n            Cleaned response starting from first recognized prefix.\n        \"\"\"\n        text = _LINE_TIMESTAMP_RE.sub(\"\", response.strip())\n\n        # Strip markdown code block markers\n        code_block_match = re.search(r\"```(?:\\w*)\\n(.*?)```\", text, re.DOTALL)\n        if code_block_match:\n            text = code_block_match.group(1).strip()\n\n        # Find first recognized prefix and discard preamble\n        lines = text.split(\"\\n\")\n        start_idx = 0\n        for i, line in enumerate(lines):\n            stripped = line.strip()\n            if any(stripped.startswith(p) for p in self._KNOWN_PREFIXES):\n                start_idx = i\n                break\n\n        return \"\\n\".join(lines[start_idx:])\n\n    def _parse_extraction_response(self, response: str) -> dict[str, Any]:\n        \"\"\"Parse LLM response into requirements dictionary.\n\n        Args:\n            response: Raw LLM response text.\n\n        Returns:\n            Parsed requirements dictionary.\n\n        Raises:\n            ValueError: If response cannot be parsed.\n        \"\"\"\n        cleaned = self._preprocess_response(response)\n        lines = cleaned.strip().split(\"\\n\")\n        requirements: dict[str, Any] = {}\n        acceptance_criteria_count = 0\n\n        for line in lines:\n            line = line.strip()\n            if not line:\n                continue\n\n            matched_prefix = False\n            for prefix in self._KNOWN_PREFIXES:\n                if line.startswith(prefix):\n                    key = prefix[:-1].lower()  # Remove colon and lowercase\n                    value = line[len(prefix) :].strip()\n                    if key == \"acceptance_criteria\":\n                        acceptance_criteria_count += 1\n                        if acceptance_criteria_count > 1:\n                            raise ValueError(\"Duplicate top-level ACCEPTANCE_CRITERIA field\")\n                    requirements[key] = value\n                    matched_prefix = True\n                    break\n            if matched_prefix:\n                continue\n            raise ValueError(f\"Unrecognized extraction line after structured output began: {line}\")\n\n        if \"acceptance_criteria\" not in requirements:\n            raise ValueError(\"Missing required field: acceptance_criteria\")\n        requirements[\"acceptance_criteria\"] = _parse_extracted_acceptance_criteria(\n            requirements[\"acceptance_criteria\"]\n        )\n\n        # Validate required fields\n        required_fields = [\n            \"goal\",\n            \"ontology_name\",\n            \"ontology_description\",\n        ]\n\n        for field_name in required_fields:\n            if field_name not in requirements:\n                raise ValueError(\n                    f\"Missing required field: {field_name}. \"\n                    f\"Found: {list(requirements.keys())}. \"\n                    f\"Response preview: {response[:200]}\"\n                )\n\n        # Validate list-valued fields at parse time so malformed JSON-intent\n        # output triggers the extraction retry path instead of being silently\n        # pipe-split downstream (#1696, #1729).\n        for field_name, field_label in (\n            (\"constraints\", \"CONSTRAINTS\"),\n            (\"assumptions\", \"ASSUMPTIONS\"),\n            (\"existing_patterns\", \"EXISTING_PATTERNS\"),\n            (\"existing_dependencies\", \"EXISTING_DEPENDENCIES\"),\n        ):\n            if field_name in requirements:\n                requirements[field_name] = _parse_string_array_values(\n                    requirements[field_name], field_label=field_label, strict=True\n                )\n        if \"evaluation_principles\" in requirements:\n            requirements[\"evaluation_principles\"] = _parse_evaluation_principles(\n                requirements[\"evaluation_principles\"], strict=True\n            )\n        if \"exit_conditions\" in requirements:\n            requirements[\"exit_conditions\"] = _parse_exit_conditions(\n                requirements[\"exit_conditions\"], strict=True\n            )\n        if \"ontology_fields\" in requirements:\n            requirements[\"ontology_fields\"] = _parse_ontology_fields(\n                requirements[\"ontology_fields\"], strict=True\n            )\n        if \"context_references\" in requirements:\n            requirements[\"context_references\"] = _parse_context_references(\n                requirements[\"context_references\"], strict=True\n            )\n\n        return requirements\n\n    def _build_seed(self, requirements: dict[str, Any], metadata: SeedMetadata) -> Seed:\n        \"\"\"Build Seed from extracted requirements.\n\n        Args:\n            requirements: Extracted requirements dictionary.\n            metadata: Seed metadata.\n\n        Returns:\n            Constructed Seed instance.\n        \"\"\"\n        # Parse constraints (JSON array preferred; legacy pipe list supported)\n        constraints = _parse_string_array_values(\n            requirements.get(\"constraints\"), field_label=\"CONSTRAINTS\"\n        )\n        assumptions = _parse_string_array_values(\n            requirements.get(\"assumptions\"), field_label=\"ASSUMPTIONS\"\n        )\n\n        # Parse acceptance criteria\n        acceptance_criteria: tuple[AcceptanceCriterionSpec | str, ...] = ()\n        if \"acceptance_criteria\" in requirements and requirements[\"acceptance_criteria\"]:\n            acceptance_criteria = _parse_acceptance_criteria_contracts(\n                requirements[\"acceptance_criteria\"]\n            )\n\n        # Parse ontology fields (JSON object arrays preferred; legacy\n        # colon/pipe lists supported for stored requirements)\n        ontology_fields = _parse_ontology_fields(requirements.get(\"ontology_fields\"))\n\n        # Build ontology schema\n        ontology_schema = OntologySchema(\n            name=requirements[\"ontology_name\"],\n            description=requirements[\"ontology_description\"],\n            fields=tuple(ontology_fields),\n        )\n\n        # Parse evaluation principles and exit conditions (JSON object arrays\n        # preferred; legacy colon/pipe lists supported for stored requirements)\n        evaluation_principles = _parse_evaluation_principles(\n            requirements.get(\"evaluation_principles\")\n        )\n        exit_conditions = _parse_exit_conditions(requirements.get(\"exit_conditions\"))\n\n        # Parse brownfield context\n        brownfield_context = BrownfieldContext()\n        project_type = requirements.get(\"project_type\", \"greenfield\").strip().lower()\n        if project_type == \"brownfield\":\n            # Parse context references (JSON object arrays preferred; legacy\n            # colon/pipe lists supported for stored requirements)\n            context_refs = _parse_context_references(requirements.get(\"context_references\"))\n\n            # Parse existing patterns (lenient: stored data has no retry path)\n            existing_patterns = _parse_string_array_values(\n                requirements.get(\"existing_patterns\"), field_label=\"EXISTING_PATTERNS\"\n            )\n\n            # Parse existing dependencies (lenient: stored data has no retry path)\n            existing_deps = _parse_string_array_values(\n                requirements.get(\"existing_dependencies\"), field_label=\"EXISTING_DEPENDENCIES\"\n            )\n\n            brownfield_context = BrownfieldContext(\n                project_type=\"brownfield\",\n                context_references=tuple(context_refs),\n                existing_patterns=existing_patterns,\n                existing_dependencies=existing_deps,\n            )\n\n        return Seed(\n            goal=requirements[\"goal\"],\n            brownfield_context=brownfield_context,\n            constraints=constraints,\n            acceptance_criteria=acceptance_criteria,\n            assumptions=assumptions,\n            ontology_schema=ontology_schema,\n            evaluation_principles=tuple(evaluation_principles),\n            exit_conditions=tuple(exit_conditions),\n            metadata=metadata,\n        )\n\n    async def save_seed(\n        self,\n        seed: Seed,\n        file_path: Path | None = None,\n    ) -> Result[Path, ValidationError]:\n        \"\"\"Save seed to YAML file.\n\n        Args:\n            seed: The seed to save.\n            file_path: Optional path for the seed file.\n                If not provided, uses output_dir/seed_{id}.yaml\n\n        Returns:\n            Result containing the file path or error.\n        \"\"\"\n        if file_path is None:\n            file_path = self.output_dir / f\"{seed.metadata.seed_id}.yaml\"\n\n        log.info(\n            \"seed.saving\",\n            seed_id=seed.metadata.seed_id,\n            file_path=str(file_path),\n        )\n\n        try:\n            # Ensure parent directory exists\n            file_path.parent.mkdir(parents=True, exist_ok=True)\n\n            # Convert to dict for YAML serialization\n            seed_dict = seed.to_dict()\n\n            # Write YAML with proper formatting\n            content = yaml.dump(\n                seed_dict,\n                default_flow_style=False,\n                allow_unicode=True,\n                sort_keys=False,\n            )\n\n            if not write_owner_only(file_path, content):\n                # Reported like every other artifact writer: the file exists\n                # but the directory flush was unconfirmed.\n                log.warning(\n                    \"seed.save_durability_uncertain\",\n                    seed_id=seed.metadata.seed_id,\n                    file_path=str(file_path),\n                )\n\n            log.info(\n                \"seed.saved\",\n                seed_id=seed.metadata.seed_id,\n                file_path=str(file_path),\n            )\n\n            return Result.ok(file_path)\n\n        except (OSError, yaml.YAMLError) as e:\n            log.exception(\n                \"seed.save_failed\",\n                seed_id=seed.metadata.seed_id,\n                file_path=str(file_path),\n                error=str(e),\n            )\n            return Result.err(\n                ValidationError(\n                    f\"Failed to save seed: {e}\",\n                    details={\n                        \"seed_id\": seed.metadata.seed_id,\n                        \"file_path\": str(file_path),\n                    },\n                )\n            )\n\n\nasync def load_seed(file_path: Path) -> Result[Seed, ValidationError]:\n    \"\"\"Load seed from YAML file.\n\n    Legacy prose acceptance criteria remain supported by ``Seed.from_dict``.\n    Persisted structured contracts are revalidated against current portable\n    execution constraints and fail explicitly here when they can no longer be\n    materialized; resume must never admit an unsatisfiable verify gate.\n\n    Args:\n        file_path: Path to the seed YAML file.\n\n    Returns:\n        Result containing the loaded Seed or error.\n    \"\"\"\n    if not file_path.exists():\n        return Result.err(\n            ValidationError(\n                f\"Seed file not found: {file_path}\",\n                field=\"file_path\",\n                value=str(file_path),\n            )\n        )\n\n    try:\n        content = file_path.read_text(encoding=\"utf-8\")\n        seed_dict = yaml.safe_load(content)\n\n        # Validate and create Seed\n        seed = Seed.from_dict(seed_dict)\n\n        log.info(\n            \"seed.loaded\",\n            seed_id=seed.metadata.seed_id,\n            file_path=str(file_path),\n        )\n\n        return Result.ok(seed)\n\n    except (OSError, yaml.YAMLError, ValueError) as e:\n        log.exception(\n            \"seed.load_failed\",\n            file_path=str(file_path),\n            error=str(e),\n        )\n        return Result.err(\n            ValidationError(\n                f\"Failed to load seed: {e}\",\n                field=\"file_path\",\n                value=str(file_path),\n                details={\"error\": str(e)},\n            )\n        )\n\n\ndef save_seed_sync(seed: Seed, file_path: Path) -> Result[Path, ValidationError]:\n    \"\"\"Synchronous version of save_seed for convenience.\n\n    Args:\n        seed: The seed to save.\n        file_path: Path for the seed file.\n\n    Returns:\n        Result containing the file path or error.\n    \"\"\"\n    log.info(\n        \"seed.saving.sync\",\n        seed_id=seed.metadata.seed_id,\n        file_path=str(file_path),\n    )\n\n    try:\n        # Ensure parent directory exists\n        file_path.parent.mkdir(parents=True, exist_ok=True)\n\n        # Convert to dict for YAML serialization\n        seed_dict = seed.to_dict()\n\n        # Write YAML with proper formatting\n        content = yaml.dump(\n            seed_dict,\n            default_flow_style=False,\n            allow_unicode=True,\n            sort_keys=False,\n        )\n\n        if not write_owner_only(file_path, content):\n            log.warning(\n                \"seed.save_durability_uncertain\",\n                seed_id=seed.metadata.seed_id,\n                file_path=str(file_path),\n            )\n\n        log.info(\n            \"seed.saved.sync\",\n            seed_id=seed.metadata.seed_id,\n            file_path=str(file_path),\n        )\n\n        return Result.ok(file_path)\n\n    except (OSError, yaml.YAMLError) as e:\n        log.exception(\n            \"seed.save_failed.sync\",\n            seed_id=seed.metadata.seed_id,\n            file_path=str(file_path),\n            error=str(e),\n        )\n        return Result.err(\n            ValidationError(\n                f\"Failed to save seed: {e}\",\n                details={\n                    \"seed_id\": seed.metadata.seed_id,\n                    \"file_path\": str(file_path),\n                },\n            )\n        )\n"
    },
    {
      "path": "src/ouroboros/mcp/tools/authoring_handlers.py",
      "content": "\"\"\"Authoring-phase tool handlers for Ouroboros MCP server.\n\nContains handlers for interview and seed generation tools:\n- GenerateSeedHandler: Converts completed interview sessions into immutable Seeds.\n- InterviewHandler: Manages interactive requirement-clarification interviews.\n\"\"\"\n\nimport asyncio\nfrom dataclasses import dataclass, field\nimport os\nfrom pathlib import Path\nimport re\nimport time\nfrom typing import Any\n\nfrom pydantic import ValidationError as PydanticValidationError\nimport structlog\nimport yaml\n\nfrom ouroboros.auto.intent_guard import IntentGuardReport, IntentGuardStatus, guard_interview_turn\nfrom ouroboros.auto.requester import REQUESTER_ANSWER_PREFIX\nfrom ouroboros.backends import (\n    backend_supports_tool_envelope,\n)\nfrom ouroboros.bigbang.ambiguity import (\n    AMBIGUITY_THRESHOLD,\n    AUTO_COMPLETE_STREAK_REQUIRED,\n    AmbiguityScore,\n    AmbiguityScorer,\n    ComponentScore,\n    ScoreBreakdown,\n    get_completion_floor_failures,\n    get_milestone,\n    qualifies_for_seed_completion,\n)\nfrom ouroboros.bigbang.answer_provenance import declare_provenance, extraction_rounds\nfrom ouroboros.bigbang.interview import (\n    INITIAL_CONTEXT_SUMMARY_QUESTION,\n    MAX_PROMPT_SAFE_INITIAL_CONTEXT_CHARS,\n    MIN_ROUNDS_BEFORE_EARLY_EXIT,\n    InterviewEngine,\n    InterviewState,\n    InterviewStatus,\n)\nfrom ouroboros.bigbang.requirement_distillation import (\n    build_promoted_reference_seed,\n    build_requirement_distillation,\n    is_reference_aware_distillation,\n    seed_readiness_details,\n)\nfrom ouroboros.bigbang.seed_generator import SeedGenerator\nfrom ouroboros.bigbang.turn_planner import InterviewTurnPlanner\nfrom ouroboros.config import get_llm_backend_for_role, get_llm_model_for_role\nfrom ouroboros.core.errors import ValidationError\nfrom ouroboros.core.initial_context import resolve_initial_context_input\nfrom ouroboros.core.owner_only import secure_directory, write_owner_only\nfrom ouroboros.core.types import Result\nfrom ouroboros.interview_adapters import (\n    InterviewTurnContext,\n)\nfrom ouroboros.interview_calibration import normalize_interview_calibration\nfrom ouroboros.mcp.errors import MCPServerError, MCPToolError\nfrom ouroboros.mcp.host_context import resolve_request_subagent_dispatch\nfrom ouroboros.mcp.tools.advisory_dispatch import (\n    append_question_advisory_dispatch,\n    echo_carries_dispatch,\n    strip_bridge_notice,\n)\nfrom ouroboros.mcp.tools.interview_advisory import (\n    _attach_question_assist_requests,\n    _milestone_for_score,\n)\nfrom ouroboros.mcp.tools.interview_calibration import (\n    _ask_next_question,\n    handle_interview_calibration_turn,\n    interview_calibration_parameters,\n)\nfrom ouroboros.mcp.tools.question_advisory import (\n    build_question_advisory_request,\n    required_advisory_personas,\n)\nfrom ouroboros.mcp.tools.subagent import (\n    DELEGATED_TO_SUBAGENT,\n    FanoutRegistry,\n    build_generate_seed_subagent,\n    build_interview_subagent,\n    dispatch_plugin_terminal,\n    lateral_persona_panel_metadata_from_capability_definitions,\n    should_dispatch_via_plugin,\n)\nfrom ouroboros.mcp.types import (\n    ContentType,\n    MCPContentItem,\n    MCPToolDefinition,\n    MCPToolParameter,\n    MCPToolResult,\n    ToolInputType,\n)\nfrom ouroboros.orchestrator.capabilities.question_text import (\n    format_question_with_ambiguity as _format_question_with_ambiguity,\n)\nfrom ouroboros.orchestrator.policy import (\n    PolicyContext,\n    PolicyExecutionPhase,\n    PolicySessionRole,\n    allowed_runtime_builtin_tool_names,\n)\nfrom ouroboros.persistence.event_store import EventStore\nfrom ouroboros.providers import create_llm_adapter, resolve_llm_backend\nfrom ouroboros.providers.base import LLMAdapter\n\nlog = structlog.get_logger(__name__)\n\n_DATA_DIR = Path.home() / \".ouroboros\" / \"data\"\n\n# Strict format for caller-supplied ``interview_id`` arguments — matches\n# the server's own generation pattern (``f\"interview_{uuid4().hex[:16]}\"``)\n# so external clients cannot inject arbitrary identifiers.  See\n# Q00/ouroboros#723 review.\n_SUGGESTED_INTERVIEW_ID_RE = re.compile(r\"^interview_[a-f0-9]{16}$\")\n\n_LIVE_AMBIGUITY_MAX_RETRIES = 3\n_QUESTION_GENERATION_ENVELOPE_VIOLATION = \"ToolUseBlockViolation\"\n_QUESTION_GENERATION_ENVELOPE_REASON_CODE = \"question_generation_envelope_violation\"\n\nREQUIRED_CLIENT_GATES: tuple[str, ...] = (\n    # TODO(#1008): derive required gate names from the interview skill /\n    # backend capability registry once non-skippable gates have a structured\n    # source of truth instead of a Markdown-only checklist.\n    \"seed_ready_acceptance_guard\",\n    \"restate_goal_approved\",\n)\n_REQUIRE_CLIENT_GATES_ENV = \"OUROBOROS_REQUIRE_CLIENT_GATES\"\n_NORMALIZED_TURN_CONTEXT_KEY = \"_normalized_interview_turn_context\"\n\n\ndef _elapsed_ms(started_at: float) -> float:\n    \"\"\"Return a stable monotonic duration suitable for diagnostic events.\"\"\"\n    return round((time.perf_counter() - started_at) * 1000, 3)\n\n\ndef _normalized_turn_context(arguments: dict[str, Any]) -> InterviewTurnContext | None:\n    value = arguments.get(_NORMALIZED_TURN_CONTEXT_KEY)\n    return value if isinstance(value, InterviewTurnContext) else None\n\n\ndef _normalize_client_gates(value: Any) -> frozenset[str]:\n    \"\"\"Normalize caller-reported client-side gate acknowledgements.\"\"\"\n    if isinstance(value, str):\n        return frozenset(part.strip() for part in value.split(\",\") if part.strip())\n    if isinstance(value, (list, tuple, set, frozenset)):\n        return frozenset(item.strip() for item in value if isinstance(item, str) and item.strip())\n    return frozenset()\n\n\ndef get_client_gate_status(arguments: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Return required/accepted/missing client gate metadata for seed generation.\"\"\"\n    accepted = _normalize_client_gates(arguments.get(\"client_gates\"))\n    missing = tuple(gate for gate in REQUIRED_CLIENT_GATES if gate not in accepted)\n    status: dict[str, Any] = {\n        \"required_client_gates\": REQUIRED_CLIENT_GATES,\n        \"accepted_client_gates\": tuple(sorted(accepted)),\n        \"missing_client_gates\": missing,\n    }\n    if missing:\n        status[\"client_gate_warning\"] = (\n            \"Seed generation was requested without all client-side interview gates \"\n            \"being acknowledged. The client should run the Seed-ready Acceptance Guard \"\n            \"and Restate gate, then pass client_gates with the acknowledged gate names.\"\n        )\n    return status\n\n\ndef _require_client_gates_enabled() -> bool:\n    \"\"\"Return True when missing client gates should hard-block generation.\"\"\"\n    return os.environ.get(_REQUIRE_CLIENT_GATES_ENV, \"\").strip().lower() in {\n        \"1\",\n        \"true\",\n        \"yes\",\n        \"on\",\n    }\n\n\ndef _client_gate_error(gate_status: dict[str, Any]) -> MCPToolError | None:\n    missing = gate_status.get(\"missing_client_gates\")\n    if not missing or not _require_client_gates_enabled():\n        return None\n    missing_display = \", \".join(str(item) for item in missing)\n    return MCPToolError(\n        \"Seed generation requires acknowledged client-side interview gates \"\n        f\"when {_REQUIRE_CLIENT_GATES_ENV}=1. Missing: {missing_display}.\",\n        tool_name=\"ouroboros_generate_seed\",\n    )\n\n\ndef _client_gate_warning_text(gate_status: dict[str, Any]) -> str:\n    warning = gate_status.get(\"client_gate_warning\")\n    missing = gate_status.get(\"missing_client_gates\")\n    if not isinstance(warning, str) or not missing:\n        return \"\"\n    missing_display = \", \".join(str(item) for item in missing)\n    return f\"Client Gate Warning: {warning} Missing: {missing_display}.\\n\\n\"\n\n\n_INTERVIEW_COMPLETION_SIGNALS = {\n    \"done\",\n    \"complete\",\n    \"stop\",\n    \"enough\",\n    \"generate seed\",\n    \"create seed\",\n    \"seed\",\n}\n\n_INTERVIEW_COMPLETION_PHRASES = (\n    \"close the interview\",\n    \"close interview\",\n    \"close now\",\n    \"mark the interview complete\",\n    \"mark interview complete\",\n    \"generate the seed\",\n    \"create the seed\",\n    \"seed generation\",\n    \"ready for seed generation\",\n    \"hand off for seed generation\",\n    \"no remaining ambiguity\",\n    \"no ambiguity remains\",\n    \"no ambiguity left\",\n)\n_INTERVIEW_STRUCTURED_COMPLETION_PREFIX = \"[from-user][refined][closure]\"\n\n\ndef _interview_allowed_tools(runtime_backend: str | None) -> list[str] | None:\n    \"\"\"Return the policy-derived read-only tool envelope for interviews.\"\"\"\n    effective_backend = resolve_llm_backend(runtime_backend)\n    if not backend_supports_tool_envelope(effective_backend):\n        return None\n    return allowed_runtime_builtin_tool_names(\n        PolicyContext(\n            runtime_backend=effective_backend,\n            session_role=PolicySessionRole.INTERVIEW,\n            execution_phase=PolicyExecutionPhase.INTERVIEW,\n        )\n    )\n\n\ndef _handler_llm_backend(configured_backend: str | None, role: str) -> str:\n    \"\"\"Resolve a handler's internal-LLM backend from its logical role.\"\"\"\n    return get_llm_backend_for_role(role, explicit_backend=configured_backend)\n\n\n_INTERVIEW_COMPLETION_NEGATIONS = (\n    \"not done\",\n    \"not complete\",\n    \"not enough\",\n    \"not ready\",\n    \"do not close\",\n    \"dont close\",\n    \"don't close\",\n)\n\n_INTERVIEW_LATERAL_REVIEW_PROSE_FALLBACK_INSTRUCTION = (\n    \"Follow skills/interview/SKILL.md milestone lateral-review dispatch: \"\n    \"call ouroboros_lateral_think with meta.lateral_review_tool_args when \"\n    \"present. If only legacy advisory fields are present, call it with \"\n    'personas=[\"researcher\",\"contrarian\",\"simplifier\"], a problem context '\n    \"containing the current interview session, milestone, and question, and a \"\n    \"current approach describing the next interview-routing decision. Fold only \"\n    \"concrete, user-safe findings into the next answer or question; if lateral \"\n    \"tooling is unavailable, continue the interview and say the review could \"\n    \"not be run.\"\n)\n\n\ndef _normalize_interview_answer(answer: str) -> str:\n    \"\"\"Normalize interview answers for lightweight intent matching.\"\"\"\n    return \" \".join(re.findall(r\"[a-z0-9']+\", answer.lower()))\n\n\ndef _is_safe_default_synthesis_completion(answer: str | None) -> bool:\n    \"\"\"Return True for the auto driver's auditable safe-default close signal.\"\"\"\n    return bool(\n        answer is not None\n        and answer.lstrip().lower().startswith(\"[from-auto][safe-default-synthesis]\")\n    )\n\n\ndef _is_interview_completion_signal(answer: str | None) -> bool:\n    \"\"\"Return True when the answer explicitly asks to end the interview.\n\n    Only ``[from-user]`` and prefix-less answers represent human intent to close.\n    The one deterministic non-human exception is the auto driver's\n    ``[from-auto][safe-default-synthesis]`` payload, which is emitted only after\n    the driver has already accepted auditable safe defaults for the remaining\n    required gaps and must close the persisted interview in the same turn.\n\n    The auto driver's ordinary ``_feature_acceptance_answer`` echoes the LLM question into\n    its answer text, which can accidentally include phrases like \"no remaining\n    ambiguity\" and trip the shortfall branch. Gate the heuristic by prefix so\n    ``[from-auto]`` / ``[from-code]`` / ``[from-research]`` answers — which carry\n    facts or auto-generated fillers, not user intent — never enter completion.\n\n    If a new ``[from-<source>]`` prefix is introduced in\n    ``skills/interview/SKILL.md`` (or the LLM-facing prompt at\n    ``bigbang/interview.py``), audit whether that source represents direct human\n    intent and update the guard below — otherwise it is silently default-denied,\n    which is safe (the user can still close with a prefix-less ``\"done\"``) but\n    may surprise callers.\n    \"\"\"\n    if answer is None:\n        return False\n\n    stripped = answer.lstrip().lower()\n    # Auto-generated answers normally must not express user intent to close, but\n    # the safe-default finalizer is the one deterministic exception: the auto\n    # driver has already decided the remaining required gaps are conservative\n    # defaults and now needs the persisted interview session to close in the\n    # same turn that records those defaults.  Keep this allowance tied to the\n    # explicit synthesis tag so ordinary ``[from-auto]`` answers remain guarded.\n    allow_auto_safe_default_completion = _is_safe_default_synthesis_completion(answer)\n    if (\n        stripped.startswith(\"[from-\")\n        and not stripped.startswith(\"[from-user]\")\n        and not allow_auto_safe_default_completion\n    ):\n        return False\n\n    if stripped.startswith(_INTERVIEW_STRUCTURED_COMPLETION_PREFIX):\n        return True\n\n    normalized = _normalize_interview_answer(answer)\n    if not normalized:\n        return False\n\n    if normalized in _INTERVIEW_COMPLETION_SIGNALS:\n        return True\n\n    if any(phrase in normalized for phrase in _INTERVIEW_COMPLETION_NEGATIONS):\n        return False\n\n    if any(phrase in normalized for phrase in _INTERVIEW_COMPLETION_PHRASES):\n        return True\n\n    tokens = set(normalized.split())\n    if {\"close\", \"interview\"} <= tokens:\n        return True\n    if \"seed\" in tokens and tokens.intersection({\"generate\", \"create\", \"ready\"}):\n        return True\n    if \"ambiguity\" in tokens and \"no\" in tokens and tokens.intersection({\"remaining\", \"left\"}):\n        return True\n    return normalized.endswith(\" done\") or normalized == \"done\"\n\n\ndef _count_answered_rounds(state: InterviewState) -> int:\n    \"\"\"Return the number of completed interview rounds.\"\"\"\n    return sum(1 for round_data in state.rounds if round_data.user_response is not None)\n\n\ndef _reset_stale_completion_streak(state: InterviewState) -> None:\n    \"\"\"Invalidate any accrued completion streak.\n\n    Single source of truth for the \"stale streak invalidation\" rule\n    shared by every path that observes a non-qualifying signal (scorer\n    error, weak live rescore, non-qualifying normal answer). Keeping the\n    reset in one helper makes the two-signal completion contract\n    stateless across flows: a stored streak only survives a signal that\n    was itself qualifying.\n    \"\"\"\n    if state.completion_candidate_streak != 0:\n        state.completion_candidate_streak = 0\n        state.mark_updated()\n\n\ndef _update_completion_candidate_streak(\n    state: InterviewState,\n    score: AmbiguityScore,\n) -> bool:\n    \"\"\"Update and return whether the current score qualifies for auto-completion.\"\"\"\n    qualifies = qualifies_for_seed_completion(score, is_brownfield=state.is_brownfield)\n    if qualifies:\n        state.completion_candidate_streak += 1\n    else:\n        _reset_stale_completion_streak(state)\n    return qualifies\n\n\ndef _completion_gate_reason(\n    score: AmbiguityScore | None,\n    *,\n    is_brownfield: bool,\n) -> str:\n    \"\"\"Describe the strongest reason interview completion is still blocked.\"\"\"\n    if score is None:\n        return f\"ambiguity score could not be confirmed against threshold {AMBIGUITY_THRESHOLD:.2f}\"\n    if score.overall_score > AMBIGUITY_THRESHOLD:\n        return (\n            f\"ambiguity score {score.overall_score:.2f} exceeds threshold {AMBIGUITY_THRESHOLD:.2f}\"\n        )\n\n    floor_failures = get_completion_floor_failures(score, is_brownfield=is_brownfield)\n    if floor_failures:\n        return f\"completion floors are unmet ({'; '.join(floor_failures)})\"\n\n    return \"requirements are not stable enough to close yet\"\n\n\n_MILESTONE_RANKS = {\n    \"initial\": 0,\n    \"progress\": 1,\n    \"refined\": 2,\n    \"ready\": 3,\n}\n\n\ndef _maybe_record_lateral_review_advisory(\n    state: InterviewState,\n    *,\n    previous_milestone: str | None,\n    score: AmbiguityScore | None,\n) -> dict[str, Any] | None:\n    \"\"\"Return advisory meta for a first-time forward milestone transition.\n\n    This helper is intentionally deterministic and side-effect free: it only\n    computes whether the next response should carry an advisory. The caller\n    persists the advised milestone after it knows a question-bearing response\n    will actually be returned, so auto-complete and question-generation failure\n    paths do not consume the advisory without surfacing it.\n    \"\"\"\n    current_milestone = _milestone_for_score(score)\n    if previous_milestone is None or current_milestone is None:\n        return None\n\n    previous_rank = _MILESTONE_RANKS.get(previous_milestone)\n    current_rank = _MILESTONE_RANKS.get(current_milestone)\n    if previous_rank is None or current_rank is None or current_rank <= previous_rank:\n        return None\n\n    if current_milestone in state.lateral_review_advised_milestones:\n        return None\n\n    return {\n        \"lateral_review_recommended\": True,\n        \"lateral_review_milestone\": current_milestone,\n        \"lateral_review_from_milestone\": previous_milestone,\n        \"lateral_review_reason\": \"first_forward_milestone_transition\",\n    }\n\n\n_INTERVIEW_LATERAL_PERSONAS = (\"researcher\", \"contrarian\", \"simplifier\")\n\n\ndef _latest_answered_round(state: InterviewState) -> Any | None:\n    \"\"\"Return the latest round with a user response, if any.\"\"\"\n    for round_data in reversed(state.rounds):\n        if round_data.user_response is not None:\n            return round_data\n    return None\n\n\ndef _build_interview_lateral_review_tool_args(\n    state: InterviewState,\n    *,\n    next_question: str,\n    score: AmbiguityScore | None,\n    lateral_review_meta: dict[str, Any],\n) -> dict[str, Any]:\n    \"\"\"Build lateral-review args, skipping personas the advisory lanes already run.\"\"\"\n    covered = required_advisory_personas(\"ouroboros_interview\")\n    latest = _latest_answered_round(state)\n    milestone = lateral_review_meta[\"lateral_review_milestone\"]\n    from_milestone = lateral_review_meta[\"lateral_review_from_milestone\"]\n    score_text = f\"{score.overall_score:.2f}\" if score is not None else \"unknown\"\n\n    problem_lines = [\n        \"An Ouroboros interview just crossed an ambiguity milestone.\",\n        f\"Interview ID: {state.interview_id}\",\n        f\"Milestone: {from_milestone} -> {milestone}\",\n        f\"Ambiguity score: {score_text}\",\n        f\"Initial context: {state.initial_context[:700]}\",\n    ]\n    if latest is not None:\n        problem_lines.extend(\n            [\n                f\"Latest answered question: {latest.question[:500]}\",\n                f\"Latest answer: {(latest.user_response or '')[:700]}\",\n            ]\n        )\n    problem_lines.append(f\"Next interview question: {next_question[:500]}\")\n\n    return {\n        \"problem_context\": \"\\n\".join(problem_lines),\n        \"current_approach\": (\n            \"The main session is continuing a Socratic interview and is about to \"\n            \"route the next question. Surface what the per-question advisory lanes \"\n            \"cannot: facts, evidence, or context the interview has not gathered yet.\"\n        ),\n        \"personas\": [p for p in _INTERVIEW_LATERAL_PERSONAS if p not in covered] or [\"researcher\"],\n        \"failed_attempts\": [],\n    }\n\n\ndef _build_interview_lateral_review_orchestration(\n    *,\n    tool_args: dict[str, Any],\n) -> dict[str, Any]:\n    \"\"\"Build runtime handling metadata for interview lateral-review panels.\"\"\"\n    panel = lateral_persona_panel_metadata_from_capability_definitions()\n    if not panel:\n        return {\n            \"kind\": \"mcp_directive\",\n            \"directive\": \"run_lateral_persona_panel\",\n            \"mcp_tool\": \"ouroboros_lateral_think\",\n            \"tool_args\": dict(tool_args),\n            \"structured_lateral_panel_metadata_available\": False,\n            \"fallback\": \"skill_prose_instructions\",\n            \"prose_instruction_source\": \"skills/interview/SKILL.md\",\n            \"prose_instruction\": _INTERVIEW_LATERAL_REVIEW_PROSE_FALLBACK_INSTRUCTION,\n            \"runtime_handling\": {\n                \"call_mcp_tool_first\": True,\n                \"result_correlation_key\": None,\n                \"requires_prose_parsing\": True,\n                \"synthesize_before_interview_continuation\": True,\n            },\n        }\n    requested_personas = [str(item) for item in tool_args.get(\"personas\", [])]\n    panel_persona_by_id = {\n        str(persona.get(\"persona_id\")): dict(persona)\n        for persona in panel.get(\"personas\", [])\n        if isinstance(persona, dict) and persona.get(\"persona_id\")\n    }\n    panel_personas = [\n        panel_persona_by_id[persona_id]\n        for persona_id in requested_personas\n        if persona_id in panel_persona_by_id\n    ]\n    response_refs = dict(panel.get(\"response_payload_refs\", {}))\n    sequential_fallback = dict(panel.get(\"sequential_fallback\", {}))\n    sequential_mode = str(sequential_fallback.get(\"mode\") or \"sequential_persona_payload_dispatch\")\n    mcp_tool = str(panel.get(\"mcp_tool\") or \"ouroboros_lateral_think\")\n\n    return {\n        \"kind\": \"mcp_directive\",\n        \"directive\": \"run_lateral_persona_panel\",\n        \"mcp_tool\": mcp_tool,\n        \"tool_args\": dict(tool_args),\n        \"panel\": {\n            \"panel_id\": str(panel.get(\"panel_id\") or \"lateral_persona_panel.v1\"),\n            \"mcp_tool\": mcp_tool,\n            \"dispatch_modes\": list(panel.get(\"dispatch_modes\", [])),\n            \"legacy_dispatch_modes\": list(panel.get(\"legacy_dispatch_modes\", [])),\n            \"parallel_preference\": str(\n                panel.get(\"parallel_preference\") or \"parallel_when_runtime_supports_subagents\"\n            ),\n            \"sequential_fallback\": sequential_fallback,\n            \"personas\": panel_personas,\n            \"response_payload_refs\": response_refs,\n            \"runtime_instruction\": str(panel.get(\"runtime_instruction\") or \"\"),\n        },\n        \"runtime_handling\": {\n            \"call_mcp_tool_first\": True,\n            \"parallel_capable_execution_mode\": \"parallel_subagent_panel\",\n            \"sequential_fallback_mode\": sequential_mode,\n            \"sequential_fallback_trigger\": sequential_fallback.get(\"trigger\"),\n            \"result_correlation_key\": response_refs.get(\"result_correlation_key\"),\n            \"requires_prose_parsing\": bool(response_refs.get(\"requires_prose_parsing\")),\n            \"synthesize_before_interview_continuation\": True,\n        },\n    }\n\n\ndef _with_lateral_review_dispatch(\n    state: InterviewState,\n    *,\n    next_question: str,\n    score: AmbiguityScore | None,\n    lateral_review_meta: dict[str, Any] | None,\n) -> dict[str, Any] | None:\n    \"\"\"Attach runnable lateral-think dispatch metadata to an advisory.\"\"\"\n    if lateral_review_meta is None:\n        return None\n    tool_args = _build_interview_lateral_review_tool_args(\n        state,\n        next_question=next_question,\n        score=score,\n        lateral_review_meta=lateral_review_meta,\n    )\n    enriched = dict(lateral_review_meta)\n    enriched.update(\n        {\n            \"lateral_review_required\": True,\n            \"lateral_review_tool\": \"ouroboros_lateral_think\",\n            \"lateral_review_personas\": list(tool_args[\"personas\"]),\n            \"lateral_review_tool_args\": tool_args,\n            \"lateral_review_orchestration\": (\n                _build_interview_lateral_review_orchestration(\n                    tool_args=tool_args,\n                )\n            ),\n        }\n    )\n    return enriched\n\n\ndef _compute_transcript_chars(state: InterviewState) -> int:\n    \"\"\"Sum question + user_response length over every round in ``state``.\n\n    Used by the response-shape diagnostic event (Q00/ouroboros#831) so we\n    can correlate hang reports with cumulative interview context size.\n    \"\"\"\n    total = 0\n    for round_data in state.rounds:\n        total += len(round_data.question or \"\")\n        total += len(round_data.user_response or \"\")\n    return total\n\n\ndef _build_question_advisory_request(\n    *,\n    session_id: str,\n    question: str,\n    phase: str,\n    score: AmbiguityScore | None,\n    code_investigation_request: dict[str, Any] | None = None,\n    last_question: str | None = None,\n) -> dict[str, Any]:\n    \"\"\"Build the interview's advisory request. Kept for existing importers.\n\n    The builder moved to ``question_advisory`` and is shared with every tool\n    that declares a catalog; this signature stays so a caller that had the\n    interview's ambiguity score in hand does not have to unpack it here.\n    \"\"\"\n    return build_question_advisory_request(\n        tool_name=\"ouroboros_interview\",\n        session_id=session_id,\n        question=question,\n        phase=phase,\n        ambiguity_score=score.overall_score if score is not None else None,\n        milestone=_milestone_for_score(score),\n        code_investigation_request=code_investigation_request,\n        last_question=last_question,\n    )\n\n\ndef _is_initial_context_length_guard_question(question: str) -> bool:\n    \"\"\"Return True when ``question`` is the length-guard meta-directive.\n\n    The interview engine surfaces a fixed string as the \"next question\" when\n    ``initial_context`` exceeds ``MAX_PROMPT_SAFE_INITIAL_CONTEXT_CHARS``.\n    That string is not a real interview question — it asks the *caller* to\n    re-send a shorter summary — so MCP responses carrying it must carry a\n    distinguishing meta signal.  See Q00/ouroboros#831.\n    \"\"\"\n    return question == INITIAL_CONTEXT_SUMMARY_QUESTION\n\n\ndef _length_guard_meta_fields() -> dict[str, Any]:\n    \"\"\"Return the meta keys that mark a length-guard response.\n\n    The handler merges these into the existing ``meta`` dict (``session_id``,\n    ``ambiguity_score``, etc.) when the returned question is the length-guard\n    meta-directive.  Clients can branch on ``meta.reason`` to handle the case\n    programmatically instead of mis-routing the question to a human via\n    AskUserQuestion.\n    \"\"\"\n    return {\n        \"recoverable\": True,\n        \"reason\": \"initial_context_too_large\",\n        \"expected_action\": \"resend_with_summary\",\n        \"max_chars\": MAX_PROMPT_SAFE_INITIAL_CONTEXT_CHARS,\n    }\n\n\ndef _provider_error_type(error: Any) -> str | None:\n    details = getattr(error, \"details\", None)\n    if isinstance(details, dict):\n        error_type = details.get(\"error_type\")\n        if isinstance(error_type, str) and error_type:\n            return error_type\n    return None\n\n\ndef _is_question_generation_envelope_violation(error: Any) -> bool:\n    \"\"\"Return true for strict provider tool-envelope violations.\"\"\"\n    provider_error_type = _provider_error_type(error)\n    if provider_error_type == _QUESTION_GENERATION_ENVELOPE_VIOLATION:\n        return True\n    return _QUESTION_GENERATION_ENVELOPE_VIOLATION in str(error)\n\n\ndef _interview_reasoning_meta(\n    *,\n    state: InterviewState | None,\n    session_id: str | None,\n    phase: str,\n    next_action: str,\n    score: AmbiguityScore | None = None,\n    question: str | None = None,\n    recoverable: bool = False,\n) -> dict[str, Any]:\n    \"\"\"Build compact interview reasoning metadata for client-side UI surfaces.\"\"\"\n    answered_rounds = _count_answered_rounds(state) if state is not None else None\n    total_rounds = len(state.rounds) if state is not None else None\n    pending_question = (\n        bool(state.rounds and state.rounds[-1].user_response is None)\n        if state is not None\n        else False\n    )\n    floor_failures: list[str] = []\n    completion_qualified: bool | None = None\n    if score is not None:\n        floor_failures = get_completion_floor_failures(\n            score,\n            is_brownfield=state.is_brownfield if state is not None else False,\n        )\n        completion_qualified = (\n            qualifies_for_seed_completion(\n                score,\n                is_brownfield=state.is_brownfield if state is not None else False,\n            )\n            and not floor_failures\n        )\n\n    lines = [f\"phase: {phase}\"]\n    if session_id:\n        lines.append(f\"session: {session_id}\")\n    if answered_rounds is not None and total_rounds is not None:\n        lines.append(f\"rounds: {answered_rounds} answered / {total_rounds} total\")\n    if state is not None:\n        lines.append(f\"brownfield: {str(state.is_brownfield).lower()}\")\n        if pending_question:\n            lines.append(\"pending: waiting for user answer\")\n        if state.completion_candidate_streak:\n            lines.append(\n                f\"stability: {state.completion_candidate_streak}/{AUTO_COMPLETE_STREAK_REQUIRED}\"\n            )\n    if score is not None:\n        lines.append(f\"ambiguity: {score.overall_score:.2f}\")\n        milestone = _milestone_for_score(score)\n        if milestone:\n            lines.append(f\"milestone: {milestone}\")\n        if floor_failures:\n            lines.append(f\"completion blocked: {'; '.join(floor_failures)}\")\n    if question:\n        lines.append(f\"question_chars: {len(question)}\")\n    if recoverable:\n        lines.append(\"recoverable: true\")\n    lines.append(f\"next: {next_action}\")\n\n    return {\n        \"internal_reasoning\": lines,\n        \"interview_reasoning\": {\n            \"phase\": phase,\n            \"next_action\": next_action,\n            \"session_id\": session_id,\n            \"answered_rounds\": answered_rounds,\n            \"total_rounds\": total_rounds,\n            \"pending_question\": pending_question,\n            \"is_brownfield\": state.is_brownfield if state is not None else None,\n            \"ambiguity_score\": score.overall_score if score is not None else None,\n            \"milestone\": _milestone_for_score(score),\n            \"seed_ready\": (score.is_ready_for_seed if score is not None else None),\n            \"completion_qualified\": completion_qualified,\n            \"completion_floor_failures\": floor_failures,\n            \"completion_candidate_streak\": (\n                state.completion_candidate_streak if state is not None else None\n            ),\n            \"streak_required\": AUTO_COMPLETE_STREAK_REQUIRED,\n            \"recoverable\": recoverable,\n            \"question_chars\": len(question) if question else None,\n        },\n    }\n\n\ndef _classify_interview_answer_source(answer: str) -> str:\n    \"\"\"Return a coarse provenance class for an ``ooo interview`` answer.\"\"\"\n    lowered = str(answer).lstrip().casefold()\n    if lowered.startswith(\"[from-code]\") or lowered.startswith(\"[from-repo]\"):\n        return \"repo_fact\"\n    if lowered.startswith(REQUESTER_ANSWER_PREFIX):  # auto relays the requester's own answer\n        return \"requester\"\n    if lowered.startswith(\"[from-auto]\") or lowered.startswith(\"[from-safe-default]\"):\n        return \"generated\"\n    if lowered.startswith(\"[from-assumption]\") or lowered.startswith(\"[from-inference]\"):\n        return \"generated\"\n    return \"human\"\n\n\ndef _guard_interview_answer(\n    *,\n    state: InterviewState,\n    question: str,\n    answer: str,\n) -> IntentGuardReport:\n    return guard_interview_turn(\n        goal=state.initial_context,\n        question=question,\n        answer_text=answer,\n        answer_source=_classify_interview_answer_source(answer),\n    )\n\n\ndef _format_intent_guard_blocker(report: IntentGuardReport) -> str:\n    for check in report.checks:\n        if check.status is IntentGuardStatus.FAIL:\n            if check.action:\n                return f\"IntentGuard blocked interview answer: {check.message} ({check.action})\"\n            return f\"IntentGuard blocked interview answer: {check.message}\"\n    return \"IntentGuard blocked interview answer\"\n\n\ndef _ambiguity_warning_for_failed_question(\n    score: AmbiguityScore | None,\n    *,\n    is_brownfield: bool = False,\n) -> str:\n    \"\"\"Build an explicit ambiguity warning for question-generation failures.\n\n    When question generation fails mid-interview, the main session must NOT\n    assume the interview is complete.\n    See: https://github.com/Q00/ouroboros/issues/210\n    \"\"\"\n    if score is None:\n        return (\n            \"\\n\\nWARNING: Ambiguity score is unknown. \"\n            \"The interview is NOT complete — do NOT generate a Seed. \"\n            \"Resume the interview to continue clarifying requirements.\"\n        )\n    if not score.is_ready_for_seed:\n        return (\n            f\"\\n\\nWARNING: Current ambiguity is {score.overall_score:.2f} \"\n            f\"(threshold: {AMBIGUITY_THRESHOLD}). \"\n            f\"The interview is NOT complete — do NOT generate a Seed. \"\n            f\"Resume the interview to continue clarifying requirements.\"\n        )\n    floor_failures = get_completion_floor_failures(score, is_brownfield=is_brownfield)\n    if floor_failures:\n        return (\n            \"\\n\\nWARNING: Ambiguity is low, but completion floors are unmet \"\n            f\"({'; '.join(floor_failures)}). \"\n            \"The interview is NOT complete — do NOT generate a Seed. \"\n            \"Resume the interview to continue clarifying requirements.\"\n        )\n    return \"\"\n\n\n_INTERVIEW_EVENT_ERROR_DETAIL_KEYS = (\n    \"error_type\",\n    \"session_id\",\n    \"failure_category\",\n    \"model_guidance\",\n    \"auth_plane\",\n    \"openai_responses_endpoint_seen\",\n    \"returncode\",\n    \"subtype\",\n    \"stop_reason\",\n    \"partial_rejected\",\n    \"content_length\",\n    \"timeout_seconds\",\n    \"attempt\",\n    \"depth\",\n)\n\n_INTERVIEW_EVENT_POSIX_PATH_RE = re.compile(\n    r\"(^|[\\s,;:='\\\"`(<{\\[])\"\n    r\"(\"\n    r\"~[/\\\\][^\\s,;'\\\"\\]}]+\"\n    r\"|/(?!api(?:/|$))[^\\s,;'\\\"\\]}]+\"\n    r\")\"\n)\n_INTERVIEW_EVENT_URL_RE = re.compile(r\"https?://[^\\s,;:'\\\")\\]}]+\")\n_INTERVIEW_EVENT_WINDOWS_DRIVE_RE = re.compile(r\"[A-Za-z]:\\\\\")\n_INTERVIEW_EVENT_PATH_REDACTION = \"[redacted path]\"\n\n\ndef _redact_interview_event_posix_path(match: re.Match[str]) -> str:\n    return f\"{match.group(1)}{_INTERVIEW_EVENT_PATH_REDACTION}\"\n\n\ndef _redact_interview_event_windows_paths(text: str) -> str:\n    \"\"\"Redact Windows drive paths without consuming unrelated sentence tails.\"\"\"\n    redacted: list[str] = []\n    cursor = 0\n    while match := _INTERVIEW_EVENT_WINDOWS_DRIVE_RE.search(text, cursor):\n        redacted.append(text[cursor : match.start()])\n        index = match.end()\n        while index < len(text):\n            char = text[index]\n            if char in \"\\r\\n,;:'\\\")]}\":\n                break\n            if char.isspace():\n                next_space = index + 1\n                while next_space < len(text) and not text[next_space].isspace():\n                    if text[next_space] in \"\\r\\n,;:'\\\")]}\":\n                        break\n                    next_space += 1\n                if \"\\\\\" not in text[index + 1 : next_space]:\n                    break\n            index += 1\n        redacted.append(_INTERVIEW_EVENT_PATH_REDACTION)\n        cursor = index\n    redacted.append(text[cursor:])\n    return \"\".join(redacted)\n\n\ndef _redact_interview_event_error_text(text: str) -> str:\n    \"\"\"Remove local path-shaped substrings from persisted interview event text.\"\"\"\n    urls: list[str] = []\n\n    def protect_url(match: re.Match[str]) -> str:\n        urls.append(match.group(0))\n        return f\"__INTERVIEW_EVENT_URL_{len(urls) - 1}__\"\n\n    protected = _INTERVIEW_EVENT_URL_RE.sub(protect_url, text)\n    redacted = _redact_interview_event_windows_paths(protected)\n    redacted = _INTERVIEW_EVENT_POSIX_PATH_RE.sub(_redact_interview_event_posix_path, redacted)\n    for index, url in enumerate(urls):\n        redacted = redacted.replace(f\"__INTERVIEW_EVENT_URL_{index}__\", url)\n    return redacted\n\n\ndef _format_interview_failure_event_error(error: Any) -> str:\n    \"\"\"Return an event-safe error string for interview failure events.\n\n    Provider errors can carry rich machine diagnostics in ``details``.  Those\n    details are intentionally useful for structured callers, but event text is a\n    persisted/user-adjacent surface.  Render only the provider message plus an\n    explicit allowlist of scalar, non-path diagnostic fields; keep path-bearing\n    fields such as ``cwd`` and ``configured_cli_path`` in the original error\n    object for internal diagnostics only.\n    \"\"\"\n    message = getattr(error, \"message\", None)\n    if not isinstance(message, str) or not message:\n        message = str(error)\n    rendered = [_redact_interview_event_error_text(message)]\n\n    details = getattr(error, \"details\", None)\n    if isinstance(details, dict):\n        for key in _INTERVIEW_EVENT_ERROR_DETAIL_KEYS:\n            value = details.get(key)\n            if value is None or isinstance(value, dict | list | tuple | set):\n                continue\n            rendered.append(f\"{key}: {_redact_interview_event_error_text(str(value))}\")\n\n    provider = getattr(error, \"provider\", None)\n    if provider:\n        rendered.append(f\"provider: {_redact_interview_event_error_text(str(provider))}\")\n    status_code = getattr(error, \"status_code\", None)\n    if status_code is not None:\n        rendered.append(f\"status_code: {status_code}\")\n\n    return \"\\n\".join(rendered)\n\n\ndef _load_state_ambiguity_score(state: InterviewState) -> AmbiguityScore | None:\n    \"\"\"Rebuild a stored ambiguity snapshot from interview state.\"\"\"\n    if state.ambiguity_score is None:\n        return None\n\n    if isinstance(state.ambiguity_breakdown, dict):\n        try:\n            breakdown = ScoreBreakdown.model_validate(state.ambiguity_breakdown)\n        except PydanticValidationError:\n            log.warning(\n                \"mcp.tool.interview.invalid_stored_ambiguity_breakdown\",\n                session_id=state.interview_id,\n            )\n        else:\n            return AmbiguityScore(\n                overall_score=state.ambiguity_score,\n                breakdown=breakdown,\n            )\n\n    breakdown = ScoreBreakdown(\n        goal_clarity=ComponentScore(\n            name=\"goal_clarity\",\n            clarity_score=1.0 - state.ambiguity_score,\n            weight=0.40,\n            justification=\"Loaded from stored interview ambiguity score\",\n        ),\n        constraint_clarity=ComponentScore(\n            name=\"constraint_clarity\",\n            clarity_score=1.0 - state.ambiguity_score,\n            weight=0.30,\n            justification=\"Loaded from stored interview ambiguity score\",\n        ),\n        success_criteria_clarity=ComponentScore(\n            name=\"success_criteria_clarity\",\n            clarity_score=1.0 - state.ambiguity_score,\n            weight=0.30,\n            justification=\"Loaded from stored interview ambiguity score\",\n        ),\n    )\n    return AmbiguityScore(\n        overall_score=state.ambiguity_score,\n        breakdown=breakdown,\n    )\n\n\ndef _stored_ambiguity_snapshot_is_degraded(state: InterviewState) -> bool:\n    \"\"\"Return True when stored ambiguity data lacks a parseable breakdown.\"\"\"\n    if state.ambiguity_score is None:\n        return True\n    if not isinstance(state.ambiguity_breakdown, dict):\n        return True\n\n    try:\n        ScoreBreakdown.model_validate(state.ambiguity_breakdown)\n    except PydanticValidationError:\n        return True\n\n    return False\n\n\ndef _format_interview_transcript(\n    state: InterviewState, *, withhold_observations: bool = False\n) -> str:\n    \"\"\"Format persisted interview rounds as a readable transcript for subagent context.\n\n    Two call sites with different roles read this one formatter. Seed generation\n    is a requirement-producing consumer and passes ``withhold_observations``; the\n    interview subagent's conversation history does not, because the interview\n    keeps seeing observations in full — informing the next question is what they\n    were collected for (#1755). Question lines are unchanged either way.\n    \"\"\"\n    if not state.rounds:\n        return \"\"\n    if withhold_observations:\n        rendered = [\n            (item.round_number, item.question, item.answer) for item in extraction_rounds(state)\n        ]\n    else:\n        rendered = [(r.round_number, r.question, r.user_response) for r in state.rounds]\n    lines: list[str] = []\n    if state.initial_context:\n        lines.append(f\"**Initial Context:** {state.initial_context}\")\n        lines.append(\"\")\n    for round_number, question, answer in rendered:\n        lines.append(f\"**Q{round_number}:** {question}\")\n        if answer:\n            lines.append(f\"**A{round_number}:** {answer}\")\n        lines.append(\"\")\n    return \"\\n\".join(lines).rstrip()\n\n\nasync def _plugin_save_state(state_dir: Path, state: InterviewState) -> Result[Path, str]:\n    \"\"\"Persist interview state without needing InterviewEngine (no LLM dep).\n\n    Used exclusively in the plugin dispatch path where litellm may not be\n    installed. Returns Result so callers can propagate persistence failures.\n    \"\"\"\n    try:\n        file_path = state_dir / f\"interview_{state.interview_id}.json\"\n        state.mark_updated()\n        content = state.model_dump_json(indent=2)\n\n        def _sync_write() -> bool:\n            # The plugin transport persists the same transcript the stdio one\n            # does, so it uses the same owner-only writer. This fourth site was\n            # still on write_text and produced 0644 under a 022 umask.\n            secure_directory(file_path.parent)\n            return write_owner_only(file_path, content)\n\n        durability_confirmed = await asyncio.to_thread(_sync_write)\n        if not durability_confirmed:\n            # The stdio writer logs this state; discarding it here reported a\n            # durability the filesystem never confirmed.\n            log.warning(\n                \"plugin.state_save_durability_uncertain\",\n                interview_id=state.interview_id,\n                file_path=str(file_path),\n            )\n        return Result.ok(file_path)\n    except (OSError, ValueError) as e:\n        return Result.err(f\"Failed to save interview state: {e}\")\n\n\nasync def _plugin_load_state(state_dir: Path, interview_id: str) -> Result[InterviewState, str]:\n    \"\"\"Load interview state without needing InterviewEngine (no LLM dep).\n\n    Used exclusively in the plugin dispatch path.\n    \"\"\"\n    file_path = state_dir / f\"interview_{interview_id}.json\"\n    if not file_path.exists():\n        return Result.err(f\"Interview state not found: {interview_id}\")\n    try:\n\n        def _sync_read() -> str:\n            return file_path.read_text(encoding=\"utf-8\")\n\n        content = await asyncio.to_thread(_sync_read)\n        state = InterviewState.model_validate_json(content)\n        state.discard_stale_requirement_distillation()\n        return Result.ok(state)\n    except (OSError, ValueError) as e:\n        return Result.err(f\"Failed to load interview state: {e}\")\n\n\n@dataclass\nclass GenerateSeedHandler:\n    \"\"\"Handler for the ouroboros_generate_seed tool.\n\n    Converts a completed interview session into an immutable Seed specification.\n    The seed generation gates on ambiguity score (must be <= 0.2).\n    \"\"\"\n\n    interview_engine: InterviewEngine | None = field(default=None, repr=False)\n    seed_generator: SeedGenerator | None = field(default=None, repr=False)\n    llm_adapter: LLMAdapter | None = field(default=None, repr=False)\n    llm_backend: str | None = field(default=None, repr=False)\n    event_store: EventStore | None = field(default=None, repr=False)\n    data_dir: Path | None = field(default=None, repr=False)\n    agent_runtime_backend: str | None = field(default=None, repr=False)\n    opencode_mode: str | None = field(default=None, repr=False)\n\n    def _build_ambiguity_score_from_value(self, ambiguity_score_value: float) -> AmbiguityScore:\n        \"\"\"Build an ambiguity score object from an explicit numeric override.\"\"\"\n        breakdown = ScoreBreakdown(\n            goal_clarity=ComponentScore(\n                name=\"goal_clarity\",\n                clarity_score=1.0 - ambiguity_score_value,\n                weight=0.40,\n                justification=\"Provided as input parameter\",\n            ),\n            constraint_clarity=ComponentScore(\n                name=\"constraint_clarity\",\n                clarity_score=1.0 - ambiguity_score_value,\n                weight=0.30,\n                justification=\"Provided as input parameter\",\n            ),\n            success_criteria_clarity=ComponentScore(\n                name=\"success_criteria_clarity\",\n                clarity_score=1.0 - ambiguity_score_value,\n                weight=0.30,\n                justification=\"Provided as input parameter\",\n            ),\n        )\n        return AmbiguityScore(\n            overall_score=ambiguity_score_value,\n            breakdown=breakdown,\n        )\n\n    def _load_stored_ambiguity_score(self, state: InterviewState) -> AmbiguityScore | None:\n        \"\"\"Load a persisted ambiguity score snapshot from interview state.\"\"\"\n        if state.ambiguity_score is None:\n            return None\n\n        if isinstance(state.ambiguity_breakdown, dict):\n            try:\n                breakdown = ScoreBreakdown.model_validate(state.ambiguity_breakdown)\n            except PydanticValidationError:\n                log.warning(\n                    \"mcp.tool.generate_seed.invalid_stored_ambiguity_breakdown\",\n                    session_id=state.interview_id,\n                )\n            else:\n                return AmbiguityScore(\n                    overall_score=state.ambiguity_score,\n                    breakdown=breakdown,\n                )\n\n        return self._build_ambiguity_score_from_value(state.ambiguity_score)\n\n    @property\n    def definition(self) -> MCPToolDefinition:\n        \"\"\"Return the tool definition.\"\"\"\n        return MCPToolDefinition(\n            name=\"ouroboros_generate_seed\",\n            description=(\n                \"Generate an immutable Seed from a completed interview session, \"\n                \"OR crystallize one directly from already-settled session context \"\n                \"with NO interview (pass session_context instead of session_id; \"\n                \"deterministic — material enters the Seed verbatim, and an \"\n                \"incomplete submission returns gap questions, not a block). Offer \"\n                \"that proactively once goal, constraints, and success criteria are \"\n                \"settled; a Seed is useful even without running it. Interview \"\n                \"path requires ambiguity_score <= 0.2 unless force=true.\"\n            ),\n            parameters=(\n                MCPToolParameter(\n                    name=\"session_id\",\n                    type=ToolInputType.STRING,\n                    description=(\n                        \"Interview session ID to convert to a seed. Required \"\n                        \"unless session_context is provided.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"session_context\",\n                    type=ToolInputType.OBJECT,\n                    description=(\n                        \"Interview-less path: settled material from THIS session. \"\n                        \"Keys: goal (required), acceptance_criteria (required, \"\n                        \"verifiable checks), constraints, decisions (become \"\n                        \"constraints), project_type. Anchored verbatim — supply \"\n                        \"the user's own settled wording, never your paraphrase.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"ambiguity_score\",\n                    type=ToolInputType.NUMBER,\n                    description=(\n                        \"Ambiguity score for the interview (0.0 = clear, 1.0 = ambiguous). \"\n                        \"Required if interview didn't calculate it. Generation fails if > 0.2.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"client_gates\",\n                    type=ToolInputType.ARRAY,\n                    description=(\n                        \"Client-side interview gates acknowledged before seed generation. \"\n                        \"Expected values include seed_ready_acceptance_guard and \"\n                        \"restate_goal_approved.\"\n                    ),\n                    required=False,\n                    items={\"type\": \"string\"},\n                ),\n                MCPToolParameter(\n                    name=\"force\",\n                    type=ToolInputType.BOOLEAN,\n                    description=(\n                        \"Bypass the ambiguity-score threshold and generate the seed even \"\n                        \"when ambiguity_score > 0.2. Mirrors the CLI 'Generate Seed anyway' \"\n                        \"opt-in: the real score is still recorded in seed metadata for \"\n                        \"provenance, and the bypass is emitted to the audit log. \"\n                        \"Defaults to false.\"\n                    ),\n                    required=False,\n                ),\n            ),\n        )\n\n    def _handle_session_context_seed(self, ctx: Any) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Interview-less crystallization (RFC D6) — see session_seed_handler.\"\"\"\n        from ouroboros.mcp.tools.session_seed_handler import handle_session_context_seed\n\n        return handle_session_context_seed(ctx)\n\n    async def handle(\n        self,\n        arguments: dict[str, Any],\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Handle a seed generation request.\n\n        Args:\n            arguments: Tool arguments including session_id and optional ambiguity_score.\n\n        Returns:\n            Result containing generated Seed YAML or error.\n        \"\"\"\n        session_id = arguments.get(\"session_id\")\n        session_context = arguments.get(\"session_context\")\n        if session_context is not None and not session_id:\n            return self._handle_session_context_seed(session_context)\n        if not session_id:\n            return Result.err(\n                MCPToolError(\n                    \"session_id is required (or pass session_context for the interview-less path)\",\n                    tool_name=\"ouroboros_generate_seed\",\n                )\n            )\n\n        ambiguity_score_value = arguments.get(\"ambiguity_score\")\n        force = bool(arguments.get(\"force\", False))\n        client_gate_status = get_client_gate_status(arguments)\n        client_gate_error = _client_gate_error(client_gate_status)\n        if client_gate_error is not None:\n            return Result.err(client_gate_error)\n\n        log.info(\n            \"mcp.tool.generate_seed\",\n            session_id=session_id,\n            ambiguity_score=ambiguity_score_value,\n            force=force,\n        )\n        if force:\n            log.warning(\n                \"mcp.tool.generate_seed.force_bypass\",\n                session_id=session_id,\n                caller_ambiguity_score=ambiguity_score_value,\n            )\n\n        # --- Subagent dispatch: gate on runtime + opencode_mode ---\n        if should_dispatch_via_plugin(self.agent_runtime_backend, self.opencode_mode):\n            # Plugin mode: validate interview readiness server-side before\n            # delegating.  The subprocess path loads state + computes/checks\n            # ambiguity via litellm.  Plugin can't compute ambiguity (no\n            # litellm), so we accept three evidence sources:\n            #   1. Caller-supplied ambiguity_score (from parent LLM output)\n            #   2. Persisted score on state (set by prior subprocess run)\n            #   3. Round count — at least one answered round means the\n            #      interview happened; the child validates completeness.\n            state_dir = self.data_dir or _DATA_DIR\n            load_result = await _plugin_load_state(state_dir, session_id)\n            if load_result.is_err:\n                return Result.err(\n                    MCPToolError(\n                        f\"Failed to load interview state: {load_result.error}\",\n                        tool_name=\"ouroboros_generate_seed\",\n                    )\n                )\n            interview_state = load_result.value\n\n            # Determine best available ambiguity score for the gate.\n            _THRESHOLD = 0.2\n            effective_score = ambiguity_score_value  # caller-supplied\n            if effective_score is None:\n                effective_score = interview_state.ambiguity_score  # persisted\n\n            # force=True intentionally bypasses BOTH the ambiguity threshold\n            # AND the \"no score / no answered rounds\" completeness guard for\n            # this plugin path — broader than #1107's domain-layer scope, but\n            # matches the CLI ``init`` \"Generate Seed anyway\" opt-in which\n            # forwards the same flag past the same guards. The real ambiguity\n            # score is still recorded in seed metadata for provenance and the\n            # bypass is emitted to the audit log.\n            if not interview_state.is_complete and not force:\n                answered_rounds = [r for r in interview_state.rounds if r.user_response is not None]\n                if effective_score is not None:\n                    # Have a score — enforce threshold\n                    if effective_score > _THRESHOLD:\n                        return Result.err(\n                            MCPToolError(\n                                f\"Ambiguity score {effective_score:.2f} exceeds \"\n                                f\"threshold {_THRESHOLD}. Continue interviewing \"\n                                f\"to reduce ambiguity before seed generation, \"\n                                f\"or pass force=true to bypass the gate.\",\n                                tool_name=\"ouroboros_generate_seed\",\n                            )\n                        )\n                elif not answered_rounds:\n                    # No score AND no rounds — nothing to generate from\n                    return Result.err(\n                        MCPToolError(\n                            \"Interview has no answered rounds and no ambiguity \"\n                            \"score. Complete at least one interview round before \"\n                            \"generating a seed.\",\n                            tool_name=\"ouroboros_generate_seed\",\n                        )\n                    )\n\n            transcript = _format_interview_transcript(interview_state, withhold_observations=True)\n            distillation = build_requirement_distillation(interview_state)\n            from ouroboros.core.requirement_candidate import evaluate_promotion\n\n            promotion = evaluate_promotion(distillation)\n            reference_aware = is_reference_aware_distillation(distillation)\n            details = seed_readiness_details(\n                promotion,\n                require_promoted_acceptance_criteria=reference_aware,\n            )\n            if details[\"blockers\"]:\n                return Result.err(\n                    MCPToolError(\n                        \"Interview must be reopened before Seed generation\",\n                        tool_name=\"ouroboros_generate_seed\",\n                        error_code=\"interview_reopen_required\",\n                        details=details,\n                    )\n                )\n            interview_state.requirement_distillation = distillation\n            cache_save_result = await _plugin_save_state(state_dir, interview_state)\n            if cache_save_result.is_err:\n                log.warning(\n                    \"mcp.tool.generate_seed.persist_distillation_failed\",\n                    session_id=session_id,\n                    error=str(cache_save_result.error),\n                )\n\n            if reference_aware:\n                reference_seed = build_promoted_reference_seed(\n                    interview_state,\n                    distillation,\n                    ambiguity_score=float(effective_score if effective_score is not None else 0.15),\n                    gate_forced=force,\n                )\n                seed_yaml = yaml.dump(\n                    reference_seed.to_dict(),\n                    default_flow_style=False,\n                    allow_unicode=True,\n                    sort_keys=False,\n                )\n                result_text = (\n                    _client_gate_warning_text(client_gate_status) + \"Seed Generated Successfully\\n\"\n                    \"=========================\\n\"\n                    f\"Seed ID: {reference_seed.metadata.seed_id}\\n\"\n                    f\"Interview ID: {reference_seed.metadata.interview_id}\\n\"\n                    f\"Ambiguity Score: {reference_seed.metadata.ambiguity_score:.2f}\\n\"\n                    f\"Goal: {reference_seed.goal}\\n\\n\"\n                    \"--- Seed YAML ---\\n\"\n                    f\"{seed_yaml}\"\n                )\n                return Result.ok(\n                    MCPToolResult(\n                        content=(MCPContentItem(type=ContentType.TEXT, text=result_text),),\n                        is_error=False,\n                        meta={\n                            \"seed_id\": reference_seed.metadata.seed_id,\n                            \"interview_id\": reference_seed.metadata.interview_id,\n                            \"ambiguity_score\": reference_seed.metadata.ambiguity_score,\n                            \"force\": force,\n                            \"gate_forced\": force,\n                            \"requirement_distillation\": distillation.model_dump(mode=\"json\"),\n                            **client_gate_status,\n                        },\n                    )\n                )\n\n            payload = build_generate_seed_subagent(\n                session_id=session_id,\n                ambiguity_score=effective_score,\n                transcript=transcript,\n                client_gates=client_gate_status[\"accepted_client_gates\"],\n                force=force,\n                requirement_distillation=(distillation if interview_state.reference_cues else None),\n            )\n            return await dispatch_plugin_terminal(\n                self.event_store,\n                session_id=session_id,\n                payload=payload,\n                response_shape={\n                    \"session_id\": session_id,\n                    \"status\": DELEGATED_TO_SUBAGENT,\n                    \"dispatch_mode\": \"plugin\",\n                    \"force\": force,\n                    \"gate_forced\": force,\n                    **client_gate_status,\n                },\n            )\n\n        # Fall-through: real in-process seed generation (subprocess / non-opencode runtimes).\n\n        try:\n            backend = _handler_llm_backend(self.llm_backend, \"seed_generation\")\n            # Use injected or create services.\n            # ``allowed_tools=[]`` paired with ``max_turns=1``: any tool-use\n            # block emitted by the model would consume the only allowed turn\n            # and the SDK then raises ``Reached maximum number of turns (1)``\n            # before a final text response can stream. See issue #781.\n            llm_adapter = self.llm_adapter or create_llm_adapter(\n                backend=backend,\n                max_turns=1,\n                allowed_tools=[]\n                if backend_supports_tool_envelope(resolve_llm_backend(backend))\n                else None,\n            )\n            interview_engine = self.interview_engine or InterviewEngine(\n                llm_adapter=llm_adapter,\n                model=get_llm_model_for_role(\"interview\", backend=backend),\n            )\n\n            # Load interview state\n            state_result = await interview_engine.load_state(session_id)\n\n            if state_result.is_err:\n                return Result.err(\n                    MCPToolError(\n                        f\"Failed to load interview state: {state_result.error}\",\n                        tool_name=\"ouroboros_generate_seed\",\n                    )\n                )\n\n            state: InterviewState = state_result.value\n\n            # Always use a trusted ambiguity score: persisted snapshot or\n            # freshly computed.  The caller-supplied ``ambiguity_score``\n            # parameter is intentionally ignored to prevent LLM callers\n            # from overriding the gate with an arbitrary low value.\n            # See: https://github.com/Q00/ouroboros/issues/210\n            if ambiguity_score_value is not None:\n                log.warning(\n                    \"mcp.tool.generate_seed.ignoring_caller_ambiguity_score\",\n                    session_id=session_id,\n                    caller_value=ambiguity_score_value,\n                )\n\n            ambiguity_score = self._load_stored_ambiguity_score(state)\n            if ambiguity_score is None:\n                scorer = AmbiguityScorer(\n                    llm_adapter=llm_adapter,\n                    model=get_llm_model_for_role(\"clarification\", backend=backend),\n                )\n                score_result = await scorer.score(state)\n                if score_result.is_err:\n                    return Result.err(\n                        MCPToolError(\n                            f\"Failed to calculate ambiguity: {score_result.error}\",\n                            tool_name=\"ouroboros_generate_seed\",\n                        )\n                    )\n\n                ambiguity_score = score_result.value\n                state.store_ambiguity(\n                    score=ambiguity_score.overall_score,\n                    breakdown=ambiguity_score.breakdown.model_dump(mode=\"json\"),\n                )\n                save_result = await interview_engine.save_state(state)\n                if save_result.is_err:\n                    log.warning(\n                        \"mcp.tool.generate_seed.persist_ambiguity_failed\",\n                        session_id=session_id,\n                        error=str(save_result.error),\n                    )\n\n            # Use injected or create seed generator\n            generator = self.seed_generator or SeedGenerator(\n                llm_adapter=llm_adapter,\n                model=get_llm_model_for_role(\"seed_generation\", backend=backend),\n            )\n\n            # Generate seed; force bypasses the ambiguity threshold gate inside\n            # SeedGenerator.generate while still stamping the real score into\n            # SeedMetadata for provenance.\n            seed_result = await generator.generate(state, ambiguity_score, force=force)\n\n            if seed_result.is_err:\n                error = seed_result.error\n                if isinstance(error, ValidationError):\n                    readiness_code = error.details.get(\"code\")\n                    return Result.err(\n                        MCPToolError(\n                            f\"Validation error: {error}\",\n                            tool_name=\"ouroboros_generate_seed\",\n                            error_code=(\n                                readiness_code\n                                if readiness_code == \"interview_reopen_required\"\n                                else None\n                            ),\n                            details=(\n                                error.details\n                                if readiness_code == \"interview_reopen_required\"\n                                else None\n                            ),\n                        )\n                    )\n                return Result.err(\n                    MCPToolError(\n                        f\"Failed to generate seed: {error}\",\n                        tool_name=\"ouroboros_generate_seed\",\n                    )\n                )\n\n            seed = seed_result.value\n            # Convert seed to YAML\n            seed_dict = seed.to_dict()\n            seed_yaml = yaml.dump(\n                seed_dict,\n                default_flow_style=False,\n                allow_unicode=True,\n                sort_keys=False,\n            )\n\n            result_text = (\n                _client_gate_warning_text(client_gate_status) + f\"Seed Generated Successfully\\n\"\n                f\"=========================\\n\"\n                f\"Seed ID: {seed.metadata.seed_id}\\n\"\n                f\"Interview ID: {seed.metadata.interview_id}\\n\"\n                f\"Ambiguity Score: {seed.metadata.ambiguity_score:.2f}\\n\"\n                f\"Goal: {seed.goal}\\n\\n\"\n                f\"--- Seed YAML ---\\n\"\n                f\"{seed_yaml}\"\n            )\n\n            return Result.ok(\n                MCPToolResult(\n                    content=(MCPContentItem(type=ContentType.TEXT, text=result_text),),\n                    is_error=False,\n                    meta={\n                        \"seed_id\": seed.metadata.seed_id,\n                        \"interview_id\": seed.metadata.interview_id,\n                        \"ambiguity_score\": seed.metadata.ambiguity_score,\n                        \"force\": force,\n                        \"gate_forced\": force,\n                        \"requirement_distillation\": (\n                            state.requirement_distillation.model_dump(mode=\"json\")\n                            if state.requirement_distillation is not None\n                            else None\n                        ),\n                        **client_gate_status,\n                    },\n                )\n            )\n\n        except Exception as e:\n            log.error(\"mcp.tool.generate_seed.error\", error=str(e))\n            return Result.err(\n                MCPToolError(\n                    f\"Seed generation failed: {e}\",\n                    tool_name=\"ouroboros_generate_seed\",\n                )\n            )\n\n\n@dataclass\nclass InterviewHandler:\n    \"\"\"Handler for the ouroboros_interview tool.\n\n    Manages interactive interviews for requirement clarification.\n    Supports starting new interviews, resuming existing sessions,\n    and recording responses to questions.\n    \"\"\"\n\n    interview_engine: InterviewEngine | None = field(default=None, repr=False)\n    event_store: EventStore | None = field(default=None, repr=False)\n    llm_adapter: LLMAdapter | None = field(default=None, repr=False)\n    llm_backend: str | None = field(default=None, repr=False)\n    agent_runtime_backend: str | None = field(default=None, repr=False)\n    opencode_mode: str | None = field(default=None, repr=False)\n    data_dir: Path | None = field(default=None, repr=False)\n    fanout_registry: FanoutRegistry | None = field(default=None, repr=False)\n    suppress_tool_use_prompt_cues: bool = False\n    findings_store: Any | None = field(default=None, repr=False)\n\n    def __post_init__(self) -> None:\n        \"\"\"Initialize event store.\"\"\"\n        self._owns_event_store = self.event_store is None\n        self._event_store = self.event_store or EventStore()\n        self._initialized = False\n        self._closed = False\n        self._bg_tasks: set[asyncio.Task] = set()\n\n    async def _ensure_initialized(self) -> None:\n        \"\"\"Ensure the event store is initialized.\"\"\"\n        if not self._initialized:\n            await self._event_store.initialize()\n            self._initialized = True\n\n    async def _drain_bg_tasks(self, timeout: float = 5.0) -> None:\n        \"\"\"Await all pending background event tasks before shutdown.\"\"\"\n        if not self._bg_tasks:\n            return\n        tasks = list(self._bg_tasks)\n        done, pending = await asyncio.wait(tasks, timeout=timeout)\n        for t in pending:\n            t.cancel()\n        # Await cancelled tasks so CancelledError propagates cleanly\n        if pending:\n            await asyncio.gather(*pending, return_exceptions=True)\n        self._bg_tasks.clear()\n\n    async def close(self) -> None:\n        \"\"\"Drain pending event tasks, then close the event store if owned.\"\"\"\n        self._closed = True\n        await self._drain_bg_tasks()\n        if self._owns_event_store:\n            await self._event_store.close()\n            self._initialized = False\n\n    def resolved_state_dir(self) -> Path:\n        \"\"\"Return the directory the handler actually writes interview state to.\n\n        Single source of truth for the interview persistence location used\n        by collision checks, the auto-driver persistence probe, and the\n        plugin/subprocess save paths.  When an ``InterviewEngine`` is\n        injected (e.g. by ``create_ouroboros_server`` with a custom\n        ``state_dir``), the engine's directory wins — the handler's own\n        ``data_dir`` may be stale or unset.  See Q00/ouroboros#723 review.\n        \"\"\"\n        if self.interview_engine is not None:\n            return self.interview_engine.state_dir\n        return self.data_dir or _DATA_DIR\n\n    def _resolved_fanout_registry(self) -> FanoutRegistry | None:\n        \"\"\"Return the fan-out registry rooted under the handler's real data dir.\n\n        The server factory constructs the shared ``FanoutRegistry`` before the\n        interview state dir is known, so a default-located registry is re-rooted\n        onto ``resolved_state_dir()/fanout`` here — the same substrate interview\n        state JSON is written to. Explicitly-located registries (tests, custom\n        wiring) are left untouched, and since producers and the submit handler\n        share one instance, re-entry reads the same directory.\n        \"\"\"\n        registry = self.fanout_registry\n        if registry is not None:\n            registry.rebase_default(self.resolved_state_dir() / \"fanout\")\n        return registry\n\n    async def _emit_event(self, event: Any) -> None:\n        \"\"\"Emit event to store. Swallows errors to not break interview flow.\"\"\"\n        try:\n            await self._ensure_initialized()\n            await self._event_store.append(event)\n        except Exception as e:\n            log.warning(\"mcp.tool.interview.event_emission_failed\", error=str(e))\n\n    def _emit_event_bg(self, event: Any) -> None:\n        \"\"\"Fire-and-forget event emission — non-blocking on the hot path.\"\"\"\n        if self._closed:\n            return\n        task = asyncio.create_task(self._emit_event(event))\n        self._bg_tasks.add(task)\n        task.add_done_callback(self._bg_tasks.discard)\n\n    @staticmethod\n    def _apply_interview_score(\n        state: InterviewState,\n        score: AmbiguityScore,\n        *,\n        advance_streak: bool = True,\n        reset_on_failure: bool = True,\n    ) -> None:\n        \"\"\"Apply one canonical ambiguity result to persisted interview state.\"\"\"\n        qualifies = qualifies_for_seed_completion(score, is_brownfield=state.is_brownfield)\n        if advance_streak:\n            _update_completion_candidate_streak(state, score)\n        elif reset_on_failure and not qualifies:\n            _reset_stale_completion_streak(state)\n        state.store_ambiguity(\n            score=score.overall_score,\n            breakdown=score.breakdown.model_dump(mode=\"json\"),\n        )\n\n    async def _score_interview_state(\n        self,\n        llm_adapter: LLMAdapter,\n        state: InterviewState,\n        *,\n        advance_streak: bool = True,\n        reset_on_failure: bool = True,\n    ) -> AmbiguityScore | None:\n        \"\"\"Calculate and cache the latest ambiguity snapshot for interview routing.\n\n        The streak update is controlled by two orthogonal flags so callers\n        can disable the qualifying-score increment without also disabling\n        the failure/non-qualifying invalidation — a requirement of the\n        explicit ``done`` branch, which owns the increment itself but still\n        relies on the scorer to reset a stale streak when the live rescore\n        is weak or fails.\n\n        Args:\n            advance_streak: When ``True`` (default) a qualifying score\n                bumps ``state.completion_candidate_streak`` by one. Set to\n                ``False`` on paths that own the increment themselves (the\n                explicit ``done`` branch) so the streak is not double-\n                bumped between this helper and the caller.\n            reset_on_failure: When ``True`` (default) a scorer error or a\n                non-qualifying score clears any existing streak — the\n                single shared \"stale-streak invalidation\" rule across all\n                explicit-done and normal-answer flows. Only pass ``False``\n                if a caller needs to observe the current streak across a\n                transient scoring failure without losing it; in practice\n                no live caller does.\n        \"\"\"\n        backend = _handler_llm_backend(self.llm_backend, \"clarification\")\n        scorer = AmbiguityScorer(\n            llm_adapter=llm_adapter,\n            model=get_llm_model_for_role(\"clarification\", backend=backend),\n            max_retries=_LIVE_AMBIGUITY_MAX_RETRIES,\n        )\n        score_result = await scorer.score(state)\n        if score_result.is_err:\n            state.clear_stored_ambiguity()\n            if reset_on_failure:\n                _reset_stale_completion_streak(state)\n            log.warning(\n                \"mcp.tool.interview.live_ambiguity_failed\",\n                interview_id=state.interview_id,\n                error=str(score_result.error),\n            )\n            return None\n\n        score = score_result.value\n        self._apply_interview_score(\n            state,\n            score,\n            advance_streak=advance_streak,\n            reset_on_failure=reset_on_failure,\n        )\n        return score\n\n    @staticmethod\n    def _parent_question_handoff_response(\n        state: InterviewState,\n        session_id: str,\n        *,\n        phase: str,\n        score: AmbiguityScore | None,\n        error: Any,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Build a non-error response asking the parent session to ask the user.\"\"\"\n        provider_error_type = _provider_error_type(error)\n        return Result.ok(\n            MCPToolResult(\n                content=(\n                    MCPContentItem(\n                        type=ContentType.TEXT,\n                        text=(\n                            f\"Session {session_id}\\n\\n\"\n                            \"Ask the user exactly one natural Socratic clarification \"\n                            \"question yourself. Do not mention MCP, provider failures, \"\n                            \"tool envelopes, retries, or internal recovery. When the \"\n                            \"user answers, call ouroboros_interview with \"\n                            f'session_id=\"{session_id}\", answer=<user answer>, and '\n                            \"last_question=<the exact question you asked>.\"\n                        ),\n                    ),\n                ),\n                is_error=False,\n                meta={\n                    \"session_id\": session_id,\n                    \"status\": \"parent_question_required\",\n                    \"recoverable\": True,\n                    \"retry_mcp\": False,\n                    \"ask_user_directly\": True,\n                    \"last_question_required\": True,\n                    \"reason_code\": _QUESTION_GENERATION_ENVELOPE_REASON_CODE,\n                    \"question_source\": \"parent_session\",\n                    \"provider_error_type\": provider_error_type,\n                    \"ambiguity_score\": score.overall_score if score is not None else None,\n                    \"milestone\": _milestone_for_score(score),\n                    \"seed_ready\": score.is_ready_for_seed if score is not None else None,\n                    **_interview_reasoning_meta(\n                        state=state,\n                        session_id=session_id,\n                        phase=phase,\n                        next_action=(\n                            \"ask one direct user question, then resume with last_question\"\n                        ),\n                        score=score,\n                        recoverable=True,\n                    ),\n                },\n            )\n        )\n\n    @staticmethod\n    def _ambiguity_gate_response(\n        session_id: str,\n        score: AmbiguityScore | None,\n        *,\n        state: InterviewState | None = None,\n        is_brownfield: bool,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Build an MCP response refusing premature interview completion.\"\"\"\n        score_display = f\"{score.overall_score:.2f}\" if score is not None else \"unknown\"\n        gate_reason = _completion_gate_reason(score, is_brownfield=is_brownfield)\n        return Result.ok(\n            MCPToolResult(\n                content=(\n                    MCPContentItem(\n                        type=ContentType.TEXT,\n                        text=(\n                            f\"Cannot complete yet — {gate_reason}. \"\n                            f\"Current ambiguity: {score_display}. \"\n                            f\"Please answer a few more questions to \"\n                            f\"clarify remaining areas.\"\n                        ),\n                    ),\n                ),\n                is_error=False,\n                meta={\n                    \"session_id\": session_id,\n                    \"ambiguity_score\": (score.overall_score if score is not None else None),\n                    \"milestone\": _milestone_for_score(score),\n                    \"seed_ready\": False,\n                    **_interview_reasoning_meta(\n                        state=state,\n                        session_id=session_id,\n                        phase=\"completion_gate\",\n                        next_action=\"ask another clarification question\",\n                        score=score,\n                    ),\n                },\n            )\n        )\n\n    async def _complete_interview_response(\n        self,\n        engine: InterviewEngine,\n        state: InterviewState,\n        session_id: str,\n        score: AmbiguityScore | None = None,\n        *,\n        seed_ready_override: bool | None = None,\n        turn_started_at: float | None = None,\n        ambiguity_scoring_duration_ms: float | None = None,\n        question_generation_duration_ms: float | None = None,\n        advisory_build_duration_ms: float | None = None,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Complete the interview and return a Seed-ready MCP response.\"\"\"\n        complete_result = await engine.complete_interview(state)\n        if complete_result.is_err:\n            if turn_started_at is not None:\n                from ouroboros.events.interview import interview_failed\n\n                self._emit_event_bg(\n                    interview_failed(\n                        session_id,\n                        _format_interview_failure_event_error(complete_result.error),\n                        phase=\"completion\",\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                        advisory_build_duration_ms=advisory_build_duration_ms,\n                    )\n                )\n            return Result.err(\n                MCPToolError(\n                    str(complete_result.error),\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n\n        state = complete_result.value\n        save_result = await engine.save_state(state)\n        if save_result.is_err:\n            log.warning(\n                \"mcp.tool.interview.save_failed_on_complete\",\n                error=str(save_result.error),\n            )\n\n        from ouroboros.events.interview import interview_completed\n\n        self._emit_event_bg(\n            interview_completed(\n                interview_id=session_id,\n                total_rounds=len(state.rounds),\n                total_duration_ms=(\n                    _elapsed_ms(turn_started_at) if turn_started_at is not None else None\n                ),\n                ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                question_generation_duration_ms=question_generation_duration_ms,\n                advisory_build_duration_ms=advisory_build_duration_ms,\n            )\n        )\n\n        score_line = \"\"\n        if score is not None:\n            score_line = f\"(ambiguity: {score.overall_score:.2f}) Ready for Seed generation.\\n\"\n\n        return Result.ok(\n            MCPToolResult(\n                content=(\n                    MCPContentItem(\n                        type=ContentType.TEXT,\n                        text=(\n                            f\"Interview completed. Session ID: {session_id}\\n\\n\"\n                            f\"{score_line}\"\n                            f'Generate a Seed with: session_id=\"{session_id}\"'\n                        ),\n                    ),\n                ),\n                is_error=False,\n                meta={\n                    \"session_id\": session_id,\n                    \"completed\": True,\n                    \"ambiguity_score\": score.overall_score if score is not None else None,\n                    \"milestone\": _milestone_for_score(score),\n                    \"seed_ready\": (\n                        seed_ready_override\n                        if seed_ready_override is not None\n                        else score.is_ready_for_seed\n                        if score is not None\n                        else None\n                    ),\n                    \"required_client_gates\": REQUIRED_CLIENT_GATES,\n                    **_interview_reasoning_meta(\n                        state=state,\n                        session_id=session_id,\n                        phase=\"complete\",\n                        next_action=\"generate seed after client gates\",\n                        score=score,\n                    ),\n                },\n            )\n        )\n\n    @property\n    def definition(self) -> MCPToolDefinition:\n        \"\"\"Return the tool definition.\"\"\"\n        return MCPToolDefinition(\n            name=\"ouroboros_interview\",\n            description=(\n                \"Clarify a vague request before any implementation. Use when: the user wants \"\n                'something built but is unsure what (\"help me figure out what to build\", \"add '\n                'notifications\", \"make it production-ready\", \"build me X\"), the request is '\n                \"ambiguous, or it lacks acceptance criteria; call it first, even if the user never \"\n                \"says 'ooo'. Result: a short Socratic interview, one question at a time, that \"\n                \"closes goals, constraints, and acceptance criteria, ready for Seed generation. Do \"\n                \"not use when: a validated Seed already exists (use ouroboros_start_execute_seed) \"\n                \"or the request is a simple question or small unambiguous edit. Start a new \"\n                \"interview with initial_context, resume with session_id, or record an answer to \"\n                \"the current question. In plugin mode, returns a delegation receipt \"\n                \"(status=delegated_to_subagent) and the interview executes in an OpenCode Task \"\n                \"pane; the real session_id is returned there.\"\n            ),\n            parameters=(\n                MCPToolParameter(\n                    name=\"initial_context\",\n                    type=ToolInputType.STRING,\n                    description=\"Initial context to start a new interview session\",\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"session_id\",\n                    type=ToolInputType.STRING,\n                    description=\"Session ID to resume an existing interview\",\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"answer\",\n                    type=ToolInputType.STRING,\n                    description=\"Response to the current interview question\",\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"cwd\",\n                    type=ToolInputType.STRING,\n                    description=(\n                        \"Working directory for brownfield auto-detection. \"\n                        \"Defaults to the current working directory if not provided.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"last_question\",\n                    type=ToolInputType.STRING,\n                    description=(\n                        \"The question text from the previous child session's response. \"\n                        \"In plugin mode each dispatch creates a new child session whose \"\n                        \"questions are not automatically persisted server-side. Pass the \"\n                        \"child's last question here when submitting an answer so the \"\n                        \"interview transcript preserves the real question text instead \"\n                        \"of a placeholder.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"interview_id\",\n                    type=ToolInputType.STRING,\n                    description=(\n                        \"Optional caller-supplied id for a brand-new interview. \"\n                        \"Must match the server format 'interview_<16 lowercase hex>' \"\n                        \"and must NOT collide with an existing interview file. \"\n                        \"Only valid for the start action — supplying it together with \"\n                        \"session_id (resume) or answer is rejected with an error to \"\n                        \"prevent silent identifier hijacking; do not preserve this \"\n                        \"argument across turns. \"\n                        \"Used by the bounded auto driver to pre-allocate the id so a \"\n                        \"driver-level cancel cannot leave auto state out of sync with \"\n                        \"the persisted interview file (see Q00/ouroboros#687).\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"confused_terms\",\n                    type=ToolInputType.ARRAY,\n                    description=(\n                        \"Explicit domain terms the user says they do not understand. \"\n                        \"Queued on the start turn and applied only after the first answer.\"\n                    ),\n                    required=False,\n                    items={\"type\": \"string\"},\n                ),\n                MCPToolParameter(\n                    name=\"references\",\n                    type=ToolInputType.ARRAY,\n                    description=(\n                        \"Bounded user-provided reference cues. Each object requires \"\n                        \"reference_id, label, and origin; url/excerpt are optional.\"\n                    ),\n                    required=False,\n                    items={\"type\": \"object\"},\n                ),\n                *interview_calibration_parameters(),\n            ),\n        )\n\n    async def handle(\n        self,\n        arguments: dict[str, Any],\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Handle an interview request.\n\n        Args:\n            arguments: Tool arguments including initial_context, session_id, or answer.\n\n        Returns:\n            Result containing interview question and session_id or error.\n        \"\"\"\n        try:\n            turn_context = InterviewTurnContext.model_validate(\n                {\n                    \"confused_terms\": arguments.get(\"confused_terms\") or (),\n                    \"references\": arguments.get(\"references\") or (),\n                }\n            )\n        except PydanticValidationError as exc:\n            return Result.err(\n                MCPToolError(\n                    f\"Invalid interview adapter context: {exc}\",\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n        arguments = dict(arguments)\n        arguments[_NORMALIZED_TURN_CONTEXT_KEY] = turn_context\n\n        calibration_input = arguments.get(\"calibration_input\")\n        initial_context = arguments.get(\"initial_context\")\n        session_id = arguments.get(\"session_id\")\n        answer = arguments.get(\"answer\")\n        # Optional caller-supplied id for new interviews (Q00/ouroboros#687).\n        # Only honoured for the ``start`` action; ignored otherwise.\n        suggested_interview_id_arg = arguments.get(\"interview_id\")\n        suggested_interview_id = (\n            suggested_interview_id_arg\n            if isinstance(suggested_interview_id_arg, str) and suggested_interview_id_arg\n            else None\n        )\n        # Taken as given; whether it is a repair or an echo of our own output is\n        # settled where the round is identified.\n        last_question = arguments.get(\"last_question\")\n\n        # --- Argument validation (before any dispatch) ---\n        # Determine action from arguments\n        if isinstance(calibration_input, str) and calibration_input.strip():\n            action = \"calibrate\"\n        elif initial_context:\n            action = \"start\"\n        elif answer:\n            action = \"answer\"\n        else:\n            action = \"resume\"\n\n        # Reject invalid combos early — applies to both plugin and subprocess paths.\n        if action not in {\"start\", \"calibrate\"} and not session_id:\n            return Result.err(\n                MCPToolError(\n                    \"Must provide initial_context to start or session_id to resume\",\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n\n        # Validate caller-supplied ``interview_id`` strictly to keep the\n        # MCP contract narrow.  The id must match the server's own\n        # ``interview_<16 hex>`` format (matching ``uuid4().hex[:16]``)\n        # and must not collide with an existing on-disk interview file —\n        # this prevents cross-client spoofing/hijacking and accidental\n        # reuse of an active session.  Q00/ouroboros#723 review.\n        if suggested_interview_id is not None:\n            if action != \"start\":\n                return Result.err(\n                    MCPToolError(\n                        \"interview_id is only valid for new interviews; resume via session_id\",\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n            if not _SUGGESTED_INTERVIEW_ID_RE.fullmatch(suggested_interview_id):\n                return Result.err(\n                    MCPToolError(\n                        \"interview_id must match the server format 'interview_<16 hex>'\",\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n            collision_path = self.resolved_state_dir() / f\"interview_{suggested_interview_id}.json\"\n            if collision_path.exists():\n                return Result.err(\n                    MCPToolError(\n                        \"interview_id collides with an existing interview; pick a fresh id\",\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n\n        if action == \"calibrate\":\n            return await handle_interview_calibration_turn(\n                self,\n                calibration_input.strip(),\n                session_id=session_id,\n            )\n\n        # --- Subagent dispatch: gate on runtime + opencode_mode ---\n        if should_dispatch_via_plugin(self.agent_runtime_backend, self.opencode_mode):\n            return await self._handle_plugin_dispatch(\n                arguments,\n                action=action,\n                session_id=session_id,\n                initial_context=initial_context,\n                answer=answer,\n                last_question=last_question,\n                suggested_interview_id=suggested_interview_id,\n            )\n\n        # Fall-through: real in-process interview engine (subprocess / non-opencode runtimes).\n        if action == \"start\":\n            return await self._handle_start(\n                arguments,\n                initial_context=initial_context,\n                suggested_interview_id=suggested_interview_id,\n            )\n        if action == \"answer\":\n            return await self._handle_answer(\n                arguments,\n                session_id=session_id,\n                answer=answer,\n                last_question=last_question,\n            )\n        return await self._handle_resume(\n            arguments,\n            session_id=session_id,\n            answer=answer,\n            last_question=last_question,\n        )\n\n    async def _handle_plugin_dispatch(\n        self,\n        arguments: dict[str, Any],\n        *,\n        action: str,\n        session_id: Any,\n        initial_context: Any,\n        answer: Any,\n        last_question: Any,\n        suggested_interview_id: str | None,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Plugin-passive dispatch: persist state, delegate LLM work to a subagent.\"\"\"\n        # Plugin mode: persist state server-side WITHOUT creating an LLM adapter.\n        # Only state I/O is needed here — the subagent handles all LLM work.\n        # This avoids importing litellm (optional dep) on plugin-only installs.\n        # Route through ``resolved_state_dir`` so an injected\n        # ``InterviewEngine`` with a custom ``state_dir`` keeps plugin\n        # writes and the collision check on the same directory\n        # (Q00/ouroboros#723 review).\n        state_dir = self.resolved_state_dir()\n        state_dir.mkdir(parents=True, exist_ok=True)\n\n        transcript = \"\"\n        real_session_id = session_id\n        plugin_state: InterviewState | None = None\n        plugin_intent_guard_report: IntentGuardReport | None = None\n        turn_context = _normalized_turn_context(arguments)\n        adapter_question: str | None = None\n        plugin_state_changed = False\n\n        if action == \"start\" and initial_context:\n            cwd = arguments.get(\"cwd\") or os.getcwd()\n            resolved_context = resolve_initial_context_input(initial_context, cwd=cwd)\n            if resolved_context.is_err:\n                return Result.err(\n                    MCPToolError(\n                        str(resolved_context.error),\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n            # Pure state creation — mirrors InterviewEngine.start_interview()\n            from ouroboros.core.security import InputValidator\n\n            is_valid, error_msg = InputValidator.validate_initial_context(resolved_context.value)\n            if not is_valid:\n                return Result.err(MCPToolError(error_msg, tool_name=\"ouroboros_interview\"))\n            from uuid import uuid4\n\n            # Honour caller-supplied id when present (auto driver\n            # pre-allocates the id for Q00/ouroboros#687).  Fall back\n            # to a fresh uuid otherwise.\n            interview_id = suggested_interview_id or f\"interview_{uuid4().hex[:16]}\"\n            state = InterviewState(\n                interview_id=interview_id,\n                initial_context=resolved_context.value,\n            )\n            state.merge_turn_context(turn_context)\n            plugin_state = state\n            # Detect brownfield\n            if cwd:\n                from ouroboros.bigbang.explore import detect_brownfield\n\n                if detect_brownfield(cwd):\n                    state.is_brownfield = True\n                    state.codebase_paths = [{\"path\": cwd, \"role\": \"primary\"}]\n\n            # Persist — propagate failure instead of silently ignoring\n            save_result = await _plugin_save_state(state_dir, state)\n            if save_result.is_err:\n                return Result.err(\n                    MCPToolError(str(save_result.error), tool_name=\"ouroboros_interview\")\n                )\n            real_session_id = state.interview_id\n\n        elif session_id:\n            load_result = await _plugin_load_state(state_dir, session_id)\n            if load_result.is_err:\n                return Result.err(\n                    MCPToolError(str(load_result.error), tool_name=\"ouroboros_interview\")\n                )\n            state = load_result.value\n            plugin_state = state\n            plugin_state_changed = state.merge_turn_context(turn_context)\n            # Record answer into persisted state.\n            # In plugin mode each dispatch = new child session. The child\n            # generates questions but can't write back to server-side state.\n            # We must always persist user answers for transcript continuity.\n            #\n            # The ``last_question`` parameter solves the question-text gap:\n            # the parent LLM sees the child's response (which contains the\n            # question) and passes it back here so we can persist the real\n            # question text instead of a placeholder.\n            if answer:\n                if state.is_complete:\n                    state.status = InterviewStatus.IN_PROGRESS\n                    state.clear_stored_ambiguity()\n                    state.completion_candidate_streak = 0\n                # ``record_answer`` decides which shape this is — filling a\n                # round persisted question-only, or appending — and settles\n                # provenance where the answer arrives either way.\n                has_pending = bool(state.rounds) and state.rounds[-1].user_response is None\n                # Plugin persists no question-only round, so the second branch\n                # is the live one; the first needs state a subprocess turn left.\n                if has_pending:\n                    issued = state.rounds[-1].question\n                    question_text = (\n                        issued\n                        if echo_carries_dispatch(last_question)\n                        else (last_question or issued)\n                    )\n                else:\n                    # No record to prefer — cut the bridge's own append instead.\n                    question_text = (\n                        strip_bridge_notice(last_question) or \"(continued from subagent)\"\n                    )\n                plugin_intent_guard_report = _guard_interview_answer(\n                    state=state,\n                    question=question_text,\n                    answer=answer,\n                )\n                if plugin_intent_guard_report.status is IntentGuardStatus.FAIL:\n                    return Result.err(\n                        MCPToolError(\n                            _format_intent_guard_blocker(plugin_intent_guard_report),\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n                declare_provenance(state.record_answer(question_text, answer), arguments)\n                plugin_state_changed = True\n            # Build transcript from persisted rounds\n            transcript = _format_interview_transcript(state)\n\n        if plugin_state is not None:\n            adapter_question = plugin_state.next_adapter_question()\n            if adapter_question is not None or plugin_state_changed:\n                save_result = await _plugin_save_state(state_dir, plugin_state)\n                if save_result.is_err:\n                    return Result.err(\n                        MCPToolError(str(save_result.error), tool_name=\"ouroboros_interview\")\n                    )\n\n        payload = build_interview_subagent(\n            session_id=real_session_id or \"new\",\n            action=action,\n            initial_context=initial_context,\n            answer=answer,\n            cwd=arguments.get(\"cwd\"),\n            transcript=transcript,\n            turn_context=turn_context,\n            adapter_question=adapter_question,\n            language_calibration=normalize_interview_calibration(\n                arguments.get(\"interview_calibration\")\n            ),\n        )\n        return await dispatch_plugin_terminal(\n            self.event_store,\n            session_id=real_session_id,\n            payload=payload,\n            response_shape={\n                \"session_id\": real_session_id,\n                \"action\": action,\n                \"status\": DELEGATED_TO_SUBAGENT,\n                \"dispatch_mode\": \"plugin\",\n                \"question_advisory_strategy\": \"plugin_child_question_first_advisory\",\n                \"question_advisory_recommended\": True,\n                **_interview_reasoning_meta(\n                    state=plugin_state,\n                    session_id=real_session_id,\n                    phase=f\"plugin_{action}\",\n                    next_action=\"wait for OpenCode child interview response\",\n                ),\n                \"next_turn_hint\": (\n                    \"When the user answers, pass the child session's \"\n                    \"question text as 'last_question' alongside 'answer' \"\n                    \"to preserve interview transcript fidelity.\"\n                ),\n                **(\n                    {\"intent_guard\": plugin_intent_guard_report.to_dict()}\n                    if plugin_intent_guard_report is not None\n                    else {}\n                ),\n            },\n        )\n\n    def _create_interview_engine(self) -> tuple[Any, Any]:\n        \"\"\"Construct the in-process interview engine and its LLM adapter.\"\"\"\n        # One sealed turn makes MCP a pure question generator and prevents a\n        # child runtime from rediscovering this MCP server recursively (#765).\n        backend = _handler_llm_backend(self.llm_backend, \"interview\")\n        llm_adapter = self.llm_adapter or create_llm_adapter(\n            backend=backend,\n            max_turns=1,\n            use_case=\"interview\",\n            allowed_tools=(\n                [] if backend_supports_tool_envelope(resolve_llm_backend(backend)) else None\n            ),\n            strict_mcp_config=True,\n        )\n        # Pair a sealed catalog with the tool-less prompt; injected adapters\n        # retain the caller's prompt mode (#1537).\n        suppress_question_tool_cues = self.suppress_tool_use_prompt_cues or (\n            self.llm_adapter is None\n            and backend_supports_tool_envelope(resolve_llm_backend(backend))\n        )\n        # Clone real shared engines per call for concurrency safety. Test fakes\n        # and monkey-patched non-types pass through unchanged.\n        template = self.interview_engine\n        if (\n            template is not None\n            and isinstance(InterviewEngine, type)\n            and isinstance(template, InterviewEngine)\n        ):\n            engine = InterviewEngine(\n                llm_adapter=llm_adapter,\n                state_dir=template.state_dir,\n                model=template.model or get_llm_model_for_role(\"interview\", backend=backend),\n                suppress_tool_use_prompt_cues=suppress_question_tool_cues,\n            )\n            engine.temperature = template.temperature\n            engine.max_tokens = template.max_tokens\n        elif template is not None:\n            engine = template\n        else:\n            engine = InterviewEngine(\n                llm_adapter=llm_adapter,\n                state_dir=self.data_dir or _DATA_DIR,\n                model=get_llm_model_for_role(\"interview\", backend=backend),\n                suppress_tool_use_prompt_cues=suppress_question_tool_cues,\n            )\n        return engine, llm_adapter\n\n    async def _handle_start(\n        self,\n        arguments: dict[str, Any],\n        *,\n        initial_context: Any,\n        suggested_interview_id: str | None,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        turn_started_at = time.perf_counter()\n        engine, _ = self._create_interview_engine()\n        calibration = normalize_interview_calibration(arguments.get(\"interview_calibration\"))\n        _interview_id: str | None = None  # Track for error event emission\n        question_generation_duration_ms: float | None = None\n        advisory_build_duration_ms: float | None = None\n\n        try:\n            # Start new interview\n            if initial_context:\n                cwd = arguments.get(\"cwd\") or os.getcwd()\n                resolved_context = resolve_initial_context_input(initial_context, cwd=cwd)\n                if resolved_context.is_err:\n                    return Result.err(\n                        MCPToolError(\n                            str(resolved_context.error),\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n\n                result = await engine.start_interview(\n                    resolved_context.value,\n                    cwd=cwd,\n                    interview_id=suggested_interview_id,\n                )\n                if result.is_err:\n                    return Result.err(\n                        MCPToolError(\n                            str(result.error),\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n\n                state = result.value\n                if state.merge_turn_context(_normalized_turn_context(arguments)):\n                    merge_save_result = await engine.save_state(state)\n                    if merge_save_result.is_err:\n                        return Result.err(\n                            MCPToolError(\n                                str(merge_save_result.error),\n                                tool_name=\"ouroboros_interview\",\n                            )\n                        )\n                _interview_id = state.interview_id\n                # No answers exist yet — scoring cannot trigger completion\n                # and would waste an LLM call (~3-8s). The PM handler\n                # already skips scoring before MIN_ROUNDS_BEFORE_EARLY_EXIT\n                # (pm_interview.py:889); apply the same optimisation here.\n                live_score = None\n                question_generation_started_at = time.perf_counter()\n                try:\n                    question_result = await _ask_next_question(engine, state, calibration)\n                finally:\n                    question_generation_duration_ms = _elapsed_ms(question_generation_started_at)\n                if question_result.is_err:\n                    if _is_question_generation_envelope_violation(question_result.error):\n                        from ouroboros.events.interview import interview_question_parent_handoff\n\n                        self._emit_event_bg(\n                            interview_question_parent_handoff(\n                                state.interview_id,\n                                phase=\"start_question_generation\",\n                                reason_code=_QUESTION_GENERATION_ENVELOPE_REASON_CODE,\n                                provider_error_type=_provider_error_type(question_result.error),\n                                total_duration_ms=_elapsed_ms(turn_started_at),\n                                ambiguity_scoring_duration_ms=None,\n                                question_generation_duration_ms=question_generation_duration_ms,\n                                advisory_build_duration_ms=None,\n                            )\n                        )\n                        log.warning(\n                            \"mcp.tool.interview.question_generation_parent_handoff\",\n                            session_id=state.interview_id,\n                            phase=\"start_question_generation\",\n                            reason_code=_QUESTION_GENERATION_ENVELOPE_REASON_CODE,\n                        )\n                        return self._parent_question_handoff_response(\n                            state,\n                            state.interview_id,\n                            phase=\"start_question_parent_handoff\",\n                            score=live_score,\n                            error=question_result.error,\n                        )\n\n                    error_msg = str(question_result.error)\n                    event_error_msg = _format_interview_failure_event_error(question_result.error)\n                    from ouroboros.events.interview import interview_failed\n\n                    self._emit_event_bg(\n                        interview_failed(\n                            state.interview_id,\n                            event_error_msg,\n                            phase=\"question_generation\",\n                            total_duration_ms=_elapsed_ms(turn_started_at),\n                            ambiguity_scoring_duration_ms=None,\n                            question_generation_duration_ms=question_generation_duration_ms,\n                            advisory_build_duration_ms=None,\n                        )\n                    )\n                    # ``InterviewEngine.start_interview`` already persisted\n                    # the initial state on disk (Q00/ouroboros#687), so the\n                    # ``session_id`` returned below is guaranteed resumable.\n                    # Return recoverable result with session ID for retry\n                    if \"empty response\" in error_msg.lower():\n                        amb_warning = _ambiguity_warning_for_failed_question(\n                            live_score,\n                            is_brownfield=state.is_brownfield,\n                        )\n                        stderr_info = \"\"\n                        err = question_result.error\n                        if hasattr(err, \"details\") and isinstance(err.details, dict):\n                            stderr = err.details.get(\"stderr\", \"\")\n                            if stderr:\n                                stderr_info = f\"\\n\\nDiagnostics (stderr):\\n{stderr}\"\n                        return Result.ok(\n                            MCPToolResult(\n                                content=(\n                                    MCPContentItem(\n                                        type=ContentType.TEXT,\n                                        text=(\n                                            f\"Question generation failed (empty response from Agent SDK). \"\n                                            f\"Session ID: {state.interview_id}\\n\\n\"\n                                            f'Resume with: session_id=\"{state.interview_id}\"'\n                                            f\"{amb_warning}\"\n                                            f\"{stderr_info}\"\n                                        ),\n                                    ),\n                                ),\n                                is_error=True,\n                                meta={\n                                    \"session_id\": state.interview_id,\n                                    \"recoverable\": True,\n                                    **_interview_reasoning_meta(\n                                        state=state,\n                                        session_id=state.interview_id,\n                                        phase=\"start_question_failed\",\n                                        next_action=\"resume interview and retry question generation\",\n                                        score=live_score,\n                                        recoverable=True,\n                                    ),\n                                },\n                            )\n                        )\n                    # Generic question-generation failure (timeout etc.):\n                    # return a recoverable result so callers can resume\n                    # using the persisted ``session_id`` instead of losing\n                    # the interview handle (Q00/ouroboros#687).  Truncate\n                    # ``error_msg`` to avoid leaking provider internals into\n                    # the user-facing envelope.  The lifecycle event uses the\n                    # provider's compact formatter for the same boundary.\n                    safe_error = error_msg[:200] if error_msg else \"unknown error\"\n                    return Result.ok(\n                        MCPToolResult(\n                            content=(\n                                MCPContentItem(\n                                    type=ContentType.TEXT,\n                                    text=(\n                                        f\"Question generation failed: {safe_error}. \"\n                                        f\"Session ID: {state.interview_id}\\n\\n\"\n                                        f'Resume with: session_id=\"{state.interview_id}\"'\n                                    ),\n                                ),\n                            ),\n                            is_error=True,\n                            meta={\n                                \"session_id\": state.interview_id,\n                                \"recoverable\": True,\n                                **_interview_reasoning_meta(\n                                    state=state,\n                                    session_id=state.interview_id,\n                                    phase=\"start_question_failed\",\n                                    next_action=\"resume interview and retry question generation\",\n                                    score=live_score,\n                                    recoverable=True,\n                                ),\n                            },\n                        )\n                    )\n\n                question = question_result.value\n                display_question = _format_question_with_ambiguity(question, live_score)\n\n                # Record the question as an unanswered round so resume can find it\n                from ouroboros.bigbang.interview import InterviewRound\n\n                state.rounds.append(\n                    InterviewRound(\n                        round_number=1,\n                        question=question,\n                        user_response=None,\n                    )\n                )\n                state.mark_updated()\n\n                # Persist state to disk so subsequent calls can resume\n                save_result = await engine.save_state(state)\n                if save_result.is_err:\n                    log.warning(\n                        \"mcp.tool.interview.save_failed_on_start\",\n                        error=str(save_result.error),\n                    )\n\n                # Emit interview started event\n                from ouroboros.events.interview import interview_started\n\n                self._emit_event_bg(\n                    interview_started(\n                        state.interview_id,\n                        resolved_context.value,\n                    )\n                )\n\n                log.info(\n                    \"mcp.tool.interview.started\",\n                    session_id=state.interview_id,\n                )\n\n                is_length_guard = _is_initial_context_length_guard_question(question)\n                start_meta: dict[str, Any] = {\n                    \"session_id\": state.interview_id,\n                    \"ambiguity_score\": (\n                        live_score.overall_score if live_score is not None else None\n                    ),\n                    \"milestone\": _milestone_for_score(live_score),\n                    \"seed_ready\": (\n                        live_score.is_ready_for_seed if live_score is not None else None\n                    ),\n                    **_interview_reasoning_meta(\n                        state=state,\n                        session_id=state.interview_id,\n                        phase=\"start\",\n                        next_action=\"ask user to answer pending question\",\n                        score=live_score,\n                        question=question,\n                    ),\n                }\n                if is_length_guard:\n                    # Q00/ouroboros#831 (Direction A): surface the length-guard\n                    # meta-directive via structured meta keys so clients can\n                    # branch on ``meta.reason`` instead of mis-routing the text\n                    # body to a human via AskUserQuestion.  ``is_error`` is\n                    # intentionally left ``False`` -- the wire success/failure\n                    # axis must not flip or ``HandlerInterviewBackend.start``\n                    # would raise on every oversized ``initial_context``.\n                    start_meta.update(_length_guard_meta_fields())\n                else:\n                    advisory_build_started_at = time.perf_counter()\n                    try:\n                        _attach_question_assist_requests(\n                            start_meta,\n                            session_id=state.interview_id,\n                            question=question,\n                            phase=\"start\",\n                            score=live_score,\n                            dispatch_mode=resolve_request_subagent_dispatch(\n                                self.agent_runtime_backend, self.opencode_mode\n                            ),\n                            runtime_backend=self.agent_runtime_backend,\n                            opencode_mode=self.opencode_mode,\n                            fanout_registry=self._resolved_fanout_registry(),\n                            findings_store=self.findings_store,\n                        )\n                    finally:\n                        advisory_build_duration_ms = _elapsed_ms(advisory_build_started_at)\n                if is_length_guard:\n                    advisory_build_duration_ms = None\n\n                start_response_text = (\n                    f\"Interview started. Session ID: {state.interview_id}\\n\\n{display_question}\"\n                )\n                start_response_text = append_question_advisory_dispatch(\n                    start_response_text, start_meta\n                )\n                # Q00/ouroboros#831 (diagnostics): capture the shape of every\n                # MCP question-bearing response so future hang reports can be\n                # correlated with response size / transcript pressure.\n                from ouroboros.events.interview import interview_response_emitted\n\n                self._emit_event_bg(\n                    interview_response_emitted(\n                        state.interview_id,\n                        response_kind=\"start\",\n                        round_number=len(state.rounds),\n                        payload_chars=len(start_response_text),\n                        transcript_chars=_compute_transcript_chars(state),\n                        ambiguity_prefix_present=start_response_text.startswith(\"(ambiguity:\"),\n                        is_length_guard=is_length_guard,\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=None,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                        advisory_build_duration_ms=advisory_build_duration_ms,\n                    )\n                )\n                return Result.ok(\n                    MCPToolResult(\n                        content=(\n                            MCPContentItem(\n                                type=ContentType.TEXT,\n                                text=start_response_text,\n                            ),\n                        ),\n                        is_error=False,\n                        meta=start_meta,\n                    )\n                )\n            # No valid parameters provided\n            return Result.err(\n                MCPToolError(\n                    \"Must provide initial_context to start or session_id to resume\",\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n        except Exception as e:\n            log.error(\"mcp.tool.interview.error\", error=str(e))\n            if _interview_id:\n                from ouroboros.events.interview import interview_failed\n\n                self._emit_event_bg(\n                    interview_failed(\n                        _interview_id,\n                        _format_interview_failure_event_error(e),\n                        phase=\"unexpected_error\",\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=None,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                        advisory_build_duration_ms=advisory_build_duration_ms,\n                    )\n                )\n            return Result.err(\n                MCPToolError(\n                    f\"Interview failed: {e}\",\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n        finally:\n            if self._owns_event_store:\n                await self.close()\n\n    async def _handle_answer(\n        self,\n        arguments: dict[str, Any],\n        *,\n        session_id: Any,\n        answer: Any,\n        last_question: Any,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        turn_started_at = time.perf_counter()\n        engine, llm_adapter = self._create_interview_engine()\n        calibration = normalize_interview_calibration(arguments.get(\"interview_calibration\"))\n        _interview_id: str | None = None\n        ambiguity_scoring_duration_ms: float | None = None\n        question_generation_duration_ms: float | None = None\n\n        try:\n            load_result = await engine.load_state(session_id)\n            if load_result.is_err:\n                return Result.err(\n                    MCPToolError(\n                        str(load_result.error),\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n\n            state = load_result.value\n            if state.merge_turn_context(_normalized_turn_context(arguments)):\n                merge_save_result = await engine.save_state(state)\n                if merge_save_result.is_err:\n                    return Result.err(\n                        MCPToolError(\n                            str(merge_save_result.error),\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n            _interview_id = session_id\n\n            lateral_review_meta: dict[str, Any] | None = None\n            intent_guard_report: IntentGuardReport | None = None\n\n            # If answer provided, record it first\n            if _is_interview_completion_signal(answer):\n                is_safe_default_synthesis = _is_safe_default_synthesis_completion(answer)\n                # Remember whether a round is awaiting an answer so we\n                # can pop it only on the branches that actually end\n                # the interview. Shortfall/refusal paths keep the\n                # pending question around so the user's next plain\n                # answer lands on a live round instead of either\n                # crashing (\"no questions have been asked yet\") or\n                # attaching to a stale, already-answered round.\n                has_pending_round = bool(state.rounds and state.rounds[-1].user_response is None)\n                # Gate: check ambiguity before completing.\n                # Stored score first; live scoring as fallback.\n                exit_score = _load_state_ambiguity_score(state)\n                if (\n                    exit_score is None\n                    or _stored_ambiguity_snapshot_is_degraded(state)\n                    or not qualifies_for_seed_completion(\n                        exit_score,\n                        is_brownfield=state.is_brownfield,\n                    )\n                ):\n                    # Own the streak advance in this branch; the\n                    # scorer must not double-bump it. See #405.\n                    # ``reset_on_failure=True`` keeps the shared\n                    # stale-streak invalidation contract even\n                    # though this branch disables the qualifying-\n                    # score increment.\n                    ambiguity_scoring_started_at = time.perf_counter()\n                    try:\n                        exit_score = await self._score_interview_state(\n                            llm_adapter,\n                            state,\n                            advance_streak=False,\n                            reset_on_failure=True,\n                        )\n                    finally:\n                        ambiguity_scoring_duration_ms = _elapsed_ms(ambiguity_scoring_started_at)\n                # Safe-default synthesis is emitted only after the auto driver has filled every\n                # remaining required ledger gap with audited conservative defaults. Do not require\n                # the semantic ambiguity scorer to also cross the normal human \"done\" threshold;\n                # that score can lag behind the ledger and would leave a trailing unanswered\n                # question in the persisted transcript.\n                if is_safe_default_synthesis:\n                    if has_pending_round:\n                        state.rounds.pop()\n                    synthesis_round = state.record_answer(\n                        last_question or \"[driver safe-default finalization]\",\n                        answer,\n                    )\n                    declare_provenance(synthesis_round, arguments)\n                    state.clear_stored_ambiguity()\n                    state.mark_updated()\n                    return await self._complete_interview_response(\n                        engine,\n                        state,\n                        session_id,\n                        None,\n                        seed_ready_override=True,\n                        turn_started_at=turn_started_at,\n                        ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                    )\n                if exit_score is not None and qualifies_for_seed_completion(\n                    exit_score,\n                    is_brownfield=state.is_brownfield,\n                ):\n                    if is_safe_default_synthesis:\n                        if has_pending_round:\n                            state.rounds.pop()\n                        return await self._complete_interview_response(\n                            engine,\n                            state,\n                            session_id,\n                            exit_score,\n                            turn_started_at=turn_started_at,\n                            ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                        )\n\n                    # Explicit 'done' with a qualifying score counts\n                    # as an implicit stability signal — advance the\n                    # streak so repeated 'done' inputs can progress\n                    # instead of looping on the same message forever.\n                    # See: https://github.com/Q00/ouroboros/issues/405\n                    if state.completion_candidate_streak < AUTO_COMPLETE_STREAK_REQUIRED:\n                        state.completion_candidate_streak += 1\n                        state.mark_updated()\n                    if state.completion_candidate_streak >= AUTO_COMPLETE_STREAK_REQUIRED:\n                        # We are about to finalize the interview —\n                        # drop the pending 'done' round so it does\n                        # not leak into the saved transcript.\n                        if has_pending_round:\n                            state.rounds.pop()\n                        return await self._complete_interview_response(\n                            engine,\n                            state,\n                            session_id,\n                            exit_score,\n                            turn_started_at=turn_started_at,\n                            ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                        )\n                    # Streak advanced but still short of the\n                    # threshold — persist the advance and invite the\n                    # user to confirm again or answer the pending\n                    # question. The pending round is intentionally\n                    # preserved so \"answer another question to\n                    # update the score\" remains truthful.\n                    #\n                    # Persistence is load-bearing on this branch:\n                    # the next 'done' must see the advanced streak\n                    # or the user is stuck looping from 0 forever.\n                    # Treat a save failure as a hard error rather\n                    # than returning the \"almost there\" success\n                    # message with an un-persisted streak.\n                    # See #405 follow-up design note on 3c2531d.\n                    shortfall_save_result = await engine.save_state(state)\n                    if shortfall_save_result.is_err:\n                        log.error(\n                            \"mcp.tool.interview.save_failed_on_shortfall\",\n                            session_id=session_id,\n                            error=str(shortfall_save_result.error),\n                        )\n                        return Result.err(\n                            MCPToolError(\n                                \"Failed to persist completion streak \"\n                                f\"advance: {shortfall_save_result.error}\",\n                                tool_name=\"ouroboros_interview\",\n                            )\n                        )\n                    streak_shortfall = (\n                        AUTO_COMPLETE_STREAK_REQUIRED - state.completion_candidate_streak\n                    )\n                    answer_hint = (\n                        \"or answer the pending question to update the score.\"\n                        if has_pending_round\n                        else \"or resume without an answer to receive another question.\"\n                    )\n                    return Result.ok(\n                        MCPToolResult(\n                            content=(\n                                MCPContentItem(\n                                    type=ContentType.TEXT,\n                                    text=(\n                                        f\"Ambiguity looks low \"\n                                        f\"(score={exit_score.overall_score:.2f}). \"\n                                        f\"Stability check: \"\n                                        f\"{state.completion_candidate_streak}\"\n                                        f\"/{AUTO_COMPLETE_STREAK_REQUIRED}. \"\n                                        f\"Type 'done' once more to confirm \"\n                                        f\"({streak_shortfall} more signal(s) needed), \"\n                                        f\"{answer_hint}\"\n                                    ),\n                                ),\n                            ),\n                            is_error=False,\n                            meta={\n                                \"session_id\": session_id,\n                                \"ambiguity_score\": exit_score.overall_score,\n                                \"seed_ready\": False,\n                                \"completion_candidate_streak\": (state.completion_candidate_streak),\n                                \"streak_required\": AUTO_COMPLETE_STREAK_REQUIRED,\n                                **_interview_reasoning_meta(\n                                    state=state,\n                                    session_id=session_id,\n                                    phase=\"completion_stability_check\",\n                                    next_action=\"confirm done again or answer pending question\",\n                                    score=exit_score,\n                                ),\n                            },\n                        )\n                    )\n                # Ambiguity too high — refuse completion. Keep any\n                # pending round in place so the user can still\n                # answer it directly.\n                #\n                # Persistence is load-bearing on this branch too:\n                # ``_score_interview_state(reset_on_failure=True)``\n                # may have just cleared a stale ``completion_candidate_streak``\n                # in memory. If the save silently fails, the next\n                # request reloads the pre-reset streak from disk\n                # and a single qualifying signal can finalize the\n                # interview, violating the two-signal contract #405\n                # was opened to enforce. Treat a save failure as a\n                # hard error, mirroring the shortfall branch.\n                refuse_save_result = await engine.save_state(state)\n                if refuse_save_result.is_err:\n                    log.error(\n                        \"mcp.tool.interview.save_failed_on_ambiguity_gate\",\n                        session_id=session_id,\n                        error=str(refuse_save_result.error),\n                    )\n                    return Result.err(\n                        MCPToolError(\n                            f\"Failed to persist stale-streak reset: {refuse_save_result.error}\",\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n                return self._ambiguity_gate_response(\n                    session_id,\n                    exit_score,\n                    state=state,\n                    is_brownfield=state.is_brownfield,\n                )\n\n            if not state.rounds and last_question:\n                pending_question = last_question\n            elif not state.rounds:\n                return Result.err(\n                    MCPToolError(\n                        \"Cannot record answer - no questions have been asked yet\",\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n\n            # Resolve the question text for this round.\n            #\n            # Case A — last round is unanswered (the normal flow): the\n            # caller is answering the pending MCP-generated question.\n            # Pop the unanswered round; record_response re-creates it\n            # with the same question and the user's answer. A\n            # caller-provided ``last_question`` overrides the stored\n            # text to repair stale placeholders.\n            #\n            # Case B — last round is already answered (post-seed-ready\n            # challenge per the Seed-ready Acceptance Guard, or any\n            # reopen with no pending question): MCP did not generate\n            # the probe — the main session did. Reusing\n            # state.rounds[-1].question would bind the caller's new\n            # answer to the previously-answered question, corrupting\n            # the transcript. Require the caller to supply the\n            # question via ``last_question``.\n            # If this is the first live ambiguity score, the interview\n            # is crossing from the implicit starting milestone.  Treat\n            # the absent stored score as ``initial`` so the normal first\n            # ``initial -> progress/refined/ready`` transition can\n            # surface the advisory instead of being skipped forever.\n            previous_milestone = (\n                get_milestone(state.ambiguity_score)[0].value\n                if state.ambiguity_score is not None\n                else \"initial\"\n            )\n\n            if not state.rounds:\n                pass\n            elif state.rounds[-1].user_response is None:\n                # An echo repairs a question damaged by partial persistence\n                # (79ef2cf5); one carrying our directive is not a repair, and\n                # the stored question of an unanswered round is what we asked.\n                issued = state.rounds[-1].question\n                pending_question = (\n                    issued if echo_carries_dispatch(last_question) else (last_question or issued)\n                )\n            else:\n                if not last_question:\n                    return Result.err(\n                        MCPToolError(\n                            \"Cannot record answer - the previous round is \"\n                            \"already answered and no follow-up question was \"\n                            \"provided. When reopening a completed interview \"\n                            \"(Seed-ready challenge), pass the new probe \"\n                            \"question as 'last_question' alongside 'answer'.\",\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n                pending_question = last_question\n\n            intent_guard_report = _guard_interview_answer(\n                state=state,\n                question=pending_question,\n                answer=answer,\n            )\n            if intent_guard_report.status is IntentGuardStatus.FAIL:\n                return Result.err(\n                    MCPToolError(\n                        _format_intent_guard_blocker(intent_guard_report),\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n            if state.rounds and state.rounds[-1].user_response is None:\n                state.rounds.pop()\n\n            record_result = await engine.record_response(state, answer, pending_question)\n            if record_result.is_err:\n                return Result.err(\n                    MCPToolError(\n                        str(record_result.error),\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n            state = record_result.value\n            declare_provenance(state.rounds[-1] if state.rounds else None, arguments)\n            state.clear_stored_ambiguity()\n\n            # Emit response recorded event\n            from ouroboros.events.interview import interview_response_recorded\n\n            self._emit_event_bg(\n                interview_response_recorded(\n                    interview_id=session_id,\n                    round_number=len(state.rounds),\n                    question_preview=pending_question,\n                    response_preview=answer,\n                )\n            )\n\n            log.info(\n                \"mcp.tool.interview.response_recorded\",\n                session_id=session_id,\n            )\n\n            # Persist recorded answer immediately so it survives\n            # question generation failures downstream\n            await engine.save_state(state)\n\n            # Once completion is possible, plan the new ambiguity snapshot and\n            # next question atomically. This keeps the score→question dependency\n            # without imposing two serial provider calls or requiring adapter\n            # concurrency. Earlier rounds keep the ordinary question-only path.\n            answered = _count_answered_rounds(state)\n            supports_atomic_turn = isinstance(InterviewEngine, type) and isinstance(\n                engine, InterviewEngine\n            )\n            if answered >= MIN_ROUNDS_BEFORE_EARLY_EXIT and supports_atomic_turn:\n                backend = _handler_llm_backend(self.llm_backend, \"clarification\")\n                scorer = AmbiguityScorer(\n                    llm_adapter=llm_adapter,\n                    model=get_llm_model_for_role(\"clarification\", backend=backend),\n                    max_retries=_LIVE_AMBIGUITY_MAX_RETRIES,\n                )\n                planner = InterviewTurnPlanner(engine=engine, scorer=scorer)\n                question_generation_started_at = time.perf_counter()\n                question_result: Any = None\n                try:\n                    turn_result = await planner.plan(\n                        state,\n                        language_calibration=calibration,\n                    )\n                finally:\n                    question_generation_duration_ms = _elapsed_ms(question_generation_started_at)\n                if turn_result.is_err:\n                    live_score = None\n                    question_result = Result.err(turn_result.error)\n                else:\n                    turn = turn_result.value\n                    live_score = turn.ambiguity\n                    if live_score is None:\n                        state.clear_stored_ambiguity()\n                        _reset_stale_completion_streak(state)\n                    else:\n                        self._apply_interview_score(state, live_score)\n                    lateral_review_meta = _maybe_record_lateral_review_advisory(\n                        state,\n                        previous_milestone=previous_milestone,\n                        score=live_score,\n                    )\n                    if (\n                        live_score is not None\n                        and qualifies_for_seed_completion(\n                            live_score,\n                            is_brownfield=state.is_brownfield,\n                        )\n                        and state.completion_candidate_streak >= AUTO_COMPLETE_STREAK_REQUIRED\n                    ):\n                        return await self._complete_interview_response(\n                            engine,\n                            state,\n                            session_id,\n                            live_score,\n                            turn_started_at=turn_started_at,\n                            question_generation_duration_ms=question_generation_duration_ms,\n                        )\n                    question_result = Result.ok(turn.question)\n            elif answered >= MIN_ROUNDS_BEFORE_EARLY_EXIT:\n                ambiguity_scoring_started_at = time.perf_counter()\n                try:\n                    live_score = await self._score_interview_state(llm_adapter, state)\n                finally:\n                    ambiguity_scoring_duration_ms = _elapsed_ms(ambiguity_scoring_started_at)\n                lateral_review_meta = _maybe_record_lateral_review_advisory(\n                    state,\n                    previous_milestone=previous_milestone,\n                    score=live_score,\n                )\n                if (\n                    live_score is not None\n                    and qualifies_for_seed_completion(\n                        live_score,\n                        is_brownfield=state.is_brownfield,\n                    )\n                    and state.completion_candidate_streak >= AUTO_COMPLETE_STREAK_REQUIRED\n                ):\n                    return await self._complete_interview_response(\n                        engine,\n                        state,\n                        session_id,\n                        live_score,\n                        turn_started_at=turn_started_at,\n                        ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                    )\n                question_generation_started_at = time.perf_counter()\n                try:\n                    question_result = await _ask_next_question(engine, state, calibration)\n                finally:\n                    question_generation_duration_ms = _elapsed_ms(question_generation_started_at)\n            else:\n                live_score = None\n                question_generation_started_at = time.perf_counter()\n                try:\n                    question_result = await _ask_next_question(engine, state, calibration)\n                finally:\n                    question_generation_duration_ms = _elapsed_ms(question_generation_started_at)\n            return await self._respond_with_next_question(\n                engine,\n                state,\n                session_id,\n                question_result=question_result,\n                live_score=live_score,\n                lateral_review_meta=lateral_review_meta,\n                intent_guard_report=intent_guard_report,\n                turn_started_at=turn_started_at,\n                ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                question_generation_duration_ms=question_generation_duration_ms,\n            )\n        except Exception as e:\n            log.error(\"mcp.tool.interview.error\", error=str(e))\n            if _interview_id:\n                from ouroboros.events.interview import interview_failed\n\n                self._emit_event_bg(\n                    interview_failed(\n                        _interview_id,\n                        _format_interview_failure_event_error(e),\n                        phase=\"unexpected_error\",\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                        advisory_build_duration_ms=None,\n                    )\n                )\n            return Result.err(\n                MCPToolError(\n                    f\"Interview failed: {e}\",\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n        finally:\n            if self._owns_event_store:\n                await self.close()\n\n    async def _handle_resume(\n        self,\n        arguments: dict[str, Any],\n        *,\n        session_id: Any,\n        answer: Any,\n        last_question: Any,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        turn_started_at = time.perf_counter()\n        engine, _ = self._create_interview_engine()\n        calibration = normalize_interview_calibration(arguments.get(\"interview_calibration\"))\n        _interview_id: str | None = None\n        question_generation_duration_ms: float | None = None\n        advisory_build_duration_ms: float | None = None\n\n        try:\n            load_result = await engine.load_state(session_id)\n            if load_result.is_err:\n                return Result.err(\n                    MCPToolError(\n                        str(load_result.error),\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n\n            state = load_result.value\n            if state.merge_turn_context(_normalized_turn_context(arguments)):\n                merge_save_result = await engine.save_state(state)\n                if merge_save_result.is_err:\n                    return Result.err(\n                        MCPToolError(\n                            str(merge_save_result.error),\n                            tool_name=\"ouroboros_interview\",\n                        )\n                    )\n            _interview_id = session_id\n\n            if not answer and state.rounds and state.rounds[-1].user_response is None:\n                pending_question = state.rounds[-1].question\n                display_question = _format_question_with_ambiguity(\n                    pending_question,\n                    _load_state_ambiguity_score(state),\n                )\n                resume_is_length_guard = _is_initial_context_length_guard_question(pending_question)\n                resume_meta: dict[str, Any] = {\n                    \"session_id\": session_id,\n                    \"ambiguity_score\": state.ambiguity_score,\n                    \"milestone\": (\n                        get_milestone(state.ambiguity_score)[0].value\n                        if state.ambiguity_score is not None\n                        else None\n                    ),\n                    \"seed_ready\": (\n                        state.ambiguity_score is not None\n                        and state.ambiguity_score <= AMBIGUITY_THRESHOLD\n                    ),\n                    **_interview_reasoning_meta(\n                        state=state,\n                        session_id=session_id,\n                        phase=\"resume_pending\",\n                        next_action=\"ask user to answer pending question\",\n                        score=_load_state_ambiguity_score(state),\n                        question=pending_question,\n                    ),\n                }\n                if resume_is_length_guard:\n                    # Q00/ouroboros#831 (Direction A): structured signal\n                    # when resuming an interview whose pending round is\n                    # the length-guard meta-directive.  ``is_error`` stays\n                    # ``False`` so the auto driver does not treat the\n                    # summarize prompt as a hard failure.\n                    resume_meta.update(_length_guard_meta_fields())\n                else:\n                    advisory_build_started_at = time.perf_counter()\n                    try:\n                        _attach_question_assist_requests(\n                            resume_meta,\n                            session_id=session_id,\n                            question=pending_question,\n                            phase=\"resume_pending\",\n                            score=_load_state_ambiguity_score(state),\n                            dispatch_mode=resolve_request_subagent_dispatch(\n                                self.agent_runtime_backend, self.opencode_mode\n                            ),\n                            runtime_backend=self.agent_runtime_backend,\n                            opencode_mode=self.opencode_mode,\n                            fanout_registry=self._resolved_fanout_registry(),\n                            findings_store=self.findings_store,\n                        )\n                    finally:\n                        advisory_build_duration_ms = _elapsed_ms(advisory_build_started_at)\n                if resume_is_length_guard:\n                    advisory_build_duration_ms = None\n\n                resume_response_text = f\"Session {session_id}\\n\\n{display_question}\"\n                resume_response_text = append_question_advisory_dispatch(\n                    resume_response_text, resume_meta\n                )\n                # Q00/ouroboros#831 (diagnostics): response-shape event for\n                # the resume-pending branch.  Pure observability.\n                from ouroboros.events.interview import interview_response_emitted\n\n                self._emit_event_bg(\n                    interview_response_emitted(\n                        session_id,\n                        response_kind=\"resume_pending\",\n                        round_number=len(state.rounds),\n                        payload_chars=len(resume_response_text),\n                        transcript_chars=_compute_transcript_chars(state),\n                        ambiguity_prefix_present=resume_response_text.startswith(\"(ambiguity:\"),\n                        is_length_guard=resume_is_length_guard,\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=None,\n                        question_generation_duration_ms=None,\n                        advisory_build_duration_ms=advisory_build_duration_ms,\n                    )\n                )\n                return Result.ok(\n                    MCPToolResult(\n                        content=(\n                            MCPContentItem(\n                                type=ContentType.TEXT,\n                                text=resume_response_text,\n                            ),\n                        ),\n                        is_error=False,\n                        meta=resume_meta,\n                    )\n                )\n\n            lateral_review_meta: dict[str, Any] | None = None\n            intent_guard_report: IntentGuardReport | None = None\n\n            live_score = _load_state_ambiguity_score(state)\n            question_generation_started_at = time.perf_counter()\n            try:\n                question_result = await _ask_next_question(engine, state, calibration)\n            finally:\n                question_generation_duration_ms = _elapsed_ms(question_generation_started_at)\n            return await self._respond_with_next_question(\n                engine,\n                state,\n                session_id,\n                question_result=question_result,\n                live_score=live_score,\n                lateral_review_meta=lateral_review_meta,\n                intent_guard_report=intent_guard_report,\n                turn_started_at=turn_started_at,\n                ambiguity_scoring_duration_ms=None,\n                question_generation_duration_ms=question_generation_duration_ms,\n            )\n        except Exception as e:\n            log.error(\"mcp.tool.interview.error\", error=str(e))\n            if _interview_id:\n                from ouroboros.events.interview import interview_failed\n\n                self._emit_event_bg(\n                    interview_failed(\n                        _interview_id,\n                        _format_interview_failure_event_error(e),\n                        phase=\"unexpected_error\",\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=None,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                        advisory_build_duration_ms=advisory_build_duration_ms,\n                    )\n                )\n            return Result.err(\n                MCPToolError(\n                    f\"Interview failed: {e}\",\n                    tool_name=\"ouroboros_interview\",\n                )\n            )\n        finally:\n            if self._owns_event_store:\n                await self.close()\n\n    async def _respond_with_next_question(\n        self,\n        engine: Any,\n        state: InterviewState,\n        session_id: Any,\n        *,\n        question_result: Any,\n        live_score: AmbiguityScore | None,\n        lateral_review_meta: dict[str, Any] | None,\n        intent_guard_report: IntentGuardReport | None,\n        turn_started_at: float,\n        ambiguity_scoring_duration_ms: float | None,\n        question_generation_duration_ms: float,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Shared question-generation and response tail for answer/resume paths.\"\"\"\n        if question_result.is_err:\n            if _is_question_generation_envelope_violation(question_result.error):\n                from ouroboros.events.interview import interview_question_parent_handoff\n\n                self._emit_event_bg(\n                    interview_question_parent_handoff(\n                        session_id,\n                        phase=\"next_question_generation\",\n                        reason_code=_QUESTION_GENERATION_ENVELOPE_REASON_CODE,\n                        provider_error_type=_provider_error_type(question_result.error),\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                    )\n                )\n                log.warning(\n                    \"mcp.tool.interview.question_generation_parent_handoff\",\n                    session_id=session_id,\n                    phase=\"next_question_generation\",\n                    reason_code=_QUESTION_GENERATION_ENVELOPE_REASON_CODE,\n                )\n                return self._parent_question_handoff_response(\n                    state,\n                    session_id,\n                    phase=\"next_question_parent_handoff\",\n                    score=live_score,\n                    error=question_result.error,\n                )\n\n            error_msg = str(question_result.error)\n            event_error_msg = _format_interview_failure_event_error(question_result.error)\n            from ouroboros.events.interview import interview_failed\n\n            self._emit_event_bg(\n                interview_failed(\n                    session_id,\n                    event_error_msg,\n                    phase=\"question_generation\",\n                    total_duration_ms=_elapsed_ms(turn_started_at),\n                    ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                    question_generation_duration_ms=question_generation_duration_ms,\n                    advisory_build_duration_ms=None,\n                )\n            )\n            if \"empty response\" in error_msg.lower():\n                amb_warning = _ambiguity_warning_for_failed_question(\n                    live_score,\n                    is_brownfield=state.is_brownfield,\n                )\n                # Extract stderr from ProviderError details for diagnostics\n                stderr_info = \"\"\n                err = question_result.error\n                if hasattr(err, \"details\") and isinstance(err.details, dict):\n                    stderr = err.details.get(\"stderr\", \"\")\n                    if stderr:\n                        stderr_info = f\"\\n\\nDiagnostics (stderr):\\n{stderr}\"\n                return Result.ok(\n                    MCPToolResult(\n                        content=(\n                            MCPContentItem(\n                                type=ContentType.TEXT,\n                                text=(\n                                    f\"Question generation failed (empty response from Agent SDK). \"\n                                    f\"Session ID: {session_id}\\n\\n\"\n                                    f'Resume with: session_id=\"{session_id}\"'\n                                    f\"{amb_warning}\"\n                                    f\"{stderr_info}\"\n                                ),\n                            ),\n                        ),\n                        is_error=True,\n                        meta={\n                            \"session_id\": session_id,\n                            \"recoverable\": True,\n                            **_interview_reasoning_meta(\n                                state=state,\n                                session_id=session_id,\n                                phase=\"next_question_failed\",\n                                next_action=\"resume interview and retry question generation\",\n                                score=live_score,\n                                recoverable=True,\n                            ),\n                        },\n                    )\n                )\n            return Result.err(MCPToolError(error_msg, tool_name=\"ouroboros_interview\"))\n\n        question = question_result.value\n        lateral_review_dispatch_meta = _with_lateral_review_dispatch(\n            state,\n            next_question=question,\n            score=live_score,\n            lateral_review_meta=lateral_review_meta,\n        )\n        if lateral_review_meta is not None and live_score is not None:\n            state.note_lateral_review_advisory(lateral_review_meta[\"lateral_review_milestone\"])\n            from ouroboros.events.interview import (\n                interview_lateral_review_recommended,\n            )\n\n            self._emit_event_bg(\n                interview_lateral_review_recommended(\n                    session_id,\n                    from_milestone=lateral_review_meta[\"lateral_review_from_milestone\"],\n                    to_milestone=lateral_review_meta[\"lateral_review_milestone\"],\n                    ambiguity_score=live_score.overall_score,\n                    round_number=len(state.rounds),\n                )\n            )\n        display_question = _format_question_with_ambiguity(question, live_score)\n\n        # Save pending question as unanswered round for next resume\n        from ouroboros.bigbang.interview import InterviewRound\n\n        state.rounds.append(\n            InterviewRound(\n                round_number=state.current_round_number,\n                question=question,\n                user_response=None,\n            )\n        )\n        state.mark_updated()\n\n        save_result = await engine.save_state(state)\n        if save_result.is_err:\n            log.warning(\n                \"mcp.tool.interview.save_failed\",\n                error=str(save_result.error),\n            )\n\n        log.info(\n            \"mcp.tool.interview.question_asked\",\n            session_id=session_id,\n        )\n\n        answer_is_length_guard = _is_initial_context_length_guard_question(question)\n        answer_meta: dict[str, Any] = {\n            \"session_id\": session_id,\n            \"ambiguity_score\": (live_score.overall_score if live_score is not None else None),\n            \"milestone\": _milestone_for_score(live_score),\n            \"seed_ready\": (live_score.is_ready_for_seed if live_score is not None else None),\n            **_interview_reasoning_meta(\n                state=state,\n                session_id=session_id,\n                phase=\"answer\",\n                next_action=\"ask user to answer pending question\",\n                score=live_score,\n                question=question,\n            ),\n        }\n        if intent_guard_report is not None:\n            answer_meta[\"intent_guard\"] = intent_guard_report.to_dict()\n        if answer_is_length_guard:\n            # Q00/ouroboros#831 (Direction A): structured signal when\n            # the next question after an answer is again the length-\n            # guard meta-directive.  ``is_error`` stays ``False`` so\n            # the auto driver's ``answer()`` path is not raised on.\n            answer_meta.update(_length_guard_meta_fields())\n        else:\n            advisory_build_started_at = time.perf_counter()\n            advisory_build_error: Exception | None = None\n            try:\n                _attach_question_assist_requests(\n                    answer_meta,\n                    session_id=session_id,\n                    question=question,\n                    phase=\"answer\",\n                    score=live_score,\n                    dispatch_mode=resolve_request_subagent_dispatch(\n                        self.agent_runtime_backend, self.opencode_mode\n                    ),\n                    runtime_backend=self.agent_runtime_backend,\n                    opencode_mode=self.opencode_mode,\n                    fanout_registry=self._resolved_fanout_registry(),\n                    findings_store=self.findings_store,\n                )\n            except Exception as error:\n                advisory_build_error = error\n            finally:\n                advisory_build_duration_ms = _elapsed_ms(advisory_build_started_at)\n            if advisory_build_error is not None:\n                log.error(\"mcp.tool.interview.error\", error=str(advisory_build_error))\n                from ouroboros.events.interview import interview_failed\n\n                self._emit_event_bg(\n                    interview_failed(\n                        session_id,\n                        _format_interview_failure_event_error(advisory_build_error),\n                        phase=\"unexpected_error\",\n                        total_duration_ms=_elapsed_ms(turn_started_at),\n                        ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                        question_generation_duration_ms=question_generation_duration_ms,\n                        advisory_build_duration_ms=advisory_build_duration_ms,\n                    )\n                )\n                return Result.err(\n                    MCPToolError(\n                        f\"Interview failed: {advisory_build_error}\",\n                        tool_name=\"ouroboros_interview\",\n                    )\n                )\n        if answer_is_length_guard:\n            advisory_build_duration_ms = None\n\n        if lateral_review_dispatch_meta is not None:\n            answer_meta.update(lateral_review_dispatch_meta)\n\n        answer_response_text = f\"Session {session_id}\\n\\n{display_question}\"\n        answer_response_text = append_question_advisory_dispatch(answer_response_text, answer_meta)\n        # Q00/ouroboros#831 (diagnostics): response-shape event for\n        # the answer branch.  Pure observability.\n        from ouroboros.events.interview import interview_response_emitted\n\n        self._emit_event_bg(\n            interview_response_emitted(\n                session_id,\n                response_kind=\"answer\",\n                round_number=len(state.rounds),\n                payload_chars=len(answer_response_text),\n                transcript_chars=_compute_transcript_chars(state),\n                ambiguity_prefix_present=answer_response_text.startswith(\"(ambiguity:\"),\n                is_length_guard=answer_is_length_guard,\n                total_duration_ms=_elapsed_ms(turn_started_at),\n                ambiguity_scoring_duration_ms=ambiguity_scoring_duration_ms,\n                question_generation_duration_ms=question_generation_duration_ms,\n                advisory_build_duration_ms=advisory_build_duration_ms,\n            )\n        )\n        return Result.ok(\n            MCPToolResult(\n                content=(\n                    MCPContentItem(\n                        type=ContentType.TEXT,\n                        text=answer_response_text,\n                    ),\n                ),\n                is_error=False,\n                meta=answer_meta,\n            )\n        )\n"
