    {
      "path": "src/ouroboros/mcp/tools/evaluation_handlers.py",
      "content": "\"\"\"Evaluation-phase tool handlers for Ouroboros MCP server.\n\nContains handlers for drift measurement, evaluation, and lateral thinking tools:\n- MeasureDriftHandler: Measures goal deviation from seed specification.\n- EvaluateHandler: Three-stage evaluation pipeline (mechanical, semantic, consensus).\n- LateralThinkHandler: Generates alternative thinking approaches via personas.\n\"\"\"\n\nimport asyncio\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\nfrom typing import TYPE_CHECKING, Any\n\nfrom pydantic import ValidationError as PydanticValidationError\nimport structlog\nimport yaml\n\nfrom ouroboros.config import (\n    get_auto_evolve_enabled,\n    get_llm_backend_for_role,\n    get_llm_model_for_role,\n)\nfrom ouroboros.core.errors import ConfigError, ProviderError, ValidationError\nfrom ouroboros.core.project_paths import resolve_path_against_base, resolve_seed_project_path\nfrom ouroboros.core.seed import AcceptanceCriterionSpec, Seed, ac_text\nfrom ouroboros.core.types import Result\nfrom ouroboros.evaluation.models import (\n    AcceptanceState,\n    CheckResult,\n    MechanicalDisposition,\n    MechanicalResult,\n    aggregate_acceptance_state,\n    derive_acceptance_state,\n)\nfrom ouroboros.mcp.errors import MCPAuthError, MCPServerError, MCPTimeoutError, MCPToolError\nfrom ouroboros.mcp.job_manager import JobLinks, JobManager\nfrom ouroboros.mcp.telemetry_boundary import (\n    record_direct_evaluation_outcome,\n)\nfrom ouroboros.mcp.tools import background as background_jobs\nfrom ouroboros.mcp.tools.evaluation_package_evidence import (\n    evidence_for_criteria,\n    recorded_checks_by_position,\n)\nfrom ouroboros.mcp.tools.evaluation_stage1_report import (\n    format_stage1_result,\n    serialize_stage1_result,\n)\nfrom ouroboros.mcp.tools.fanout_handler import (  # noqa: F401\n    FetchArtifactHandler,\n    SubmitFanoutResultsHandler,\n)\nfrom ouroboros.mcp.tools.job_observer import (\n    append_job_observer_inline_handoff,\n    build_job_observer_contract,\n)\n\n# Re-export: LateralThinkHandler moved to its own module (#1797 ratchet);\n# definitions.py and tests import it from here.\nfrom ouroboros.mcp.tools.lateral_think_handler import (  # noqa: E402,F401\n    LateralThinkHandler,\n)\nfrom ouroboros.mcp.tools.subagent import (\n    DELEGATED_TO_SUBAGENT,\n    build_evaluate_subagent,\n    dispatch_plugin_terminal,\n    should_dispatch_via_plugin,\n)\nfrom ouroboros.mcp.types import (\n    ContentType,\n    MCPContentItem,\n    MCPToolDefinition,\n    MCPToolParameter,\n    MCPToolResult,\n    ToolInputType,\n)\nfrom ouroboros.observability.drift import (\n    DRIFT_THRESHOLD,\n    DriftMeasurement,\n)\nfrom ouroboros.orchestrator.policy import (\n    PolicyContext,\n    PolicyExecutionPhase,\n    PolicySessionRole,\n    allowed_runtime_builtin_tool_names,\n)\nfrom ouroboros.orchestrator.session import SessionRepository\nfrom ouroboros.persistence.event_store import EventStore\nfrom ouroboros.providers import create_llm_adapter\n\nlog = structlog.get_logger(__name__)\n\n# Unverified is not a rejection: no executed check ran, so model review could\n# only be attached as feedback. Rendering it as REJECTED would misstate that.\n_ACCEPTANCE_LABELS: dict[AcceptanceState, str] = {\n    AcceptanceState.APPROVED: \"APPROVED\",\n    AcceptanceState.REJECTED: \"REJECTED\",\n    AcceptanceState.UNVERIFIED: \"NOT APPROVED (unverified: no executed verification evidence)\",\n}\n\n\ndef _direct_evaluation_failure_reason(error: object) -> str | None:\n    \"\"\"Map only trusted exception types to the telemetry reason vocabulary.\"\"\"\n    if isinstance(error, (ConfigError,)):\n        return \"config\"\n    if isinstance(error, (ValidationError, PydanticValidationError)):\n        return \"validation\"\n    if isinstance(error, (MCPAuthError,)):\n        return \"auth\"\n    if isinstance(error, (MCPTimeoutError, TimeoutError)):\n        return \"timeout\"\n    if isinstance(error, ProviderError):\n        return \"model\"\n    return None\n\n\ndef _failure_reason_details(error: object) -> dict[str, str]:\n    \"\"\"Carry the branch reason code for the background evaluate job runner.\n\n    The direct ``ouroboros_evaluate`` path already records this code on\n    ``workflow_outcome``; the job path only sees the ``Result.err``, so the\n    same closed code rides in ``MCPToolError.failure_meta`` (never rendered,\n    never sent) for ``mcp.tools.background.job_work_error`` to lift into\n    ``result_meta``.\n    \"\"\"\n    reason = _direct_evaluation_failure_reason(error)\n    return {\"failure_reason_code\": reason} if reason else {}\n\n\nif TYPE_CHECKING:\n    from ouroboros.mcp.tools.ralph_handlers import StartRalphHandler\n    from ouroboros.mcp.tools.seed_handoff import SeedHandoffRegistry\n\n\ndef _seed_acceptance_criteria(seed: Seed) -> tuple[str, ...]:\n    return tuple(\n        stripped\n        for criterion in seed.acceptance_criteria\n        if (stripped := ac_text(criterion).strip())\n    )\n\n\ndef _seed_ac_spec_map(seed: Seed | None) -> dict[str, AcceptanceCriterionSpec]:\n    \"\"\"Map each AC description to its structured spec (PR-H).\n\n    Since PR-F, ``Seed.acceptance_criteria`` holds ``AcceptanceCriterionSpec``\n    objects.  Evaluation flows AC text (descriptions) around as bare strings,\n    so we key specs by their trimmed ``description`` to reattach the declared\n    success contract when building each ``EvaluationContext``.  Only specs\n    that actually carry a contract are included — bare-description ACs map to\n    nothing and the evaluator judges the AC text alone (today's behavior).\n    \"\"\"\n    if seed is None:\n        return {}\n    spec_map: dict[str, AcceptanceCriterionSpec] = {}\n    for criterion in seed.acceptance_criteria:\n        if not isinstance(criterion, AcceptanceCriterionSpec):\n            continue\n        if not criterion.has_success_contract:\n            continue\n        key = criterion.description.strip()\n        if key:\n            spec_map.setdefault(key, criterion)\n    return spec_map\n\n\nasync def _default_brownfield_project_dir() -> Path | None:\n    \"\"\"Return the registered default brownfield project directory, if any.\"\"\"\n    from ouroboros.persistence.brownfield import BrownfieldStore\n\n    store = BrownfieldStore()\n    try:\n        await store.initialize()\n        default_repo = await store.get_default()\n    except Exception as exc:  # noqa: BLE001 - fallback discovery must be best-effort\n        log.warning(\"mcp.tool.evaluate.brownfield_default_lookup_failed\", error=str(exc))\n        return None\n    finally:\n        await store.close()\n\n    if default_repo is None or not default_repo.path:\n        return None\n\n    resolved = Path(default_repo.path).expanduser().resolve()\n    if not resolved.is_dir():\n        log.warning(\n            \"mcp.tool.evaluate.brownfield_default_unusable\",\n            path=str(resolved),\n        )\n        return None\n    return resolved\n\n\ndef _seed_project_dir(seed: Seed | None, *, stable_base: Path) -> Path | None:\n    \"\"\"Resolve a contained project directory encoded in seed metadata/context.\"\"\"\n    resolution = resolve_seed_project_path(seed, stable_base=stable_base)\n    if resolution.path is None:\n        return None\n\n    resolved = resolution.path\n    if resolved.is_file():\n        return resolved.parent\n    if resolved.exists() and not resolved.is_dir():\n        return None\n    return resolved\n\n\nasync def _resolve_evaluate_working_dir(\n    explicit_working_dir: str | None,\n    seed: Seed | None,\n) -> Path:\n    \"\"\"Resolve the project root that gates Stage 1 and Stage 2 evaluation.\n\n    Precedence is explicit tool argument, registered brownfield default,\n    seed-declared project directory, then the MCP server cwd. The last\n    fallback preserves the historical behavior, but only after project-aware\n    sources have been exhausted.\n    \"\"\"\n    stable_base = Path.cwd().resolve()\n    if explicit_working_dir:\n        resolved = resolve_path_against_base(explicit_working_dir, stable_base=stable_base)\n        if resolved is not None:\n            return resolved\n\n    brownfield_default = await _default_brownfield_project_dir()\n    if brownfield_default is not None:\n        if brownfield_default.is_dir():\n            return brownfield_default.resolve()\n        log.warning(\n            \"mcp.tool.evaluate.brownfield_default_unusable\",\n            path=str(brownfield_default),\n        )\n\n    seed_dir = _seed_project_dir(seed, stable_base=stable_base)\n    if seed_dir is not None:\n        return seed_dir\n\n    return stable_base\n\n\nasync def _resolve_executor_backend(store: EventStore | None, session_id: str) -> str | None:\n    \"\"\"Best-effort: which runtime backend executed this session (PR-X X2).\n\n    Read from the ``execution.session.completed`` / ``.started`` lifecycle events,\n    whose payload carries ``runtime_backend`` per node. Lets formal evaluation\n    keep the executor's own vendor out of the reviewer jury. Any failure returns\n    ``None`` — evaluation then behaves exactly as before.\n    \"\"\"\n    if store is None or not session_id:\n        return None\n    try:\n        for event_type in (\n            \"execution.session.completed\",\n            \"execution.session.started\",\n        ):\n            events = await store.query_session_related_events(\n                session_id, event_type=event_type, limit=50\n            )\n            for event in events:\n                data = event.data if isinstance(event.data, dict) else {}\n                backend = data.get(\"runtime_backend\")\n                if isinstance(backend, str) and backend.strip():\n                    return backend.strip()\n    except Exception:\n        return None\n    return None\n\n\ndef _evaluation_allowed_tools(runtime_backend: str | None) -> list[str]:\n    \"\"\"Return the policy-derived read-only tool envelope for evaluation.\"\"\"\n    return allowed_runtime_builtin_tool_names(\n        PolicyContext(\n            runtime_backend=runtime_backend,\n            session_role=PolicySessionRole.EVALUATION,\n            execution_phase=PolicyExecutionPhase.EVALUATION,\n        )\n    )\n\n\n@dataclass\nclass MeasureDriftHandler:\n    \"\"\"Handler for the measure_drift tool.\n\n    Measures goal deviation from the original seed specification\n    using DriftMeasurement with weighted components:\n    goal (50%), constraint (30%), ontology (20%).\n    \"\"\"\n\n    event_store: EventStore | None = field(default=None, repr=False)\n\n    @property\n    def definition(self) -> MCPToolDefinition:\n        \"\"\"Return the tool definition.\"\"\"\n        return MCPToolDefinition(\n            name=\"ouroboros_measure_drift\",\n            description=(\n                \"Measure drift from the original seed goal. \"\n                \"Calculates goal deviation score using weighted components: \"\n                \"goal drift (50%), constraint drift (30%), ontology drift (20%). \"\n                \"Returns drift metrics, analysis, and suggestions if drift exceeds threshold.\"\n            ),\n            parameters=(\n                MCPToolParameter(\n                    name=\"session_id\",\n                    type=ToolInputType.STRING,\n                    description=\"The execution session ID to measure drift for\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"current_output\",\n                    type=ToolInputType.STRING,\n                    description=\"Current execution output to measure drift against the seed goal\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"seed_content\",\n                    type=ToolInputType.STRING,\n                    description=\"Original seed YAML content for drift calculation\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"constraint_violations\",\n                    type=ToolInputType.ARRAY,\n                    description=\"Known constraint violations (e.g., ['Missing tests', 'Wrong language'])\",\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"current_concepts\",\n                    type=ToolInputType.ARRAY,\n                    description=\"Concepts present in the current output (for ontology drift)\",\n                    required=False,\n                ),\n            ),\n        )\n\n    async def handle(\n        self,\n        arguments: dict[str, Any],\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Handle a drift measurement request.\n\n        Args:\n            arguments: Tool arguments including session_id, current_output, and seed_content.\n\n        Returns:\n            Result containing drift metrics or error.\n        \"\"\"\n        session_id = arguments.get(\"session_id\")\n        if not session_id:\n            return Result.err(\n                MCPToolError(\n                    \"session_id is required\",\n                    tool_name=\"ouroboros_measure_drift\",\n                )\n            )\n\n        current_output = arguments.get(\"current_output\")\n        if not current_output:\n            return Result.err(\n                MCPToolError(\n                    \"current_output is required\",\n                    tool_name=\"ouroboros_measure_drift\",\n                )\n            )\n\n        seed_content = arguments.get(\"seed_content\")\n        if not seed_content:\n            return Result.err(\n                MCPToolError(\n                    \"seed_content is required\",\n                    tool_name=\"ouroboros_measure_drift\",\n                )\n            )\n\n        constraint_violations_raw = arguments.get(\"constraint_violations\") or []\n        current_concepts_raw = arguments.get(\"current_concepts\") or []\n\n        log.info(\n            \"mcp.tool.measure_drift\",\n            session_id=session_id,\n            output_length=len(current_output),\n            violations_count=len(constraint_violations_raw),\n        )\n\n        try:\n            # Parse seed YAML\n            seed_dict = yaml.safe_load(seed_content)\n            seed = Seed.from_dict(seed_dict)\n        except yaml.YAMLError as e:\n            return Result.err(\n                MCPToolError(\n                    f\"Failed to parse seed YAML: {e}\",\n                    tool_name=\"ouroboros_measure_drift\",\n                )\n            )\n        except (ValidationError, PydanticValidationError) as e:\n            return Result.err(\n                MCPToolError(\n                    f\"Seed validation failed: {e}\",\n                    tool_name=\"ouroboros_measure_drift\",\n                )\n            )\n\n        try:\n            # Calculate drift using real DriftMeasurement\n            measurement = DriftMeasurement()\n            metrics = await measurement.measure_async(\n                current_output=current_output,\n                constraint_violations=[str(v) for v in constraint_violations_raw],\n                current_concepts=[str(c) for c in current_concepts_raw],\n                seed=seed,\n            )\n\n            drift_text = (\n                f\"Drift Measurement Report\\n\"\n                f\"=======================\\n\"\n                f\"Session: {session_id}\\n\"\n                f\"Seed ID: {seed.metadata.seed_id}\\n\"\n                f\"Goal: {seed.goal}\\n\\n\"\n                f\"Combined Drift: {metrics.combined_drift:.2f}\\n\"\n                f\"Acceptable Threshold: {DRIFT_THRESHOLD}\\n\"\n                f\"Status: {'ACCEPTABLE' if metrics.is_acceptable else 'EXCEEDED'}\\n\\n\"\n                f\"Component Breakdown:\\n\"\n                f\"  Goal Drift: {metrics.goal_drift:.2f} (50% weight)\\n\"\n                f\"  Constraint Drift: {metrics.constraint_drift:.2f} (30% weight)\\n\"\n                f\"  Ontology Drift: {metrics.ontology_drift:.2f} (20% weight)\\n\"\n            )\n\n            suggestions: list[str] = []\n            if not metrics.is_acceptable:\n                suggestions.append(\"Drift exceeds threshold - consider consensus review\")\n                suggestions.append(\"Review execution path against original goal\")\n                if metrics.constraint_drift > 0:\n                    suggestions.append(\n                        f\"Constraint violations detected: {constraint_violations_raw}\"\n                    )\n\n            if suggestions:\n                drift_text += \"\\nSuggestions:\\n\"\n                for s in suggestions:\n                    drift_text += f\"  - {s}\\n\"\n\n            return Result.ok(\n                MCPToolResult(\n                    content=(MCPContentItem(type=ContentType.TEXT, text=drift_text),),\n                    is_error=False,\n                    meta={\n                        \"session_id\": session_id,\n                        \"seed_id\": seed.metadata.seed_id,\n                        \"goal_drift\": metrics.goal_drift,\n                        \"constraint_drift\": metrics.constraint_drift,\n                        \"ontology_drift\": metrics.ontology_drift,\n                        \"combined_drift\": metrics.combined_drift,\n                        \"is_acceptable\": metrics.is_acceptable,\n                        \"threshold\": DRIFT_THRESHOLD,\n                        \"suggestions\": suggestions,\n                    },\n                )\n            )\n        except Exception as e:\n            log.error(\"mcp.tool.measure_drift.error\", error=str(e))\n            return Result.err(\n                MCPToolError(\n                    f\"Failed to measure drift: {e}\",\n                    tool_name=\"ouroboros_measure_drift\",\n                )\n            )\n\n\n@dataclass\nclass EvaluateHandler:\n    \"\"\"Handler for the ouroboros_evaluate tool.\n\n    Evaluates an execution session using the three-stage evaluation pipeline:\n    Stage 1: Mechanical Verification ($0)\n    Stage 2: Semantic Evaluation (Standard tier)\n    Stage 3: Multi-Model Consensus (Frontier tier, if triggered)\n    \"\"\"\n\n    event_store: EventStore | None = field(default=None, repr=False)\n    llm_backend: str | None = field(default=None, repr=False)\n    agent_runtime_backend: str | None = field(default=None, repr=False)\n    opencode_mode: str | None = field(default=None, repr=False)\n    TIMEOUT_SECONDS: int = 0  # No server-side timeout; client/runtime decides.\n\n    @property\n    def definition(self) -> MCPToolDefinition:\n        \"\"\"Return the tool definition.\"\"\"\n        return MCPToolDefinition(\n            name=\"ouroboros_evaluate\",\n            description=(\n                \"Evaluate an Ouroboros execution session using the three-stage evaluation pipeline. \"\n                \"Stage 1 performs mechanical verification (lint, build, test). \"\n                \"Stage 2 performs semantic evaluation of AC compliance and goal alignment. \"\n                \"Stage 3 runs multi-model consensus if triggered by uncertainty or manual request.\"\n            ),\n            parameters=(\n                MCPToolParameter(\n                    name=\"session_id\",\n                    type=ToolInputType.STRING,\n                    description=\"The execution session ID to evaluate\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"artifact\",\n                    type=ToolInputType.STRING,\n                    description=\"The execution output/artifact to evaluate\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"seed_content\",\n                    type=ToolInputType.STRING,\n                    description=\"Original seed YAML for goal/constraints extraction\",\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"acceptance_criterion\",\n                    type=ToolInputType.STRING,\n                    description=\"Specific acceptance criterion to evaluate against\",\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"acceptance_criteria\",\n                    type=ToolInputType.ARRAY,\n                    description=(\n                        \"Multiple acceptance criteria for checklist evaluation. \"\n                        \"When two or more items are provided, each AC is evaluated \"\n                        \"independently and the results are aggregated into a \"\n                        \"pass/fail checklist (#366). Overrides acceptance_criterion.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"artifact_type\",\n                    type=ToolInputType.STRING,\n                    description=\"Type of artifact: code, docs, config. Default: code\",\n                    required=False,\n                    default=\"code\",\n                    enum=(\"code\", \"docs\", \"config\"),\n                ),\n                MCPToolParameter(\n                    name=\"trigger_consensus\",\n                    type=ToolInputType.BOOLEAN,\n                    description=\"Force Stage 3 consensus evaluation. Default: False\",\n                    required=False,\n                    default=False,\n                ),\n                MCPToolParameter(\n                    name=\"working_dir\",\n                    type=ToolInputType.STRING,\n                    description=(\n                        \"Project root used to resolve Stage 1 mechanical verification \"\n                        \"commands and Stage 2 source-file visibility. Commands are \"\n                        \"read from .ouroboros/mechanical.toml; \"\n                        \"when the file is missing, the evaluator makes one AI detect \"\n                        \"call that inspects manifests (package.json, pyproject.toml, \"\n                        \"Cargo.toml, Makefile, ...) and authors the toml. Stage 1 \"\n                        \"skips every check when no toml is produced — it never guesses.\"\n                    ),\n                    required=False,\n                ),\n            ),\n        )\n\n    async def handle(\n        self,\n        arguments: dict[str, Any],\n        *,\n        emit_terminal_telemetry: bool = True,\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Handle an evaluation request.\n\n        Args:\n            arguments: Tool arguments including session_id, artifact, and optional seed_content.\n            emit_terminal_telemetry: Whether this call owns the direct-evaluation\n                telemetry boundary. True (default) for genuine top-level direct\n                calls — the MCP adapter dispatching ``ouroboros_evaluate``, or\n                ``ChecklistVerifyHandler`` delegating in multi-AC mode (neither\n                is observed by JobManager). False when the caller is itself\n                job-backed (``run_evaluation_job`` behind ``StartEvaluateHandler``),\n                since ``JobTelemetryBoundary`` already emits a deduplicated\n                (``$insert_id``-keyed) terminal outcome for that job — this\n                handler is a shared instance reused across both call shapes\n                (see ``definitions.py``), so the decision must be made by the\n                caller at each call, not baked into the instance.\n\n        Returns:\n            Result containing evaluation results or error.\n        \"\"\"\n        from ouroboros.evaluation import (\n            EvaluationContext,\n            EvaluationPipeline,\n            PipelineConfig,\n            SemanticConfig,\n            build_mechanical_config,\n            ensure_mechanical_toml,\n            has_mechanical_toml,\n        )\n\n        session_id = arguments.get(\"session_id\")\n        if not session_id:\n            return Result.err(\n                MCPToolError(\n                    \"session_id is required\",\n                    tool_name=\"ouroboros_evaluate\",\n                    failure_meta={\"failure_reason_code\": \"validation\"},\n                )\n            )\n\n        artifact = arguments.get(\"artifact\")\n        if not artifact:\n            return Result.err(\n                MCPToolError(\n                    \"artifact is required\",\n                    tool_name=\"ouroboros_evaluate\",\n                    failure_meta={\"failure_reason_code\": \"validation\"},\n                )\n            )\n\n        seed_content = arguments.get(\"seed_content\")\n        acceptance_criterion = arguments.get(\"acceptance_criterion\")\n        acceptance_criteria_raw = arguments.get(\"acceptance_criteria\")\n        artifact_type = arguments.get(\"artifact_type\", \"code\")\n        trigger_consensus = arguments.get(\"trigger_consensus\", False)\n\n        # Normalize all AC inputs into a single tuple (#366 fix):\n        # 1. If acceptance_criteria (plural, ARRAY) has valid entries, use them.\n        # 2. Else if acceptance_criterion (singular, STRING) is set, wrap it.\n        # 3. Else empty — single-AC path will use a default.\n        # This ensures a 1-item list is honoured as the effective AC,\n        # fixing the contract violation where the input shape was accepted\n        # but its meaning was silently ignored.\n        acceptance_criteria: tuple[str, ...] = ()\n        if isinstance(acceptance_criteria_raw, list):\n            acceptance_criteria = tuple(\n                str(item).strip()\n                for item in acceptance_criteria_raw\n                if isinstance(item, (str, int, float)) and str(item).strip()\n            )\n        if not acceptance_criteria and acceptance_criterion and str(acceptance_criterion).strip():\n            acceptance_criteria = (str(acceptance_criterion).strip(),)\n\n        # Parse seed before dispatch so working_dir fallback is available for\n        # both plugin/subagent and in-process evaluation paths.\n        goal = \"\"\n        constraints: tuple[str, ...] = ()\n        seed_id = session_id  # fallback\n        seed: Seed | None = None\n\n        if seed_content:\n            try:\n                seed_dict = yaml.safe_load(seed_content)\n                seed = Seed.from_dict(seed_dict)\n                goal = seed.goal\n                constraints = tuple(seed.constraints)\n                seed_id = seed.metadata.seed_id\n                if not acceptance_criteria:\n                    acceptance_criteria = _seed_acceptance_criteria(seed)\n            except (yaml.YAMLError, ValidationError, PydanticValidationError) as e:\n                # Seed failed to parse — leave seed as None; spec map stays empty.\n                log.warning(\"mcp.tool.evaluate.seed_parse_warning\", error=str(e))\n                # Continue without seed data - not fatal\n\n        log.info(\n            \"mcp.tool.evaluate\",\n            session_id=session_id,\n            has_seed=seed_content is not None,\n            multi_ac_count=len(acceptance_criteria),\n            trigger_consensus=trigger_consensus,\n        )\n\n        working_dir = await _resolve_evaluate_working_dir(arguments.get(\"working_dir\"), seed)\n\n        if len(acceptance_criteria) > 1:\n            ac_for_payload: str | None = \"\\n\".join(\n                f\"{i + 1}. {ac}\" for i, ac in enumerate(acceptance_criteria)\n            )\n        elif acceptance_criteria:\n            ac_for_payload = acceptance_criteria[0]\n        else:\n            ac_for_payload = None\n        from ouroboros.mcp.tools.evaluation_job import worker_safe_evaluation_inputs\n\n        worker_inputs = worker_safe_evaluation_inputs(seed_content, ac_for_payload, artifact)\n        payload = build_evaluate_subagent(\n            session_id=session_id,\n            artifact=worker_inputs.artifact,\n            artifact_type=artifact_type,\n            seed_content=worker_inputs.seed_content,\n            acceptance_criterion=worker_inputs.acceptance_criterion,\n            working_dir=str(working_dir),\n            trigger_consensus=trigger_consensus,\n        )\n        if (\n            should_dispatch_via_plugin(self.agent_runtime_backend, self.opencode_mode)\n            and arguments.get(\"_force_in_process\") is not True\n        ):\n            # Preserve public response shape (#442): session_id + status are\n            # part of the documented contract for ouroboros_evaluate.\n            return await dispatch_plugin_terminal(\n                self.event_store,\n                session_id=session_id,\n                payload=payload,\n                response_shape={\n                    \"session_id\": session_id,\n                    \"status\": DELEGATED_TO_SUBAGENT,\n                    \"dispatch_mode\": \"plugin\",\n                    \"artifact_type\": artifact_type,\n                    \"trigger_consensus\": trigger_consensus,\n                },\n            )\n\n        # Fall-through: real in-process evaluation pipeline (subprocess / non-opencode runtimes).\n\n        store = self.event_store\n        owns_event_store = False\n\n        try:\n            # Try to enrich from session repository if event_store available\n            if not goal:\n                if store is None:\n                    store = EventStore()\n                    owns_event_store = True\n                try:\n                    await store.initialize()\n                    repo = SessionRepository(store)\n                    session_result = await repo.reconstruct_session(session_id)\n                    if session_result.is_ok:\n                        tracker = session_result.value\n                        seed_id = tracker.seed_id\n                except Exception:\n                    pass  # Best-effort enrichment\n\n            # PR-X X2: resolve which runtime backend executed this session so\n            # consensus can keep that vendor out of the reviewer jury. Best-effort\n            # — None leaves today's behavior untouched.\n            executor_backend = await _resolve_executor_backend(store, session_id)\n\n            # The controller already ran the frozen check package for this run;\n            # its recorded per-criterion decision is Stage 1 evidence for that\n            # criterion (evaluation_package_evidence). No decision, no evidence.\n            by_position: tuple[tuple[CheckResult, ...], ...] = ()\n            if seed is not None:\n                if store is None:\n                    store = EventStore()\n                    owns_event_store = True\n                try:\n                    await store.initialize()\n                    by_position = await recorded_checks_by_position(store, session_id, seed)\n                except Exception as exc:  # noqa: BLE001 — a read failure is no evidence\n                    log.warning(\n                        \"mcp.tool.evaluate.recorded_decision_unreadable\",\n                        session_id=session_id,\n                        error=str(exc),\n                    )\n            recorded_checks = (\n                evidence_for_criteria(acceptance_criteria, seed, by_position)\n                if seed is not None\n                else tuple(() for _ in acceptance_criteria)\n            )\n\n            # Derive current_ac from the unified acceptance_criteria tuple.\n            # The tuple already incorporates both the plural and singular params,\n            # so we only need to index or fall back to a default.\n            current_ac = (\n                acceptance_criteria[0]\n                if acceptance_criteria\n                else \"Verify execution output meets requirements\"\n            )\n\n            # Reattach declared success contracts (PR-H): map AC text back to\n            # its structured spec so Stage 2 grades against verify_command /\n            # expected_artifacts / output_assertion, not the bare wording.\n            ac_spec_map = _seed_ac_spec_map(seed)\n\n            # Evaluation reads multiple spec files (one Read call per AC).\n            # Use a dedicated adapter with a higher turn budget — the shared\n            # MCP adapter is max_turns=1 (tuned for interview/seed single-shot).\n            backend = get_llm_backend_for_role(\n                \"semantic_evaluation\",\n                explicit_backend=self.llm_backend,\n            )\n            llm_adapter = create_llm_adapter(\n                backend=backend,\n                allowed_tools=_evaluation_allowed_tools(backend),\n                max_turns=20,\n            )\n            log.info(\n                \"mcp.tool.evaluate.started\",\n                session_id=session_id,\n                artifact_type=artifact_type,\n                working_dir=str(working_dir),\n                llm_backend=backend,\n                adapter_type=type(llm_adapter).__name__,\n            )\n\n            # Collect file-based artifacts for richer semantic evaluation.\n            # working_dir is used as the project root for artifact resolution.\n            #\n            # The artifact text (potentially 50KB+) is kept as a file under the\n            # data dir, never in working_dir, and joins the collected files so\n            # the prompt does not inline it.\n            from ouroboros.core.owner_only import write_owner_only\n            from ouroboros.evaluation.artifact_collector import (\n                ArtifactCollector,\n                eval_artifact_path,\n                with_artifact_file,\n            )\n\n            artifact_file = eval_artifact_path(working_dir)\n            try:\n                artifact_file.parent.mkdir(parents=True, exist_ok=True)\n                write_owner_only(artifact_file, artifact)\n            except OSError:\n                pass  # Non-critical — evaluator falls back to text_summary\n\n            try:\n                artifact_bundle = with_artifact_file(\n                    ArtifactCollector().collect(artifact, str(working_dir)), artifact_file, artifact\n                )\n            except Exception as exc:\n                log.warning(\n                    \"mcp.tool.evaluate.artifact_collection_failed\",\n                    error=str(exc),\n                    working_dir=str(working_dir),\n                )\n                artifact_bundle = None\n\n            # Stage 1 trusts .ouroboros/mechanical.toml only. When the file is\n            # absent we run the AI detector once to author it (best-effort).\n            # A failed detect leaves Stage 1 with no configured check, which\n            # is not executed evidence: the pipeline still runs the advisory\n            # Stage 2 review, and the result is reported as unverified rather\n            # than phantom-failing on hardcoded preset guesses.\n            if not has_mechanical_toml(working_dir):\n                try:\n                    await ensure_mechanical_toml(\n                        working_dir,\n                        llm_adapter,\n                        backend=backend,\n                    )\n                except Exception as exc:  # noqa: BLE001 — detector must never break eval\n                    log.warning(\n                        \"mcp.tool.evaluate.detect_failed\",\n                        working_dir=str(working_dir),\n                        error=str(exc),\n                    )\n            mechanical_config = build_mechanical_config(working_dir)\n            config = PipelineConfig(\n                mechanical=mechanical_config,\n                semantic=SemanticConfig(\n                    model=get_llm_model_for_role(\"semantic_evaluation\", backend=backend)\n                ),\n            )\n            pipeline = EvaluationPipeline(llm_adapter, config)\n\n            # Multi-AC checklist path (#366):\n            # When the caller provides >= 2 acceptance criteria we run the\n            # pipeline once per AC and aggregate the results into a\n            # checklist.  Single-AC callers keep the original single-pass\n            # behaviour — no extra cost or behaviour change for them.\n            if len(acceptance_criteria) >= 2:\n                return await self._handle_multi_ac(\n                    session_id=session_id,\n                    seed_id=seed_id,\n                    acceptance_criteria=acceptance_criteria,\n                    artifact=artifact,\n                    artifact_type=artifact_type,\n                    goal=goal,\n                    constraints=constraints,\n                    trigger_consensus=trigger_consensus,\n                    artifact_bundle=artifact_bundle,\n                    pipeline=pipeline,\n                    working_dir=working_dir,\n                    executor_backend=executor_backend,\n                    ac_spec_map=ac_spec_map,\n                    emit_terminal_telemetry=emit_terminal_telemetry,\n                    recorded_checks=recorded_checks,\n                )\n\n            context = EvaluationContext(\n                execution_id=session_id,\n                seed_id=seed_id,\n                current_ac=current_ac,\n                current_ac_spec=ac_spec_map.get(current_ac),\n                artifact=artifact,\n                artifact_type=artifact_type,\n                goal=goal,\n                constraints=constraints,\n                trigger_consensus=trigger_consensus,\n                artifact_bundle=artifact_bundle,\n                executor_backend=executor_backend,\n                recorded_checks=recorded_checks[0] if acceptance_criteria else (),\n            )\n            result = await pipeline.evaluate(context)\n\n            if result.is_err:\n                rendered_error = (\n                    result.error.format_details()\n                    if hasattr(result.error, \"format_details\")\n                    else str(result.error)\n                )\n                log.warning(\n                    \"mcp.tool.evaluate.pipeline_failed\",\n                    session_id=session_id,\n                    working_dir=str(working_dir),\n                    llm_backend=backend,\n                    error=rendered_error,\n                )\n                if emit_terminal_telemetry:\n                    record_direct_evaluation_outcome(\n                        final_approved=None,\n                        failed=True,\n                        failure_reason_code=_direct_evaluation_failure_reason(result.error),\n                    )\n                return Result.err(\n                    MCPToolError(\n                        f\"Evaluation failed: {rendered_error}\",\n                        tool_name=\"ouroboros_evaluate\",\n                        failure_meta=_failure_reason_details(result.error),\n                    )\n                )\n\n            eval_result = result.value\n\n            # Detect code changes when Stage 1 fails (presentation concern)\n            code_changes: bool | None = None\n            if (\n                eval_result.stage1_result\n                and eval_result.stage1_result.disposition is MechanicalDisposition.EXECUTED_FAIL\n            ):\n                code_changes = await self._has_code_changes(working_dir)\n\n            # Build result text\n            result_text = self._format_evaluation_result(eval_result, code_changes=code_changes)\n\n            # Build metadata\n            meta = {\n                \"session_id\": session_id,\n                \"final_approved\": eval_result.final_approved,\n                \"acceptance_state\": eval_result.acceptance_state.value,\n                \"executed_evidence\": eval_result.has_executed_evidence,\n                \"failure_reason\": eval_result.failure_reason,\n                \"highest_stage\": eval_result.highest_stage_completed,\n                \"stage1_passed\": eval_result.stage1_result.passed\n                if eval_result.stage1_result\n                else None,\n                \"stage2_ac_compliance\": eval_result.stage2_result.ac_compliance\n                if eval_result.stage2_result\n                else None,\n                \"stage2_score\": eval_result.stage2_result.score\n                if eval_result.stage2_result\n                else None,\n                \"stage3_approved\": eval_result.stage3_result.approved\n                if eval_result.stage3_result\n                else None,\n                \"stage3_reviewer_independence\": eval_result.stage3_result.reviewer_independence\n                if eval_result.stage3_result\n                else None,\n                \"code_changes_detected\": code_changes,\n            }\n\n            if emit_terminal_telemetry:\n                record_direct_evaluation_outcome(final_approved=eval_result.final_approved)\n            return Result.ok(\n                MCPToolResult(\n                    content=(MCPContentItem(type=ContentType.TEXT, text=result_text),),\n                    is_error=False,\n                    meta=meta,\n                )\n            )\n        except ConfigError as e:\n            # Configuration/bootstrap errors (unsupported backend, missing\n            # provider install) — actionable by the user, safe to surface.\n            log.warning(\"mcp.tool.evaluate.config_error\", error=str(e))\n            if emit_terminal_telemetry:\n                record_direct_evaluation_outcome(\n                    final_approved=None,\n                    failed=True,\n                    failure_reason_code=\"config\",\n                )\n            return Result.err(\n                MCPToolError(\n                    f\"Evaluation setup failed: {e}\",\n                    tool_name=\"ouroboros_evaluate\",\n                    failure_meta={\"failure_reason_code\": \"config\"},\n                )\n            )\n        except (ValueError, RuntimeError) as e:\n            # Preserve the historical setup-facing response for these factory\n            # failures, but do not infer ``config`` from a generic built-in\n            # exception. Only a typed ConfigError earns that telemetry reason.\n            log.warning(\"mcp.tool.evaluate.setup_error\", error=str(e))\n            if emit_terminal_telemetry:\n                record_direct_evaluation_outcome(\n                    final_approved=None,\n                    failed=True,\n                    failure_reason_code=_direct_evaluation_failure_reason(e),\n                )\n            return Result.err(\n                MCPToolError(\n                    f\"Evaluation setup failed: {e}\",\n                    tool_name=\"ouroboros_evaluate\",\n                    failure_meta=_failure_reason_details(e),\n                )\n            )\n        except Exception as exc:\n            log.exception(\"mcp.tool.evaluate.error\")\n            if emit_terminal_telemetry:\n                record_direct_evaluation_outcome(\n                    final_approved=None,\n                    failed=True,\n                    failure_reason_code=_direct_evaluation_failure_reason(exc),\n                )\n            return Result.err(\n                MCPToolError(\n                    \"Evaluation failed due to an internal error. Check server logs for details.\",\n                    tool_name=\"ouroboros_evaluate\",\n                    failure_meta=_failure_reason_details(exc),\n                )\n            )\n        finally:\n            if owns_event_store and store is not None:\n                await store.close()\n\n    async def _handle_multi_ac(\n        self,\n        *,\n        session_id: str,\n        seed_id: str,\n        acceptance_criteria: tuple[str, ...],\n        artifact: str,\n        artifact_type: str,\n        goal: str,\n        constraints: tuple[str, ...],\n        trigger_consensus: bool,\n        artifact_bundle: object | None,\n        pipeline: object,  # EvaluationPipeline — typed as object to avoid import cycle\n        working_dir: Path,\n        executor_backend: str | None = None,\n        ac_spec_map: dict[str, AcceptanceCriterionSpec] | None = None,\n        emit_terminal_telemetry: bool = True,\n        recorded_checks: tuple[tuple[CheckResult, ...], ...] = (),\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Evaluate each AC individually and return an aggregated checklist (#366).\n\n        Stage 1 (mechanical verification — lint/build/test) is AC-agnostic,\n        so we run it exactly once via the first AC's full pipeline call and\n        inject the result into the remaining per-AC evaluations.  Only\n        Stage 2+ (semantic evaluation) is parallelized per AC via\n        ``asyncio.gather``.\n\n        Per-AC results are then folded into a single ``ACChecklistResult``\n        so the caller sees one pass/fail checklist with per-item evidence\n        and failure reasons.\n\n        Single-AC callers never reach this path — see ``handle()``.\n        \"\"\"\n\n        from ouroboros.evaluation import EvaluationContext\n        from ouroboros.evaluation.checklist import (\n            aggregate_results,\n            build_run_feedback,\n            format_checklist,\n        )\n\n        spec_map = ac_spec_map or {}\n        # Each criterion's own recorded evidence, by position.\n        recorded = recorded_checks or tuple(() for _ in acceptance_criteria)\n\n        log.info(\n            \"mcp.tool.evaluate.multi_ac_started\",\n            session_id=session_id,\n            ac_count=len(acceptance_criteria),\n        )\n\n        # --- Stage 1: run once via the first AC's full pipeline call ---\n        first_context = EvaluationContext(\n            execution_id=session_id,\n            seed_id=seed_id,\n            current_ac=acceptance_criteria[0],\n            current_ac_spec=spec_map.get(acceptance_criteria[0]),\n            artifact=artifact,\n            artifact_type=artifact_type,\n            goal=goal,\n            constraints=constraints,\n            trigger_consensus=trigger_consensus,\n            artifact_bundle=artifact_bundle,\n            executor_backend=executor_backend,\n            recorded_checks=recorded[0],\n        )\n        first_result = await pipeline.evaluate(first_context)  # type: ignore[attr-defined]\n        if first_result.is_err:\n            err = first_result.error\n            rendered = err.format_details() if hasattr(err, \"format_details\") else str(err)\n            if emit_terminal_telemetry:\n                record_direct_evaluation_outcome(\n                    final_approved=None,\n                    failed=True,\n                    failure_reason_code=_direct_evaluation_failure_reason(err),\n                )\n            return Result.err(\n                MCPToolError(\n                    f\"Evaluation failed: {rendered}\",\n                    tool_name=\"ouroboros_evaluate\",\n                )\n            )\n\n        # Share the project command checks only; each AC adds its own\n        # recorded check package evidence (``recorded_checks``).\n        first_stage1 = first_result.value.stage1_result\n        shared_stage1 = first_stage1.command_checks() if first_stage1 is not None else None\n\n        # --- Stage 2+: parallelize remaining ACs (Stage 1 injected) ---\n        async def _run_one(index: int, ac_text: str) -> Result[object, object]:\n            context = EvaluationContext(\n                execution_id=session_id,\n                seed_id=seed_id,\n                current_ac=ac_text,\n                current_ac_spec=spec_map.get(ac_text),\n                artifact=artifact,\n                artifact_type=artifact_type,\n                goal=goal,\n                constraints=constraints,\n                trigger_consensus=trigger_consensus,\n                artifact_bundle=artifact_bundle,\n                executor_backend=executor_backend,\n                recorded_checks=recorded[index],\n            )\n            return await pipeline.evaluate(  # type: ignore[attr-defined]\n                context,\n                stage1_result=shared_stage1,\n            )\n\n        remaining_gathered = await asyncio.gather(\n            *(_run_one(index, ac) for index, ac in enumerate(acceptance_criteria) if index),\n            return_exceptions=True,\n        )\n        gathered = (first_result, *remaining_gathered)\n\n        # Any exception or err-Result aborts the whole checklist —\n        # otherwise we'd aggregate over a half-evaluated set.\n        for entry in gathered:\n            if isinstance(entry, BaseException):\n                log.exception(\n                    \"mcp.tool.evaluate.multi_ac_exception\",\n                    session_id=session_id,\n                )\n                if emit_terminal_telemetry:\n                    record_direct_evaluation_outcome(\n                        final_approved=None,\n                        failed=True,\n                        failure_reason_code=_direct_evaluation_failure_reason(entry),\n                    )\n                return Result.err(\n                    MCPToolError(\n                        f\"Evaluation failed during multi-AC run: {entry}\",\n                        tool_name=\"ouroboros_evaluate\",\n                    )\n                )\n            if entry.is_err:  # type: ignore[union-attr]\n                err = entry.error  # type: ignore[union-attr]\n                rendered = err.format_details() if hasattr(err, \"format_details\") else str(err)\n                log.warning(\n                    \"mcp.tool.evaluate.multi_ac_pipeline_failed\",\n                    session_id=session_id,\n                    error=rendered,\n                )\n                if emit_terminal_telemetry:\n                    record_direct_evaluation_outcome(\n                        final_approved=None,\n                        failed=True,\n                        failure_reason_code=_direct_evaluation_failure_reason(err),\n                    )\n                return Result.err(\n                    MCPToolError(\n                        f\"Evaluation failed: {rendered}\",\n                        tool_name=\"ouroboros_evaluate\",\n                    )\n                )\n\n        eval_results = tuple(entry.value for entry in gathered)  # type: ignore[union-attr]\n        checklist = aggregate_results(acceptance_criteria, eval_results)\n        feedback = build_run_feedback(checklist)\n        # The checklist is one aggregate evaluation, so its trustworthy stage\n        # is the highest stage completed by every AC pipeline, not an invented\n        # constant or the best stage reached by only one AC. EvaluationSummary\n        # uses this value as a quality axis in frugality comparisons.\n        highest_stage = min(max(1, result.highest_stage_completed) for result in eval_results)\n\n        code_changes: bool | None = None\n        if any(\n            r.stage1_result and r.stage1_result.disposition is MechanicalDisposition.EXECUTED_FAIL\n            for r in eval_results\n        ):\n            code_changes = await self._has_code_changes(working_dir)\n\n        # The run's Stage 1: the shared command checks plus every criterion's\n        # recorded check package evidence, decided by the one classifier.\n        run_recorded = tuple(check for checks in recorded for check in checks)\n        run_stage1 = shared_stage1\n        if run_recorded:\n            run_stage1 = (shared_stage1 or MechanicalResult(passed=True, checks=())).with_recorded(\n                run_recorded\n            )\n\n        text_parts = [\n            *format_stage1_result(run_stage1, include_exit_status=True),\n            format_checklist(checklist),\n        ]\n        if code_changes is False:\n            text_parts.append(\"\\nNote: no code changes detected in the working tree.\")\n        result_text = \"\\n\".join(text_parts)\n\n        meta = {\n            \"session_id\": session_id,\n            \"final_approved\": checklist.all_passed,\n            \"acceptance_state\": aggregate_acceptance_state(\n                [\n                    derive_acceptance_state(\n                        final_approved=r.final_approved, stage1_result=r.stage1_result\n                    )\n                    for r in eval_results\n                ]\n            ).value,\n            \"executed_evidence\": bool(run_stage1 and run_stage1.has_executed_evidence),\n            \"highest_stage\": highest_stage,\n            \"multi_ac\": True,\n            \"ac_count\": checklist.total,\n            \"passed_count\": checklist.passed_count,\n            \"pass_rate\": checklist.pass_rate,\n            \"checklist\": [\n                {\n                    \"ac_text\": item.ac_text,\n                    \"passed\": item.passed,\n                    \"reasoning\": item.reasoning,\n                    \"evidence\": list(item.evidence),\n                    \"questions_used\": list(item.questions_used),\n                    \"failure_reason\": item.failure_reason,\n                }\n                for item in checklist.items\n            ],\n            \"run_feedback\": list(feedback),\n            \"code_changes_detected\": code_changes,\n            \"stage1_result\": serialize_stage1_result(run_stage1),\n        }\n\n        log.info(\n            \"mcp.tool.evaluate.multi_ac_completed\",\n            session_id=session_id,\n            passed=checklist.passed_count,\n            total=checklist.total,\n            all_passed=checklist.all_passed,\n        )\n\n        if emit_terminal_telemetry:\n            record_direct_evaluation_outcome(final_approved=checklist.all_passed)\n        return Result.ok(\n            MCPToolResult(\n                content=(MCPContentItem(type=ContentType.TEXT, text=result_text),),\n                is_error=False,\n                meta=meta,\n            )\n        )\n\n    async def _has_code_changes(self, working_dir: Path) -> bool | None:\n        \"\"\"Detect whether the working tree has code changes.\n\n        Runs ``git status --porcelain`` to check for modifications.\n\n        Returns:\n            True if changes detected, False if clean, None if not a git repo\n            or git is unavailable.\n        \"\"\"\n        from ouroboros.evaluation.mechanical import run_command\n\n        try:\n            cmd_result = await run_command(\n                (\"git\", \"status\", \"--porcelain\"),\n                timeout=10,\n                working_dir=working_dir,\n            )\n            if cmd_result.return_code != 0:\n                return None\n            return bool(cmd_result.stdout.strip())\n        except Exception:\n            return None\n\n    def _format_evaluation_result(self, result, *, code_changes: bool | None = None) -> str:\n        \"\"\"Format evaluation result as human-readable text.\n\n        Args:\n            result: EvaluationResult from pipeline.\n            code_changes: Whether working tree has code changes (Stage 1 context).\n\n        Returns:\n            Formatted text representation.\n        \"\"\"\n        lines = [\n            \"Evaluation Results\",\n            \"=\" * 60,\n            f\"Execution ID: {result.execution_id}\",\n            f\"Final Approval: {_ACCEPTANCE_LABELS[result.acceptance_state]}\",\n            f\"Highest Stage Completed: {result.highest_stage_completed}\",\n            \"\",\n        ]\n\n        # Stage 1 results\n        lines.extend(format_stage1_result(result.stage1_result))\n\n        # Stage 2 results\n        if result.stage2_result:\n            s2 = result.stage2_result\n            lines.extend(\n                [\n                    \"Stage 2: Semantic Evaluation\",\n                    \"-\" * 40,\n                    f\"Score: {s2.score:.2f}\",\n                    f\"AC Compliance: {'YES' if s2.ac_compliance else 'NO'}\",\n                    f\"Goal Alignment: {s2.goal_alignment:.2f}\",\n                    f\"Drift Score: {s2.drift_score:.2f}\",\n                    f\"Uncertainty: {s2.uncertainty:.2f}\",\n                    f\"Reasoning: {s2.reasoning[:200]}...\"\n                    if len(s2.reasoning) > 200\n                    else f\"Reasoning: {s2.reasoning}\",\n                ]\n            )\n            # Anti-reward-hacking transparency (#367): surface the concrete\n            # Socratic questions and evidence the evaluator relied on so\n            # the user can audit whether the verdict was earned.\n            if s2.questions_used:\n                lines.append(\"Questions Used:\")\n                for question in s2.questions_used:\n                    lines.append(f\"  - {question}\")\n            if s2.evidence:\n                lines.append(\"Evidence:\")\n                for item in s2.evidence:\n                    lines.append(f\"  - {item}\")\n            lines.append(\"\")\n\n        # Stage 3 results\n        if result.stage3_result:\n            s3 = result.stage3_result\n            lines.extend(\n                [\n                    \"Stage 3: Multi-Model Consensus\",\n                    \"-\" * 40,\n                    f\"Status: {'APPROVED' if s3.approved else 'REJECTED'}\",\n                    f\"Majority Ratio: {s3.majority_ratio:.1%}\",\n                    f\"Total Votes: {s3.total_votes}\",\n                    f\"Approving: {s3.approving_votes}\",\n                ]\n            )\n            reviewer_independence = getattr(s3, \"reviewer_independence\", None)\n            if reviewer_independence:\n                lines.append(f\"Reviewer Independence: {reviewer_independence}\")\n            for vote in s3.votes:\n                decision = \"APPROVE\" if vote.approved else \"REJECT\"\n                lines.append(f\"  [{decision}] {vote.model} (confidence: {vote.confidence:.2f})\")\n            if s3.disagreements:\n                lines.append(\"Disagreements:\")\n                for d in s3.disagreements:\n                    lines.append(f\"  - {d[:100]}...\")\n            lines.append(\"\")\n\n        # Failure reason\n        if not result.final_approved:\n            lines.extend(\n                [\n                    \"Failure Reason\",\n                    \"-\" * 40,\n                    result.failure_reason or \"Unknown\",\n                ]\n            )\n            # Contextual annotation for Stage 1 failures\n            stage1_failed = (\n                result.stage1_result is not None\n                and result.stage1_result.disposition is MechanicalDisposition.EXECUTED_FAIL\n            )\n            if stage1_failed and code_changes is True:\n                lines.extend(\n                    [\n                        \"\",\n                        \"⚠ Code changes detected — these are real build/test failures \"\n                        \"that need to be fixed before re-evaluating.\",\n                    ]\n                )\n            elif stage1_failed and code_changes is False:\n                lines.extend(\n                    [\n                        \"\",\n                        \"ℹ No code changes detected in the working tree. These failures \"\n                        \"are expected if you haven't run `ooo run` yet to produce code.\",\n                    ]\n                )\n\n        return \"\\n\".join(lines)\n\n\n@dataclass\nclass ChecklistVerifyHandler:\n    \"\"\"Handler for the ``ouroboros_checklist_verify`` tool (#366).\n\n    Given a seed (containing ``acceptance_criteria``) and an execution\n    artifact, this handler routes each AC through the Stage 2 evaluation\n    pipeline and returns an aggregated checklist.  It is intentionally\n    thin — it composes ``EvaluateHandler`` rather than reimplementing\n    pipeline orchestration, so it stays in sync with any future changes\n    to the main evaluator.\n\n    Why this is a separate tool instead of a flag on ``ouroboros_execute_seed``:\n\n    - ``ExecuteSeed`` is already complex (background execution, resume,\n      delegation) and has a stable public contract.  Adding a retry\n      loop inside it would entangle with Ralph mode and the Job system.\n    - This tool lets the *caller* (a human, a ``/ralph`` loop, or a\n      runtime workflow) decide when and how to retry.  No decisions\n      are hidden inside background tasks.\n    - It is opt-in: existing callers are unaffected.\n    \"\"\"\n\n    evaluate_handler: EvaluateHandler | None = field(default=None, repr=False)\n    llm_backend: str | None = field(default=None, repr=False)\n\n    @property\n    def definition(self) -> MCPToolDefinition:\n        \"\"\"Return the tool definition.\"\"\"\n        return MCPToolDefinition(\n            name=\"ouroboros_checklist_verify\",\n            description=(\n                \"Verify that a Run artifact satisfies every acceptance criterion \"\n                \"in a Seed.  Returns a per-AC checklist (pass/fail with evidence \"\n                \"and failure reasons) plus ready-to-use run_feedback strings the \"\n                \"caller can inject into a re-run prompt.  Does NOT automatically \"\n                \"re-execute — the caller (Ralph, workflow, or human) decides.\"\n            ),\n            parameters=(\n                MCPToolParameter(\n                    name=\"session_id\",\n                    type=ToolInputType.STRING,\n                    description=\"The execution session ID being verified\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"seed_content\",\n                    type=ToolInputType.STRING,\n                    description=(\n                        \"Seed YAML containing acceptance_criteria, goal, constraints. \"\n                        \"The seed's acceptance_criteria list is evaluated in full.\"\n                    ),\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"artifact\",\n                    type=ToolInputType.STRING,\n                    description=\"The Run output/artifact to verify against the seed's ACs\",\n                    required=True,\n                ),\n                MCPToolParameter(\n                    name=\"artifact_type\",\n                    type=ToolInputType.STRING,\n                    description=\"Type of artifact: code, docs, config. Default: code\",\n                    required=False,\n                    default=\"code\",\n                    enum=(\"code\", \"docs\", \"config\"),\n                ),\n                MCPToolParameter(\n                    name=\"working_dir\",\n                    type=ToolInputType.STRING,\n                    description=\"Project working directory (for language auto-detection).\",\n                    required=False,\n                ),\n            ),\n        )\n\n    async def handle(\n        self,\n        arguments: dict[str, Any],\n    ) -> Result[MCPToolResult, MCPServerError]:\n        \"\"\"Verify the seed's full AC list against the artifact.\"\"\"\n        session_id = arguments.get(\"session_id\")\n        if not session_id:\n            return Result.err(\n                MCPToolError(\n                    \"session_id is required\",\n                    tool_name=\"ouroboros_checklist_verify\",\n                )\n            )\n\n        seed_content = arguments.get(\"seed_content\")\n        if not seed_content:\n            return Result.err(\n                MCPToolError(\n                    \"seed_content is required\",\n                    tool_name=\"ouroboros_checklist_verify\",\n                )\n            )\n\n        artifact = arguments.get(\"artifact\")\n        if not artifact:\n            return Result.err(\n                MCPToolError(\n                    \"artifact is required\",\n                    tool_name=\"ouroboros_checklist_verify\",\n                )\n            )\n\n        # Extract acceptance criteria from seed.\n        try:\n            seed_dict = yaml.safe_load(seed_content)\n            seed = Seed.from_dict(seed_dict)\n        except yaml.YAMLError as exc:\n            log.warning(\"mcp.tool.checklist_verify.yaml_error\", error=str(exc))\n            return Result.err(\n                MCPToolError(\n                    f\"Failed to parse seed YAML: {exc}\",\n                    tool_name=\"ouroboros_checklist_verify\",\n                )\n            )\n        except (ValidationError, PydanticValidationError) as exc:\n            log.warning(\"mcp.tool.checklist_verify.seed_validation_error\", error=str(exc))\n            return Result.err(\n                MCPToolError(\n                    f\"Seed validation failed: {exc}\",\n                    tool_name=\"ouroboros_checklist_verify\",\n                )\n            )\n\n        acceptance_criteria = tuple(\n            text for criterion in seed.acceptance_criteria if (text := ac_text(criterion).strip())\n        )\n        if not acceptance_criteria:\n            return Result.err(\n                MCPToolError(\n                    \"Seed has no acceptance_criteria — cannot build checklist.\",\n                    tool_name=\"ouroboros_checklist_verify\",\n                )\n            )\n\n        # Delegate to EvaluateHandler in multi-AC mode.  Re-using the\n        # evaluator means language detection, artifact bundling, event\n        # logging, and LLM backend handling stay consistent.\n        evaluator = self.evaluate_handler or EvaluateHandler(llm_backend=self.llm_backend)\n\n        evaluate_args = {\n            \"session_id\": session_id,\n            \"artifact\": artifact,\n            \"seed_content\": seed_content,\n            \"acceptance_criteria\": list(acceptance_criteria),\n            \"artifact_type\": arguments.get(\"artifact_type\", \"code\"),\n        }\n        if \"working_dir\" in arguments:\n            evaluate_args[\"working_dir\"] = arguments[\"working_dir\"]\n\n        log.info(\n            \"mcp.tool.checklist_verify.started\",\n            session_id=session_id,\n            ac_count=len(acceptance_criteria),\n        )\n\n        # ouroboros_checklist_verify is itself a genuine top-level direct MCP\n        # tool (no \"Start\" job-backed variant, no JobManager wraps it), so the\n        # nested EvaluateHandler call keeps emit_terminal_telemetry at its\n        # default True — nothing else will emit a workflow_outcome for this\n        # invocation.\n        result = await evaluator.handle(evaluate_args)\n\n        if result.is_err:\n            log.warning(\n                \"mcp.tool.checklist_verify.evaluate_failed\",\n                session_id=session_id,\n                error=str(result.error),\n            )\n            return result\n\n        # Augment the MCP result meta so callers can distinguish the\n        # verify path from a plain multi-AC evaluate call.\n        meta = dict(result.value.meta or {})\n        meta[\"checklist_verify\"] = True\n        meta[\"seed_goal\"] = seed.goal\n        augmented = MCPToolResult(\n            content=result.value.content,\n            is_error=result.value.is_error,\n            meta=meta,\n        )\n\n        log.info(\n            \"mcp.tool.checklist_verify.completed\",\n            session_id=session_id,\n            all_passed=meta.get(\"final_approved\"),\n            passed_count=meta.get(\"passed_count\"),\n            ac_count=meta.get(\"ac_count\"),\n        )\n\n        return Result.ok(augmented)\n\n\n@dataclass\nclass StartEvaluateHandler:\n    \"\"\"Start an evaluation asynchronously and return a job ID immediately.\n\n    The three-stage evaluation pipeline (mechanical + semantic + optional\n    consensus) routinely runs longer than an MCP client's default tool-call\n    timeout (Claude Code's MCP layer caps tool calls at ~120s). This handler\n    wraps :class:`EvaluateHandler` in a :class:`JobManager`-backed background\n    job so the caller gets a ``job_id`` immediately and polls for the verdict\n    via ``ouroboros_job_status`` / ``ouroboros_job_wait`` /\n    ``ouroboros_job_result``.\n\n    Plugin mode (OpenCode subagent dispatch) is terminal when automatic\n    evolution is disabled, mirroring :class:`StartExecuteSeedHandler` and\n    :class:`StartEvolveStepHandler`: the envelope is emitted directly and no\n    background job is enqueued. With automatic evolution enabled the parent\n    must observe the verdict, so evaluation stays parent-owned and pollable.\n    \"\"\"\n\n    evaluate_handler: EvaluateHandler | None = field(default=None, repr=False)\n    event_store: EventStore | None = field(default=None, repr=False)\n    job_manager: JobManager | None = field(default=None, repr=False)\n    llm_backend: str | None = field(default=None, repr=False)\n    agent_runtime_backend: str | None = field(default=None, repr=False)\n    opencode_mode: str | None = field(default=None, repr=False)\n    start_ralph_handler: \"StartRalphHandler | None\" = field(default=None, repr=False)\n    seed_handoff_registry: \"SeedHandoffRegistry | None\" = field(default=None, repr=False)\n    deadline_seconds: float = 1800.0\n\n    def __post_init__(self) -> None:\n        self._event_store = self.event_store or EventStore()\n        self._job_manager = self.job_manager or JobManager(self._event_store)\n        self._evaluate_handler = self.evaluate_handler or EvaluateHandler(\n            event_store=self._event_store,\n            llm_backend=self.llm_backend,\n            agent_runtime_backend=self.agent_runtime_backend,\n            opencode_mode=self.opencode_mode,\n        )\n\n    async def _enqueue_chained_ralph(\n        self,\n        evaluation_result: MCPToolResult,\n        *,\n        session_id: str,\n        arguments: dict[str, Any],\n    ) -> MCPToolResult:\n        \"\"\"Compatibility seam for direct chain tests and embedders.\"\"\"\n        from ouroboros.mcp.tools.evaluate_ralph_chain import enqueue_chained_ralph\n\n        return await enqueue_chained_ralph(\n            evaluation_result,\n            session_id=session_id,\n            arguments=arguments,\n            event_store=self._event_store,\n            job_manager=self._job_manager,\n            start_ralph_handler=self.start_ralph_handler,\n        )\n\n    @property\n    def definition(self) -> MCPToolDefinition:\n        return MCPToolDefinition(\n            name=\"ouroboros_start_evaluate\",\n            description=(\n                \"Verify that finished work meets its acceptance criteria, not just \"\n                'that tests pass (\"is it actually done?\", \"check it against '\n                'the spec\"). '\n                \"Start an evaluation in the background and return a job ID immediately. \"\n                \"Use this instead of ouroboros_evaluate when the three-stage pipeline \"\n                \"(mechanical + semantic + optional consensus) is expected to exceed the \"\n                \"MCP client tool-call timeout. Poll with ouroboros_job_status / \"\n                \"ouroboros_job_wait and read the verdict via ouroboros_job_result. \"\n                \"In plugin mode with auto_evolve disabled, evaluation is delegated \"\n                \"to an OpenCode Task pane and job_id is None. With auto_evolve enabled, \"\n                \"the parent keeps evaluation pollable so a rejection can start Ralph.\"\n            ),\n            parameters=(\n                *EvaluateHandler().definition.parameters,\n                MCPToolParameter(\n                    name=\"auto_evolve\",\n                    type=ToolInputType.BOOLEAN,\n                    description=(\n                        \"Override execution.auto_evolve for this background call. \"\n                        \"When true, an explicitly rejected formal evaluation starts \"\n                        \"a bounded Ralph continuation loop.\"\n                    ),\n                    required=False,\n                ),\n                MCPToolParameter(\n                    name=\"seed_handoff_id\",\n                    type=ToolInputType.STRING,\n                    description=\"Opaque parent-owned Seed handle for plugin evaluation\",\n                    required=False,\n                ),\n            ),\n        )\n\n    async def handle(\n        self,\n        arguments: dict[str, Any],\n    ) -> Result[MCPToolResult, MCPServerError]:\n        session_id = arguments.get(\"session_id\")\n        if not session_id:\n            return Result.err(\n                MCPToolError(\n                    \"session_id is required\",\n                    tool_name=\"ouroboros_start_evaluate\",\n                )\n            )\n        artifact = arguments.get(\"artifact\")\n        if not artifact:\n            return Result.err(\n                MCPToolError(\n                    \"artifact is required\",\n                    tool_name=\"ouroboros_start_evaluate\",\n                )\n            )\n\n        from ouroboros.mcp.tools.evaluation_job import (\n            dispatch_plugin_evaluation,\n            resolve_auto_evolve_policy,\n            restore_seed_handoff,\n        )\n\n        try:\n            arguments, auto_evolve_enabled = resolve_auto_evolve_policy(\n                arguments, configured_enabled=get_auto_evolve_enabled()\n            )\n            plugin_dispatch = should_dispatch_via_plugin(\n                self.agent_runtime_backend, self.opencode_mode\n            )\n            background_acceptance = background_jobs.BackgroundJobAcceptanceState()\n        except ValueError as exc:\n            return Result.err(MCPToolError(str(exc), tool_name=\"ouroboros_start_evaluate\"))\n\n        try:\n            arguments, seed_handoff = restore_seed_handoff(\n                arguments, session_id=session_id, registry=self.seed_handoff_registry\n            )\n        except ValueError as exc:\n            return Result.err(MCPToolError(str(exc), tool_name=\"ouroboros_start_evaluate\"))\n\n        # Plugin mode is terminal only when no convergence successor is needed:\n        # return the delegation envelope without enqueuing a background job,\n        # matching StartExecuteSeedHandler / StartEvolveStepHandler. Polling a\n        # fake job_id would break the ouroboros_job_status contract.\n        if plugin_dispatch and not auto_evolve_enabled:\n            return await seed_handoff.accept(\n                dispatch_plugin_evaluation(\n                    arguments=arguments,\n                    session_id=session_id,\n                    artifact=artifact,\n                    event_store=self._event_store,\n                    resolve_working_dir=_resolve_evaluate_working_dir,\n                ),\n                require_ok=True,\n                acceptance_may_have_occurred=False,\n            )\n\n        # The shared helper preserves job-scoped cancellation across restart.\n        async def _runner(_handle) -> MCPToolResult:\n            from ouroboros.mcp.tools.evaluation_job import run_evaluation_job\n\n            return await run_evaluation_job(\n                evaluate_handler=self._evaluate_handler,\n                arguments=arguments,\n                session_id=session_id,\n                deadline_seconds=self.deadline_seconds,\n                force_in_process=auto_evolve_enabled and plugin_dispatch,\n                auto_evolve=auto_evolve_enabled,\n                event_store=self._event_store,\n                job_manager=self._job_manager,\n                start_ralph_handler=self.start_ralph_handler,\n            )\n\n        snapshot = await seed_handoff.accept(\n            background_jobs.start_background_tool_job(\n                job_manager=self._job_manager,\n                event_store=self._event_store,\n                job_type=\"evaluate\",\n                intent=\"evaluate\",\n                process_scope=f\"evaluate:{session_id}\",\n                initial_message=f\"Queued evaluation for {session_id}\",\n                links=JobLinks(session_id=session_id),\n                work_fn=_runner,\n                cancelled_text=\"Evaluation cancelled before work began.\",\n                detached_tool_name=\"ouroboros_start_evaluate\",\n                detached_arguments=arguments,\n                runtime_backend=self.agent_runtime_backend,\n                llm_backend=self.llm_backend,\n                opencode_mode=self.opencode_mode,\n                acceptance_state=background_acceptance,\n            ),\n            acceptance_may_have_occurred=background_acceptance.may_have_accepted,\n        )\n\n        observer = build_job_observer_contract(\n            job_id=snapshot.job_id,\n            cursor=snapshot.cursor,\n            session_id=session_id,\n            follow_result_job_keys=(\"chained_ralph_job_id\",),\n        )\n        text = (\n            f\"Started background evaluation.\\n\\nJob ID: {snapshot.job_id}\\n\"\n            f\"Session ID: {session_id}\\n\\nUse ouroboros_job_status, ouroboros_job_wait, \"\n            \"or ouroboros_job_result to monitor it.\"\n        )\n        text = append_job_observer_inline_handoff(text, observer)\n        meta = {\n            \"job_id\": snapshot.job_id,\n            \"session_id\": session_id,\n            \"status\": snapshot.status.value,\n            \"cursor\": snapshot.cursor,\n            \"job_observer\": observer,\n        }\n        return Result.ok(\n            MCPToolResult(\n                content=(MCPContentItem(type=ContentType.TEXT, text=text),),\n                is_error=False,\n                meta=meta,\n                structured_content=dict(meta),\n            )\n        )\n"
    },
    {
      "path": "src/ouroboros/evaluation/pipeline.py",
      "content": "\"\"\"Evaluation Pipeline Orchestrator.\n\nOrchestrates the three-stage evaluation pipeline:\n1. Stage 1: Mechanical Verification ($0)\n2. Stage 2: Semantic Evaluation (Standard tier)\n3. Stage 3: Multi-Model Consensus (Frontier tier, if triggered)\n\nThe pipeline respects configuration flags and trigger conditions.\n\nAcceptance authority: only executed Stage 1 evidence can grant approval.\nStage 2 and Stage 3 are advisory; they can withhold approval and supply\nfeedback, never grant it. Without executed evidence the result is\nunverified (see ``AcceptanceState``).\n\"\"\"\n\nfrom dataclasses import dataclass\n\nfrom ouroboros.core.errors import ProviderError, ValidationError\nfrom ouroboros.core.types import Result\nfrom ouroboros.evaluation.consensus import ConsensusConfig, ConsensusEvaluator\nfrom ouroboros.evaluation.mechanical import (\n    MechanicalConfig,\n    MechanicalVerifier,\n)\nfrom ouroboros.evaluation.models import (\n    COMMAND_CHECK_TYPES,\n    ConsensusResult,\n    EvaluationContext,\n    EvaluationResult,\n    MechanicalDisposition,\n    MechanicalResult,\n    SemanticResult,\n    build_failure_reason,\n    decide_final_approval,\n    derive_acceptance_state,\n)\nfrom ouroboros.evaluation.semantic import SemanticConfig, SemanticEvaluator\nfrom ouroboros.evaluation.trigger import (\n    ConsensusTrigger,\n    TriggerConfig,\n    TriggerContext,\n)\nfrom ouroboros.events.base import BaseEvent\nfrom ouroboros.events.evaluation import create_pipeline_completed_event\nfrom ouroboros.providers.base import LLMAdapter\n\n\n@dataclass(frozen=True, slots=True)\nclass PipelineConfig:\n    \"\"\"Configuration for the evaluation pipeline.\n\n    Attributes:\n        stage1_enabled: Run mechanical verification\n        stage2_enabled: Run semantic evaluation\n        stage3_enabled: Allow consensus if triggered\n        mechanical: Stage 1 configuration\n        semantic: Stage 2 configuration\n        consensus: Stage 3 configuration\n        trigger: Trigger matrix configuration\n    \"\"\"\n\n    stage1_enabled: bool = True\n    stage2_enabled: bool = True\n    stage3_enabled: bool = True\n    mechanical: MechanicalConfig | None = None\n    semantic: SemanticConfig | None = None\n    consensus: ConsensusConfig | None = None\n    trigger: TriggerConfig | None = None\n\n\nclass EvaluationPipeline:\n    \"\"\"Orchestrates the three-stage evaluation pipeline.\n\n    Runs stages sequentially, respecting configuration and triggers.\n    Stage 3 is only run if trigger conditions are met.\n\n    Example:\n        pipeline = EvaluationPipeline(llm_adapter, config)\n        result = await pipeline.evaluate(context)\n    \"\"\"\n\n    def __init__(\n        self,\n        llm_adapter: LLMAdapter,\n        config: PipelineConfig | None = None,\n    ) -> None:\n        \"\"\"Initialize pipeline.\n\n        Args:\n            llm_adapter: LLM adapter for semantic and consensus\n            config: Pipeline configuration\n        \"\"\"\n        self._llm = llm_adapter\n        self._config = config or PipelineConfig()\n\n        # Initialize stage evaluators\n        self._mechanical = MechanicalVerifier(self._config.mechanical)\n        self._semantic = SemanticEvaluator(llm_adapter, self._config.semantic)\n        self._consensus = ConsensusEvaluator(llm_adapter, self._config.consensus)\n        self._trigger = ConsensusTrigger(self._config.trigger)\n\n    async def evaluate(\n        self,\n        context: EvaluationContext,\n        trigger_context: TriggerContext | None = None,\n        *,\n        stage1_result: MechanicalResult | None = None,\n    ) -> Result[EvaluationResult, ProviderError | ValidationError]:\n        \"\"\"Run the evaluation pipeline.\n\n        Args:\n            context: Evaluation context with artifact\n            trigger_context: Optional pre-populated trigger context\n            stage1_result: Pre-computed Stage 1 result.  When provided,\n                Stage 1 mechanical verification is skipped and this result\n                is reused.  This allows multi-AC callers to run\n                lint/build/test once and share the outcome across parallel\n                semantic evaluations.\n\n                INVARIANT: Stage 1 checks (lint, build, test, static\n                analysis, coverage) must be AC-agnostic — they verify\n                project-wide code quality, not AC-specific behavior.  The\n                multi-AC checklist path (``_handle_multi_ac`` in\n                ``EvaluateHandler``, introduced in #385) relies on this\n                invariant to run Stage 1 exactly once across all ACs and\n                share the result via this parameter.\n\n                If future Stage 1 additions become AC-specific (e.g.\n                AC-tagged test filtering or per-AC coverage thresholds),\n                this dedup becomes incorrect and the multi-AC caller must\n                be updated to run Stage 1 per AC again.\n\n        Returns:\n            Result containing EvaluationResult or error\n        \"\"\"\n        if context.artifact_bundle is not None and not context.artifact_bundle.scan_complete:\n            return Result.err(\n                ValidationError(\n                    \"Artifact collection is incomplete; evaluation refused to avoid judging a partial workspace scan.\",\n                    field=\"artifact_bundle\",\n                    details={\"scan_error\": context.artifact_bundle.scan_error},\n                )\n            )\n\n        events: list[BaseEvent] = []\n        stage2_result = None\n        stage3_result = None\n\n        # Stage 1: Mechanical Verification\n        # When a pre-computed result is injected, skip re-running the\n        # AC-agnostic lint/build/test checks.\n        if stage1_result is None and self._config.stage1_enabled:\n            result = await self._mechanical.verify(\n                context.execution_id,\n                checks=list(COMMAND_CHECK_TYPES),\n            )\n            if result.is_err:\n                return Result.err(result.error)\n\n            stage1_result, stage1_events = result.value\n            events.extend(stage1_events)\n\n        # What the controller already ran for this criterion (its recorded\n        # check package decision) is executed evidence for this criterion\n        # only; the one classifier decides over it and the command checks.\n        if context.recorded_checks:\n            base = stage1_result or MechanicalResult(passed=True, checks=())\n            stage1_result = base.with_recorded(context.recorded_checks)\n\n        # Only an executed failure stops here. A result with no executed\n        # evidence continues so the advisory review can supply feedback;\n        # the acceptance gate still refuses to approve it.\n        if (\n            stage1_result is not None\n            and stage1_result.disposition is MechanicalDisposition.EXECUTED_FAIL\n        ):\n            return self._build_result(\n                context.execution_id,\n                events,\n                stage1_result=stage1_result,\n            )\n\n        # Stage 2: Semantic Evaluation (advisory). It still runs when Stage 1\n        # produced no executed evidence: its review becomes the feedback that\n        # accompanies an unverified result, not a verdict.\n        if self._config.stage2_enabled:\n            result = await self._semantic.evaluate(context, stage1_result)\n            if result.is_err:\n                return Result.err(result.error)\n\n            stage2_result, stage2_events = result.value\n            events.extend(stage2_events)\n\n            # Stage 2 withheld on compliance. trigger_consensus still asks\n            # Stage 3 for a second opinion that is reported, but a consensus\n            # approval cannot lift this block.\n            if not stage2_result.ac_compliance and not context.trigger_consensus:\n                return self._build_result(\n                    context.execution_id,\n                    events,\n                    stage1_result=stage1_result,\n                    stage2_result=stage2_result,\n                )\n\n        # Build or enrich trigger context — outside Stage 2 block so that\n        # trigger_consensus=True works even when stage2_enabled=False.\n        if trigger_context is None:\n            trigger_context = TriggerContext(\n                execution_id=context.execution_id,\n                semantic_result=stage2_result,\n                manual_consensus_request=context.trigger_consensus,\n            )\n        elif context.trigger_consensus and not trigger_context.manual_consensus_request:\n            # Caller supplied a TriggerContext (e.g. for drift data) but\n            # trigger_consensus was set separately — merge the override.\n            trigger_context = TriggerContext(\n                execution_id=trigger_context.execution_id,\n                seed_modified=trigger_context.seed_modified,\n                ontology_changed=trigger_context.ontology_changed,\n                goal_reinterpreted=trigger_context.goal_reinterpreted,\n                drift_score=trigger_context.drift_score,\n                uncertainty_score=trigger_context.uncertainty_score,\n                lateral_thinking_adopted=trigger_context.lateral_thinking_adopted,\n                semantic_result=trigger_context.semantic_result or stage2_result,\n                manual_consensus_request=True,\n            )\n\n        # Stage 3: Consensus (if triggered)\n        if self._config.stage3_enabled and trigger_context:\n            trigger_result = self._trigger.evaluate(trigger_context)\n            if trigger_result.is_err:\n                return Result.err(trigger_result.error)\n\n            trigger_decision, trigger_events = trigger_result.value\n            events.extend(trigger_events)\n\n            if trigger_decision.should_trigger:\n                trigger_reason = (\n                    trigger_decision.trigger_type.value\n                    if trigger_decision.trigger_type\n                    else \"manual\"\n                )\n                result = await self._consensus.evaluate(context, trigger_reason)\n                if result.is_err:\n                    return Result.err(result.error)\n\n                stage3_result, stage3_events = result.value\n                events.extend(stage3_events)\n\n        return self._build_result(\n            context.execution_id,\n            events,\n            stage1_result=stage1_result,\n            stage2_result=stage2_result,\n            stage3_result=stage3_result,\n        )\n\n    def _build_result(\n        self,\n        execution_id: str,\n        events: list[BaseEvent],\n        stage1_result: MechanicalResult | None = None,\n        stage2_result: SemanticResult | None = None,\n        stage3_result: ConsensusResult | None = None,\n    ) -> Result[EvaluationResult, ValidationError]:\n        \"\"\"Build the final evaluation result.\n\n        Approval is decided here and nowhere else, by\n        ``decide_final_approval``: executed Stage 1 evidence grants it, and\n        any model review that ran (Stage 2 compliance or score, Stage 3\n        consensus, the reward-hacking veto) may withhold it. No caller passes\n        an approval in, so no branch can mint one from a model verdict.\n\n        Args:\n            execution_id: Execution identifier\n            events: Collected events\n            stage1_result: Stage 1 result if completed\n            stage2_result: Stage 2 result if completed\n            stage3_result: Stage 3 result if triggered\n\n        Returns:\n            Result containing EvaluationResult\n        \"\"\"\n        final_approved = decide_final_approval(\n            stage1_result=stage1_result,\n            stage2_result=stage2_result,\n            stage3_result=stage3_result,\n        )\n\n        # Calculate highest stage before creating immutable result\n        highest_stage = 0\n        if stage1_result is not None:\n            highest_stage = 1\n        if stage2_result is not None:\n            highest_stage = 2\n        if stage3_result is not None:\n            highest_stage = 3\n\n        # Calculate failure reason before creating immutable result.  Shared\n        # with ``EvaluationResult.failure_reason`` so the two surfaces cannot\n        # drift: this one is built before the result exists, that one after.\n        failure_reason = build_failure_reason(\n            final_approved=final_approved,\n            stage1_result=stage1_result,\n            stage2_result=stage2_result,\n            stage3_result=stage3_result,\n        )\n\n        # Create completion event\n        completion_event = create_pipeline_completed_event(\n            execution_id=execution_id,\n            final_approved=final_approved,\n            highest_stage=highest_stage,\n            failure_reason=failure_reason,\n            acceptance_state=derive_acceptance_state(\n                final_approved=final_approved,\n                stage1_result=stage1_result,\n            ).value,\n        )\n\n        # Build complete event list before creating frozen result\n        all_events = [*events, completion_event]\n\n        result = EvaluationResult(\n            execution_id=execution_id,\n            stage1_result=stage1_result,\n            stage2_result=stage2_result,\n            stage3_result=stage3_result,\n            final_approved=final_approved,\n            events=all_events,\n        )\n\n        return Result.ok(result)\n\n\nasync def run_evaluation_pipeline(\n    context: EvaluationContext,\n    llm_adapter: LLMAdapter,\n    config: PipelineConfig | None = None,\n    trigger_context: TriggerContext | None = None,\n) -> Result[EvaluationResult, ProviderError | ValidationError]:\n    \"\"\"Convenience function for running the evaluation pipeline.\n\n    Args:\n        context: Evaluation context\n        llm_adapter: LLM adapter\n        config: Optional configuration\n        trigger_context: Optional trigger context\n\n    Returns:\n        Result with EvaluationResult\n    \"\"\"\n    pipeline = EvaluationPipeline(llm_adapter, config)\n    return await pipeline.evaluate(context, trigger_context)\n"
    },
    {
      "path": "src/ouroboros/evaluation/models.py",
      "content": "\"\"\"Data models for the evaluation pipeline.\n\nThis module defines immutable data structures for all three evaluation stages.\nAll models use frozen dataclasses with slots for immutability and performance.\n\nClasses:\n    CheckType: Enum of mechanical check types\n    CheckResult: Single mechanical check result\n    MechanicalResult: Aggregated Stage 1 results\n    SemanticResult: Stage 2 LLM evaluation results\n    Vote: Single model vote in consensus\n    VoterRole: Role in deliberative consensus\n    ConsensusResult: Aggregated Stage 3 results\n    DeliberationResult: Aggregated Stage 3 deliberative results\n    EvaluationContext: Input context for evaluation\n    EvaluationResult: Complete pipeline output\n\"\"\"\n\nfrom collections.abc import Sequence\nfrom dataclasses import dataclass, field\nfrom enum import StrEnum\nfrom typing import Any\n\nfrom ouroboros.core.acceptance import AcceptanceState\nfrom ouroboros.core.seed import AcceptanceCriterionSpec\nfrom ouroboros.events.base import BaseEvent\n\n# Above this reward-hacking risk the final gate vetoes an otherwise-passing\n# artifact.  It is deliberately high (0.7): it only vetoes *high-confidence*\n# gaming signals so a nervous evaluator's mild suspicion never blocks a\n# genuine pass.  Defined here (not in pipeline.py) so the gate and the\n# ``EvaluationResult.failure_reason`` surface share one source of truth\n# without a models<->pipeline import cycle.  pipeline.py imports this.\nREWARD_HACKING_VETO_THRESHOLD = 0.7\n\n# Below this Stage 2 score, semantic review withholds approval.  It never\n# grants approval above it: acceptance requires executed Stage 1 evidence.\n# Shared with ``pipeline.py`` so the gate and the failure reason that has to\n# name it cannot drift apart.\nSEMANTIC_APPROVAL_SCORE = 0.8\n\n\nclass VoterRole(StrEnum):\n    \"\"\"Roles in deliberative consensus.\n\n    Each role has a specific perspective in the 2-round deliberation:\n    - ADVOCATE: Argues in favor, finds strengths\n    - DEVIL: Critical perspective using ontological questions\n    - JUDGE: Weighs both sides, makes final decision\n    \"\"\"\n\n    ADVOCATE = \"advocate\"\n    DEVIL = \"devil\"\n    JUDGE = \"judge\"\n\n\nclass CheckType(StrEnum):\n    \"\"\"Types of mechanical checks in Stage 1.\n\n    Attributes:\n        LINT: Code style and formatting checks\n        BUILD: Compilation and build validation\n        TEST: Unit and integration test execution\n        STATIC: Static analysis (type checking, etc.)\n        COVERAGE: Test coverage threshold verification\n    \"\"\"\n\n    LINT = \"lint\"\n    BUILD = \"build\"\n    TEST = \"test\"\n    STATIC = \"static\"\n    COVERAGE = \"coverage\"\n    CHECK_PACKAGE = \"check_package\"\n    \"\"\"The controller's recorded check package decision for one criterion, not a command.\"\"\"\n\n\nCOMMAND_CHECK_TYPES: tuple[CheckType, ...] = (\n    CheckType.LINT,\n    CheckType.BUILD,\n    CheckType.TEST,\n    CheckType.STATIC,\n    CheckType.COVERAGE,\n)\n\"\"\"The checks Stage 1 runs as project commands; the same for every criterion.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass CheckResult:\n    \"\"\"Result of a single mechanical check.\n\n    Attributes:\n        check_type: Type of check performed\n        passed: Whether the check passed\n        message: Human-readable result message\n        details: Additional check-specific details\n        executed: Whether a configured command was attempted, so that\n            ``passed`` reports its outcome. An unconfigured check is reported\n            as ``passed`` so it does not fail Stage 1, but it is not evidence.\n            Defaults to ``False`` so a check that does not declare execution\n            never counts as evidence.\n    \"\"\"\n\n    check_type: CheckType\n    passed: bool\n    message: str\n    details: dict[str, Any] = field(default_factory=dict)\n    executed: bool = False\n\n\nclass MechanicalDisposition(StrEnum):\n    \"\"\"What a Stage 1 result is evidence of; the one classifier every reader uses.\n\n    Attributes:\n        EXECUTED_PASS: At least one check ran a command and every check passed.\n            The only disposition that can support acceptance.\n        EXECUTED_FAIL: A check that ran a command failed. Authoritative\n            rejection; model review is not consulted.\n        NO_EVIDENCE: No executed check decided anything: every check was\n            skipped, or the only failures were never executed. Not approvable\n            and not a rejection; the outcome is unverified and model review\n            still runs to supply feedback.\n    \"\"\"\n\n    EXECUTED_PASS = \"executed_pass\"\n    EXECUTED_FAIL = \"executed_fail\"\n    NO_EVIDENCE = \"no_evidence\"\n\n\n@dataclass(frozen=True, slots=True)\nclass MechanicalResult:\n    \"\"\"Aggregated result of Stage 1 mechanical verification.\n\n    All checks must pass for the overall result to pass.\n    Coverage score is tracked separately for NFR9 compliance.\n\n    Attributes:\n        passed: True if all checks passed\n        checks: Tuple of individual check results\n        coverage_score: Test coverage percentage (0.0-1.0), None if not measured\n    \"\"\"\n\n    passed: bool\n    checks: tuple[CheckResult, ...]\n    coverage_score: float | None = None\n\n    def __post_init__(self) -> None:\n        \"\"\"Reconcile the aggregate verdict with its checks, fail-closed.\n\n        ``passed`` duplicates what the checks already say, and a directly\n        constructed or rehydrated result can make the two disagree. The\n        aggregate may only claim a pass that every check confirms with a\n        literal ``True``; any disagreement resolves to not passed, so no\n        reader (the pipeline's Stage 1 gate, the acceptance gate, failure\n        reasons) can see an executed failing check as a pass.\n        \"\"\"\n        reconciled = self.passed is True and all(c.passed is True for c in self.checks)\n        if reconciled is not self.passed:\n            object.__setattr__(self, \"passed\", reconciled)\n\n    @property\n    def failed_checks(self) -> tuple[CheckResult, ...]:\n        \"\"\"Return only the checks that did not report a literal pass.\"\"\"\n        return tuple(c for c in self.checks if c.passed is not True)\n\n    @property\n    def executed_checks(self) -> tuple[CheckResult, ...]:\n        \"\"\"Return only the checks whose configured command actually ran.\"\"\"\n        return tuple(c for c in self.checks if c.executed is True)\n\n    @property\n    def executed_failures(self) -> tuple[CheckResult, ...]:\n        \"\"\"Return the checks that ran a command and did not pass.\"\"\"\n        return tuple(c for c in self.failed_checks if c.executed is True)\n\n    @property\n    def disposition(self) -> MechanicalDisposition:\n        \"\"\"Classify this result once, for the pipeline and every projection.\n\n        An executed failure rejects. A pass counts only when every check\n        passed and at least one ran a command (a skipped check reports\n        ``passed`` but is not evidence). Everything else, including a failure\n        that was never executed, is no evidence.\n        \"\"\"\n        if self.executed_failures:\n            return MechanicalDisposition.EXECUTED_FAIL\n        if self.passed and self.executed_checks:\n            return MechanicalDisposition.EXECUTED_PASS\n        return MechanicalDisposition.NO_EVIDENCE\n\n    def with_recorded(self, recorded: tuple[CheckResult, ...]) -> \"MechanicalResult\":\n        \"\"\"This result plus checks the controller already ran for one criterion.\n\n        ``recorded`` holds ``CHECK_PACKAGE`` results only; the one classifier\n        (``disposition``) then decides over the command checks and them alike.\n        \"\"\"\n        if any(check.check_type is not CheckType.CHECK_PACKAGE for check in recorded):\n            raise ValueError(\"only check package results are recorded evidence\")\n        checks = self.command_checks().checks + recorded\n        return MechanicalResult(\n            passed=all(check.passed is True for check in checks),\n            checks=checks,\n            coverage_score=self.coverage_score,\n        )\n\n    def command_checks(self) -> \"MechanicalResult\":\n        \"\"\"This result without recorded criterion evidence: what every criterion shares.\"\"\"\n        checks = tuple(c for c in self.checks if c.check_type is not CheckType.CHECK_PACKAGE)\n        return MechanicalResult(\n            passed=all(check.passed is True for check in checks),\n            checks=checks,\n            coverage_score=self.coverage_score,\n        )\n\n    @property\n    def has_executed_evidence(self) -> bool:\n        \"\"\"Whether Stage 1 is executed verification evidence for acceptance.\"\"\"\n        return self.disposition is MechanicalDisposition.EXECUTED_PASS\n\n\n@dataclass(frozen=True, slots=True)\nclass SemanticResult:\n    \"\"\"Result of Stage 2 semantic evaluation.\n\n    Uses LLM to evaluate AC compliance, goal alignment, drift, and\n    reward-hacking risk.  Uncertainty score determines if Stage 3\n    consensus is needed.\n\n    Attributes:\n        score: Overall evaluation score (0.0-1.0)\n        ac_compliance: Whether acceptance criteria are met\n        goal_alignment: Alignment with original goal (0.0-1.0)\n        drift_score: Deviation from seed intent (0.0-1.0, lower is better)\n        uncertainty: Model uncertainty about evaluation (0.0-1.0)\n        reasoning: Explanation of the evaluation\n        reward_hacking_risk: Suspicion that the artifact games the\n            evaluator rather than solving the real task (0.0-1.0).\n            Distinct from drift_score.\n        questions_used: Socratic / ontology-gap questions the evaluator\n            actually asked while verifying the artifact.  Exposing these\n            to the user is an anti-reward-hacking mechanism (#367) —\n            the evaluator has to show its work.\n        evidence: Concrete evidence (file snippets, behavior observations,\n            etc.) the evaluator relied on when deciding the verdict.\n    \"\"\"\n\n    score: float\n    ac_compliance: bool\n    goal_alignment: float\n    drift_score: float\n    uncertainty: float\n    reasoning: str\n    reward_hacking_risk: float = 0.0\n    questions_used: tuple[str, ...] = ()\n    evidence: tuple[str, ...] = ()\n\n    def __post_init__(self) -> None:\n        \"\"\"Validate score ranges.\"\"\"\n        for attr in (\n            \"score\",\n            \"goal_alignment\",\n            \"drift_score\",\n            \"uncertainty\",\n            \"reward_hacking_risk\",\n        ):\n            value = getattr(self, attr)\n            if not 0.0 <= value <= 1.0:\n                msg = f\"{attr} must be between 0.0 and 1.0, got {value}\"\n                raise ValueError(msg)\n\n\n@dataclass(frozen=True, slots=True)\nclass Vote:\n    \"\"\"Single model vote in Stage 3 consensus.\n\n    Attributes:\n        model: Model identifier that cast the vote\n        approved: Whether the model approves the output\n        confidence: Model's confidence in its decision (0.0-1.0)\n        reasoning: Explanation of the vote\n        role: Role in deliberative consensus (optional, for deliberative mode)\n    \"\"\"\n\n    model: str\n    approved: bool\n    confidence: float\n    reasoning: str\n    role: VoterRole | None = None\n\n    def __post_init__(self) -> None:\n        \"\"\"Validate confidence range.\"\"\"\n        if not 0.0 <= self.confidence <= 1.0:\n            msg = f\"confidence must be between 0.0 and 1.0, got {self.confidence}\"\n            raise ValueError(msg)\n\n\n@dataclass(frozen=True, slots=True)\nclass ConsensusResult:\n    \"\"\"Aggregated result of Stage 3 multi-model consensus.\n\n    Requires 2/3 majority for approval with minimum 3 models.\n\n    Attributes:\n        approved: True if consensus reached approval\n        votes: Tuple of individual model votes\n        majority_ratio: Ratio of approving votes (0.0-1.0)\n        disagreements: Tuple of reasoning strings from dissenting votes\n    \"\"\"\n\n    approved: bool\n    votes: tuple[Vote, ...]\n    majority_ratio: float\n    disagreements: tuple[str, ...] = ()\n    is_single_model: bool = False\n    # PR-X X2: honest label of executor/reviewer independence\n    # (\"independent\" | \"same_vendor\" | \"unavailable\" | \"unverified\" |\n    # None when not resolved). See evaluation.reviewer_independence.\n    reviewer_independence: str | None = None\n\n    @property\n    def approving_votes(self) -> int:\n        \"\"\"Count of votes that approved.\"\"\"\n        return sum(1 for v in self.votes if v.approved)\n\n    @property\n    def total_votes(self) -> int:\n        \"\"\"Total number of votes cast.\"\"\"\n        return len(self.votes)\n\n\nclass FinalVerdict(StrEnum):\n    \"\"\"Final verdict from Judge in deliberative consensus.\"\"\"\n\n    APPROVED = \"approved\"\n    REJECTED = \"rejected\"\n    CONDITIONAL = \"conditional\"\n\n\n@dataclass(frozen=True, slots=True)\nclass JudgmentResult:\n    \"\"\"Result from the Judge in deliberative consensus.\n\n    Attributes:\n        verdict: Final decision (approved/rejected/conditional)\n        confidence: Judge's confidence in decision (0.0-1.0)\n        reasoning: Explanation of the judgment\n        conditions: Conditions for approval (if conditional)\n    \"\"\"\n\n    verdict: FinalVerdict\n    confidence: float\n    reasoning: str\n    conditions: tuple[str, ...] | None = None\n\n    def __post_init__(self) -> None:\n        \"\"\"Validate confidence range.\"\"\"\n        if not 0.0 <= self.confidence <= 1.0:\n            msg = f\"confidence must be between 0.0 and 1.0, got {self.confidence}\"\n            raise ValueError(msg)\n\n\n@dataclass(frozen=True, slots=True)\nclass DeliberationResult:\n    \"\"\"Result of 2-round deliberative consensus.\n\n    Round 1: Advocate and Devil's Advocate present positions\n    Round 2: Judge reviews both and makes final decision\n\n    Attributes:\n        final_verdict: The Judge's final decision\n        advocate_position: The Advocate's vote and reasoning\n        devil_position: The Devil's Advocate vote and reasoning\n        judgment: The Judge's full judgment\n        is_root_solution: Whether Devil confirmed this addresses root cause\n    \"\"\"\n\n    final_verdict: FinalVerdict\n    advocate_position: Vote\n    devil_position: Vote\n    judgment: JudgmentResult\n    is_root_solution: bool\n\n    @property\n    def approved(self) -> bool:\n        \"\"\"Whether the final verdict is approval.\"\"\"\n        return self.final_verdict == FinalVerdict.APPROVED\n\n    @property\n    def has_conditions(self) -> bool:\n        \"\"\"Whether approval is conditional.\"\"\"\n        return self.final_verdict == FinalVerdict.CONDITIONAL\n\n\n@dataclass(frozen=True, slots=True)\nclass FileArtifact:\n    \"\"\"A single file collected from execution output.\n\n    Attributes:\n        file_path: Absolute path to the file\n        content: File content (may be truncated)\n        ac_indices: Which ACs modified this file\n        truncated: Whether content was truncated to fit token budget\n    \"\"\"\n\n    file_path: str\n    content: str\n    ac_indices: tuple[int, ...] = ()\n    truncated: bool = False\n\n\n@dataclass(frozen=True, slots=True)\nclass ArtifactBundle:\n    \"\"\"Bundle of file artifacts collected from execution.\n\n    Provides actual source code to the semantic evaluator instead of\n    relying solely on agent text summaries.\n\n    Attributes:\n        files: Collected file artifacts\n        text_summary: Original text summary (backward compat)\n        total_chars: Total characters across all files\n    \"\"\"\n\n    files: tuple[FileArtifact, ...] = ()\n    text_summary: str = \"\"\n    total_chars: int = 0\n    scan_complete: bool = True\n    scan_error: str | None = None\n\n\n@dataclass(frozen=True, slots=True)\nclass EvaluationContext:\n    \"\"\"Input context for the evaluation pipeline.\n\n    Attributes:\n        execution_id: Unique identifier for the execution\n        seed_id: Identifier of the seed being evaluated against\n        current_ac: The acceptance criterion being evaluated\n        current_ac_spec: Structured success contract for ``current_ac`` when\n            the seed declared one (verify_command / expected_artifacts /\n            output_assertion).  ``None`` for bare-string ACs — the evaluator\n            then falls back to judging ``current_ac`` text alone (today's\n            behavior).\n        artifact: The output artifact to evaluate\n        artifact_type: Type of artifact (code, document, etc.)\n        goal: Original goal from seed\n        constraints: Constraints from seed\n        artifact_bundle: Optional file-based artifacts for richer evaluation\n    \"\"\"\n\n    execution_id: str\n    seed_id: str\n    current_ac: str\n    artifact: str\n    current_ac_spec: AcceptanceCriterionSpec | None = None\n    artifact_type: str = \"code\"\n    goal: str = \"\"\n    constraints: tuple[str, ...] = ()\n    artifact_bundle: ArtifactBundle | None = None\n    trigger_consensus: bool = False\n    # PR-X X2: the runtime backend that produced ``artifact``, when known. Lets\n    # consensus keep the executor's own vendor out of the reviewer jury. ``None``\n    # (the default) means \"unknown\" — today's behavior, no independence binding.\n    executor_backend: str | None = None\n    # Checks the controller already ran for ``current_ac`` (its recorded check\n    # package decision, ``CheckType.CHECK_PACKAGE``). Stage 1 adds them to the\n    # project command checks for this criterion only.\n    recorded_checks: tuple[CheckResult, ...] = ()\n\n\n@dataclass(frozen=True, slots=True)\nclass EvaluationResult:\n    \"\"\"Complete evaluation pipeline result.\n\n    Contains results from all stages that were executed,\n    final approval status, and generated events for audit trail.\n\n    Attributes:\n        execution_id: Execution identifier for tracing\n        stage1_result: Mechanical verification result (if executed)\n        stage2_result: Semantic evaluation result (if executed)\n        stage3_result: Consensus result (if triggered)\n        final_approved: Overall approval status\n        events: List of events generated during evaluation\n    \"\"\"\n\n    execution_id: str\n    stage1_result: MechanicalResult | None = None\n    stage2_result: SemanticResult | None = None\n    stage3_result: ConsensusResult | None = None\n    final_approved: bool = False\n    events: list[BaseEvent] = field(default_factory=list)\n\n    @property\n    def highest_stage_completed(self) -> int:\n        \"\"\"Return the highest stage number that completed.\"\"\"\n        if self.stage3_result is not None:\n            return 3\n        if self.stage2_result is not None:\n            return 2\n        if self.stage1_result is not None:\n            return 1\n        return 0\n\n    @property\n    def has_executed_evidence(self) -> bool:\n        \"\"\"Whether Stage 1 produced executed verification evidence.\"\"\"\n        return self.stage1_result is not None and self.stage1_result.has_executed_evidence\n\n    @property\n    def acceptance_state(self) -> AcceptanceState:\n        \"\"\"Return whether this result is approved, rejected, or unverified.\"\"\"\n        return derive_acceptance_state(\n            final_approved=self.final_approved,\n            stage1_result=self.stage1_result,\n        )\n\n    @property\n    def failure_reason(self) -> str | None:\n        \"\"\"Return the reason for failure, if any.\"\"\"\n        return build_failure_reason(\n            final_approved=self.final_approved,\n            stage1_result=self.stage1_result,\n            stage2_result=self.stage2_result,\n            stage3_result=self.stage3_result,\n        )\n\n\ndef model_review_withhold_reason(\n    *,\n    stage2_result: SemanticResult | None,\n    stage3_result: ConsensusResult | None,\n) -> str | None:\n    \"\"\"Return why model review withheld approval, or ``None`` if it did not.\n\n    Model review (Stage 2 semantic, Stage 3 consensus, and the reward-hacking\n    veto) is advisory: it can withhold approval and explain why, but it can\n    never grant acceptance. Every stage that ran is consulted and any one of\n    them withholding settles it; a Stage 3 approval does not lift a Stage 2\n    block. The first withholding gate is named, in the order below.\n    \"\"\"\n    if stage3_result is not None and not stage3_result.approved:\n        return f\"Stage 3 failed: Consensus not reached ({stage3_result.majority_ratio:.0%})\"\n    if stage2_result is not None and not stage2_result.ac_compliance:\n        return (\n            \"Stage 2 failed: AC non-compliance \"\n            f\"(ac_compliance=false; semantic score {stage2_result.score:.2f} \"\n            \"did not gate this)\"\n        )\n    if stage2_result is not None and stage2_result.score < SEMANTIC_APPROVAL_SCORE:\n        return (\n            \"Stage 2 failed: semantic score \"\n            f\"{stage2_result.score:.2f} < {SEMANTIC_APPROVAL_SCORE:.2f} \"\n            \"(ac_compliance=true; the score gate decided this)\"\n        )\n    if (\n        stage2_result is not None\n        and stage2_result.reward_hacking_risk >= REWARD_HACKING_VETO_THRESHOLD\n    ):\n        return (\n            \"Stage 2 veto: reward-hacking risk \"\n            f\"{stage2_result.reward_hacking_risk:.2f} >= \"\n            f\"{REWARD_HACKING_VETO_THRESHOLD:.2f}; artifact appears optimized to game the \"\n            \"evaluator rather than solve the real task\"\n        )\n    return None\n\n\ndef decide_final_approval(\n    *,\n    stage1_result: MechanicalResult | None,\n    stage2_result: SemanticResult | None,\n    stage3_result: ConsensusResult | None,\n) -> bool:\n    \"\"\"The single acceptance gate: executed evidence grants, model review withholds.\n\n    Approval requires Stage 1 to have run at least one configured check with\n    every check passing. Model review that ran may withhold that approval;\n    no model verdict can supply it.\n    \"\"\"\n    if stage1_result is None or not stage1_result.has_executed_evidence:\n        return False\n    return (\n        model_review_withhold_reason(\n            stage2_result=stage2_result,\n            stage3_result=stage3_result,\n        )\n        is None\n    )\n\n\ndef derive_acceptance_state(\n    *,\n    final_approved: bool,\n    stage1_result: MechanicalResult | None,\n) -> AcceptanceState:\n    \"\"\"Classify an evaluation outcome for callers and feedback loops.\"\"\"\n    if final_approved:\n        return AcceptanceState.APPROVED\n    if stage1_result is None:\n        return AcceptanceState.UNVERIFIED\n    disposition = stage1_result.disposition\n    if disposition is MechanicalDisposition.NO_EVIDENCE:\n        return AcceptanceState.UNVERIFIED\n    # EXECUTED_FAIL, or EXECUTED_PASS that model review withheld.\n    return AcceptanceState.REJECTED\n\n\ndef aggregate_acceptance_state(states: Sequence[AcceptanceState]) -> AcceptanceState:\n    \"\"\"The run's state from its criteria' states (each from ``derive_acceptance_state``).\n\n    Approved only when every criterion is; rejected when any criterion was\n    rejected on executed evidence or model review; otherwise unverified.\n    \"\"\"\n    if states and all(state is AcceptanceState.APPROVED for state in states):\n        return AcceptanceState.APPROVED\n    if any(state is AcceptanceState.REJECTED for state in states):\n        return AcceptanceState.REJECTED\n    return AcceptanceState.UNVERIFIED\n\n\ndef build_failure_reason(\n    *,\n    final_approved: bool,\n    stage1_result: MechanicalResult | None,\n    stage2_result: SemanticResult | None,\n    stage3_result: ConsensusResult | None,\n) -> str | None:\n    \"\"\"Return why an evaluation was not approved, or ``None`` when it was.\n\n    A failed executed check is named first because it is the decisive\n    evidence. Without executed evidence the result is unverified, and the\n    reason says so before appending whatever model review concluded, so the\n    feedback is not mistaken for a verdict. With executed evidence that\n    passed, the withholding model gate is named.\n    \"\"\"\n    if final_approved:\n        return None\n    disposition = stage1_result.disposition if stage1_result is not None else None\n    if stage1_result is not None and disposition is MechanicalDisposition.EXECUTED_FAIL:\n        failed = stage1_result.executed_failures\n        return f\"Stage 1 failed: {', '.join(c.check_type for c in failed)}\"\n\n    model_reason = model_review_withhold_reason(\n        stage2_result=stage2_result,\n        stage3_result=stage3_result,\n    )\n    if stage1_result is None or disposition is MechanicalDisposition.NO_EVIDENCE:\n        if stage1_result is None:\n            missing = \"Stage 1 did not run\"\n        elif stage1_result.failed_checks:\n            missing = \"Stage 1 reported failures from no executed check\"\n        else:\n            missing = \"Stage 1 ran no configured check\"\n        reason = f\"Not approved: unverified. No executed verification evidence ({missing}).\"\n        if model_reason is not None:\n            return f\"{reason} Advisory model review also withheld approval: {model_reason}\"\n        if stage2_result is not None or stage3_result is not None:\n            return (\n                f\"{reason} Advisory model review raised no objection, but cannot grant acceptance.\"\n            )\n        return reason\n    return model_reason or \"Unknown failure\"\n"
    },
    {
      "path": "src/ouroboros/evaluation/mechanical.py",
      "content": "\"\"\"Stage 1: Mechanical Verification.\n\nZero-cost verification through automated checks:\n- Lint: Code style and formatting\n- Build: Compilation validation\n- Test: Unit/integration test execution\n- Static: Static analysis (type checking)\n- Coverage: Test coverage threshold (NFR9 >= 0.7)\n\nThe MechanicalVerifier is stateless and produces immutable results.\n\"\"\"\n\nimport asyncio\nfrom dataclasses import dataclass\nimport os\nfrom pathlib import Path\nfrom typing import Any\n\nfrom ouroboros.core.errors import ValidationError\nfrom ouroboros.core.project_env import with_project_venv\nfrom ouroboros.core.types import Result\nfrom ouroboros.evaluation.command_dispatch import prepare_command\nfrom ouroboros.evaluation.models import (\n    COMMAND_CHECK_TYPES,\n    CheckResult,\n    CheckType,\n    MechanicalResult,\n)\nfrom ouroboros.events.base import BaseEvent\nfrom ouroboros.events.evaluation import (\n    create_stage1_completed_event,\n    create_stage1_started_event,\n)\n\n_COMMAND_OUTPUT_PREVIEW_CHARS = 500\n\n\ndef _output_preview(text: str) -> str:\n    \"\"\"Return a compact preview from the leading portion of command output.\n\n    The diagnostically useful tail is captured separately by ``_output_tail``.\n    \"\"\"\n    if not text:\n        return \"\"\n    if len(text) <= _COMMAND_OUTPUT_PREVIEW_CHARS:\n        return text\n    return text[:_COMMAND_OUTPUT_PREVIEW_CHARS]\n\n\ndef _output_tail(text: str) -> str:\n    \"\"\"Return the tail of command output where test failures usually appear.\"\"\"\n    if not text:\n        return \"\"\n    if len(text) <= _COMMAND_OUTPUT_PREVIEW_CHARS:\n        return text\n    return text[-_COMMAND_OUTPUT_PREVIEW_CHARS:]\n\n\n@dataclass(frozen=True, slots=True)\nclass MechanicalConfig:\n    \"\"\"Configuration for mechanical verification.\n\n    Attributes:\n        coverage_threshold: Minimum coverage required (default 0.7 per NFR9)\n        lint_command: Command to run linting\n        build_command: Command to run build\n        test_command: Command to run tests\n        static_command: Command to run static analysis\n        timeout_seconds: Timeout for each command\n        working_dir: Working directory for commands\n    \"\"\"\n\n    coverage_threshold: float = 0.7\n    lint_command: tuple[str, ...] | None = None\n    build_command: tuple[str, ...] | None = None\n    test_command: tuple[str, ...] | None = None\n    static_command: tuple[str, ...] | None = None\n    coverage_command: tuple[str, ...] | None = None\n    timeout_seconds: int = 300\n    working_dir: Path | None = None\n\n\n@dataclass(frozen=True, slots=True)\nclass CommandResult:\n    \"\"\"Result of running a shell command.\n\n    Attributes:\n        return_code: Exit code of the command\n        stdout: Standard output\n        stderr: Standard error\n        timed_out: Whether the command timed out\n        executed_command: Arguments passed to the subprocess launcher, when attempted\n    \"\"\"\n\n    return_code: int\n    stdout: str\n    stderr: str\n    timed_out: bool = False\n    executed_command: tuple[str, ...] | None = None\n\n\nasync def run_command(\n    command: tuple[str, ...],\n    timeout: int,\n    working_dir: Path | None = None,\n) -> CommandResult:\n    \"\"\"Run a shell command asynchronously.\n\n    Args:\n        command: Command and arguments to run\n        timeout: Timeout in seconds\n        working_dir: Working directory\n\n    Returns:\n        CommandResult with output and status\n    \"\"\"\n    # The detector accepts a tool the project's virtualenv provides, which a\n    # task worktree reaches only through the main working tree's, so the\n    # command resolves it the same way.\n    env = os.environ.copy() if working_dir is None else with_project_venv(os.environ, working_dir)\n    # The MCP server sets this sentinel to prevent recursive server spawning.\n    # Mechanical verification must test the repository as a fresh process would;\n    # leaking the sentinel makes CLI tests take the nested-server early exit.\n    env.pop(\"_OUROBOROS_NESTED\", None)\n    try:\n        prepared_command = prepare_command(command, env)\n    except ValueError as e:\n        return CommandResult(return_code=-1, stdout=\"\", stderr=str(e))\n    try:\n        process = await asyncio.create_subprocess_exec(\n            *prepared_command,\n            stdout=asyncio.subprocess.PIPE,\n            stderr=asyncio.subprocess.PIPE,\n            cwd=working_dir,\n            env=env,\n        )\n\n        try:\n            stdout, stderr = await asyncio.wait_for(\n                process.communicate(),\n                timeout=timeout,\n            )\n            return CommandResult(\n                return_code=process.returncode or 0,\n                stdout=stdout.decode(\"utf-8\", errors=\"replace\"),\n                stderr=stderr.decode(\"utf-8\", errors=\"replace\"),\n                executed_command=prepared_command,\n            )\n        except TimeoutError:\n            process.kill()\n            await process.wait()\n            return CommandResult(\n                return_code=-1,\n                stdout=\"\",\n                stderr=\"Command timed out\",\n                timed_out=True,\n                executed_command=prepared_command,\n            )\n        except asyncio.CancelledError:\n            if process.returncode is None:\n                process.kill()\n                await process.wait()\n            raise\n    except FileNotFoundError as e:\n        return CommandResult(\n            return_code=-1,\n            stdout=\"\",\n            stderr=f\"Command not found: {e}\",\n            executed_command=prepared_command,\n        )\n    except OSError as e:\n        return CommandResult(\n            return_code=-1,\n            stdout=\"\",\n            stderr=f\"OS error: {e}\",\n            executed_command=prepared_command,\n        )\n\n\ndef parse_coverage_from_output(output: str) -> float | None:\n    \"\"\"Extract coverage percentage from pytest-cov output.\n\n    Args:\n        output: stdout from coverage command\n\n    Returns:\n        Coverage as float (0.0-1.0) or None if not found\n    \"\"\"\n    # Look for \"TOTAL ... XX%\" pattern\n    import re\n\n    # Pattern matches lines like \"TOTAL   1234   123  90%\"\n    pattern = r\"[ \\t]*TOTAL[ \\t]+\\d+[ \\t]+\\d+[ \\t]+(\\d+)%[ \\t]*\"\n    # Alternative pattern: a line that starts with \"Coverage: XX%\". Anchored so\n    # a requirement such as \"Required Coverage: 70%\" is not read as a result.\n    alt_pattern = r\"[ \\t]*Coverage:[ \\t]*(\\d+(?:\\.\\d+)?)%[ \\t]*\"\n\n    # Every TOTAL row is a figure from the report. One in a shape the pattern\n    # cannot read (decimals, branch columns) makes the report ambiguous, so no\n    # other row or \"Coverage:\" line may stand in for it.\n    total_rows = [row for row in output.splitlines() if re.match(r\"[ \\t]*TOTAL\\b\", row)]\n    # A numeric, punctuation-led or empty Coverage body is a measurement candidate,\n    # even with missing/malformed separators, numbers or units. Alphabetic prose\n    # remains nonmeasurement; only alt_pattern can grant a supported reading.\n    candidate_pattern = r\"[ \\t]*Coverage[ \\t]*(?:$|\\d|[^\\w\\s]|(?i:nan|inf(?:inity)?|percent)\\b)\"\n    coverage_rows = [row for row in output.splitlines() if re.match(candidate_pattern, row)]\n    matches = [re.fullmatch(pattern, row) for row in total_rows]\n    matches += [re.fullmatch(alt_pattern, row) for row in coverage_rows]\n    if not all(matches):\n        return None\n    readings = [match.group(1) for match in matches if match]\n    values = {float(reading) for reading in readings}\n    # More than one distinct figure, or a figure no tool can report, is not a\n    # measurement: return None so the threshold stays undecided.\n    if len(values) != 1:\n        return None\n    (value,) = values\n    if value > 100.0:\n        return None\n    return value / 100.0\n\n\nclass MechanicalVerifier:\n    \"\"\"Stage 1 mechanical verification executor.\n\n    Runs zero-cost automated checks on artifacts.\n    Stateless - all state passed via parameters.\n\n    Example:\n        verifier = MechanicalVerifier(config)\n        result = await verifier.verify(execution_id, checks=[CheckType.LINT, CheckType.TEST])\n    \"\"\"\n\n    def __init__(self, config: MechanicalConfig | None = None) -> None:\n        \"\"\"Initialize verifier with configuration.\n\n        Args:\n            config: Verification configuration, uses defaults if None\n        \"\"\"\n        self.config = config or MechanicalConfig()\n\n    async def verify(\n        self,\n        execution_id: str,\n        checks: list[CheckType] | None = None,\n    ) -> Result[tuple[MechanicalResult, list[BaseEvent]], ValidationError]:\n        \"\"\"Run mechanical verification checks.\n\n        Args:\n            execution_id: Execution identifier for events\n            checks: List of checks to run, defaults to all\n\n        Returns:\n            Result containing MechanicalResult and events, or error\n        \"\"\"\n        if checks is None:\n            checks = list(COMMAND_CHECK_TYPES)\n\n        events: list[BaseEvent] = []\n        check_results: list[CheckResult] = []\n        coverage_score: float | None = None\n\n        # Emit start event\n        events.append(\n            create_stage1_started_event(\n                execution_id=execution_id,\n                checks_to_run=[c.value for c in checks],\n            )\n        )\n\n        # Run each check\n        for check_type in checks:\n            result = await self._run_check(check_type)\n            check_results.append(result)\n\n            # Track coverage if it was a coverage check\n            if check_type == CheckType.COVERAGE and result.passed:\n                coverage_score = result.details.get(\"coverage_score\")\n\n        # Determine overall pass/fail\n        all_passed = all(c.passed for c in check_results)\n\n        # Verify coverage threshold if coverage was checked\n        if coverage_score is not None and coverage_score < self.config.coverage_threshold:\n            # Find and update coverage check to failed\n            updated_results = []\n            for cr in check_results:\n                if cr.check_type == CheckType.COVERAGE:\n                    updated_results.append(\n                        CheckResult(\n                            check_type=CheckType.COVERAGE,\n                            passed=False,\n                            message=f\"Coverage {coverage_score:.1%} below threshold {self.config.coverage_threshold:.1%}\",\n                            details=cr.details,\n                            executed=cr.executed,\n                        )\n                    )\n                else:\n                    updated_results.append(cr)\n            check_results = updated_results\n            all_passed = False\n\n        mechanical_result = MechanicalResult(\n            passed=all_passed,\n            checks=tuple(check_results),\n            coverage_score=coverage_score,\n        )\n\n        # Emit completion event\n        events.append(\n            create_stage1_completed_event(\n                execution_id=execution_id,\n                passed=all_passed,\n                checks=[\n                    {\n                        \"check_type\": c.check_type.value,\n                        \"passed\": c.passed,\n                        \"message\": c.message,\n                    }\n                    for c in check_results\n                ],\n                coverage_score=coverage_score,\n            )\n        )\n\n        return Result.ok((mechanical_result, events))\n\n    async def _run_check(self, check_type: CheckType) -> CheckResult:\n        \"\"\"Run a single check.\n\n        Args:\n            check_type: Type of check to run\n\n        Returns:\n            CheckResult with pass/fail status\n        \"\"\"\n        command = self._get_command_for_check(check_type)\n        if command is None:\n            return CheckResult(\n                check_type=check_type,\n                passed=True,\n                message=f\"Check {check_type.value} skipped (no command configured)\",\n                details={\"skipped\": True},\n                executed=False,\n            )\n\n        cmd_result = await run_command(\n            command,\n            timeout=self.config.timeout_seconds,\n            working_dir=self.config.working_dir,\n        )\n\n        if cmd_result.timed_out:\n            return CheckResult(\n                check_type=check_type,\n                passed=False,\n                message=f\"Check {check_type.value} timed out after {self.config.timeout_seconds}s\",\n                executed=True,\n                details={\n                    \"timed_out\": True,\n                    \"command\": list(command),\n                    **(\n                        {\"executed_command\": list(cmd_result.executed_command)}\n                        if cmd_result.executed_command is not None\n                        else {}\n                    ),\n                    \"working_dir\": str(self.config.working_dir)\n                    if self.config.working_dir\n                    else None,\n                },\n            )\n\n        passed = cmd_result.return_code == 0\n        details: dict[str, Any] = {\n            \"command\": list(command),\n            \"working_dir\": str(self.config.working_dir) if self.config.working_dir else None,\n            \"return_code\": cmd_result.return_code,\n            \"stdout_preview\": _output_preview(cmd_result.stdout),\n            \"stderr_preview\": _output_preview(cmd_result.stderr),\n            \"stdout_tail\": _output_tail(cmd_result.stdout),\n            \"stderr_tail\": _output_tail(cmd_result.stderr),\n        }\n        if cmd_result.executed_command is not None:\n            details[\"executed_command\"] = list(cmd_result.executed_command)\n\n        # Extract coverage if this was a coverage check\n        if check_type == CheckType.COVERAGE and passed:\n            coverage = parse_coverage_from_output(cmd_result.stdout)\n            if coverage is None and self.config.coverage_threshold != 0.0:\n                # The exit code says the command ran, not that coverage met the\n                # threshold. Without a figure the threshold is undecided: not a\n                # pass, and not an executed failure that would claim a measurement.\n                return CheckResult(\n                    check_type=check_type,\n                    passed=False,\n                    message=(\n                        \"Coverage command exited 0 but no coverage figure could be read \"\n                        f\"from its output; threshold {self.config.coverage_threshold:.1%} \"\n                        \"not verified\"\n                    ),\n                    details={**details, \"coverage_unparsed\": True},\n                    executed=False,\n                )\n            if coverage is not None:\n                details[\"coverage_score\"] = coverage\n\n        message = (\n            f\"Check {check_type.value} passed\"\n            if passed\n            else f\"Check {check_type.value} failed (exit code {cmd_result.return_code})\"\n        )\n\n        return CheckResult(\n            check_type=check_type,\n            passed=passed,\n            message=message,\n            details=details,\n            executed=True,\n        )\n\n    def _get_command_for_check(self, check_type: CheckType) -> tuple[str, ...] | None:\n        \"\"\"Get the command for a specific check type.\n\n        Args:\n            check_type: Type of check\n\n        Returns:\n            Command tuple or None if not configured\n        \"\"\"\n        commands = {\n            CheckType.LINT: self.config.lint_command,\n            CheckType.BUILD: self.config.build_command,\n            CheckType.TEST: self.config.test_command,\n            CheckType.STATIC: self.config.static_command,\n            CheckType.COVERAGE: self.config.coverage_command,\n        }\n        return commands.get(check_type)\n\n\nasync def run_mechanical_verification(\n    execution_id: str,\n    config: MechanicalConfig | None = None,\n    checks: list[CheckType] | None = None,\n) -> Result[tuple[MechanicalResult, list[BaseEvent]], ValidationError]:\n    \"\"\"Convenience function for running mechanical verification.\n\n    Args:\n        execution_id: Execution identifier\n        config: Optional configuration\n        checks: Optional list of checks to run\n\n    Returns:\n        Result with MechanicalResult and events\n    \"\"\"\n    verifier = MechanicalVerifier(config)\n    return await verifier.verify(execution_id, checks)\n"
